__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Guardián del Secreto, ¿puedo preguntar cuándo podré visitar el cementerio de la academia? ¡Las grandes almas que están enterradas allí seguramente me brindarán una inspiración extraordinaria! No te preocupes, prometo que no volveré a desenterrar esos cuerpos para observarlos de cerca..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Charla: Sobre el modelo"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "¡Espera! Se me ocurrió una nueva forma de expresión que seguramente conmoverá a todo el mundo del arte de la pintura!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "¡Soy luz y sombra, soy color, yo... soy la pintura misma!"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "Sss... un color que nunca había visto, brillando en tu mundo espiritual... ¿qué podría ser...?"
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_100338_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "¡Qué pintura negra tan maravillosa! Solía recolectar mucho líquido corrosivo para pintar, y al final, esas obras desaparecieron. Colores del universo primordial, obras que fueron devoradas y olvidadas por todos... ¿no es aún más increíble?"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Déjame acercarme un poco más... ¡Déjame ver un poco más! Estas luces y sombras, estos colores, estas posturas... Comparado con ellos, lo que he pintado antes son solo un montón de papel desperdiciado..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_100340_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Dulcayn siempre me habla de lo artístico que es su cocina, ¡y yo le digo que comer no tiene nada que ver con el arte! No solo desperdicio un valioso tiempo de creación en esos complicados trabajos de manipulación de cadáveres, sino que después de lograr crear un plato que tiene tanto forma como apariencia, ¡tengo que morderlo y tragármelo! ¡Esto es un verdadero crimen contra el arte!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100342_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_100343_AwakerVoiceContent = {
    Text = "Mal modelo..."
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "No, no, otra pintura horrible... ¿Dónde puedo encontrar inspiración? ¿En un cementerio? ¿O en un patíbulo...?"
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "Aunque siento que la escultura es una forma de arte un poco rígida y anticuada, la escultora llamada Shan, con su cincel, puede tener una expresividad que va más allá de lo que este arte puede transmitir... ¡Es realmente un talento excepcional!"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Charlas: Sobre Shan"
  },
  Voice_100345_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"Sanga\""
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "¿Ves esta pintura, Guardián del Secreto? Este es un retrato que he pintado para ti. ¡Mira cómo devoras los cuerpos, qué fascinante! Sé que no todos pueden entender mis obras, pero el loco belleza que transmite esta pintura, ¡seguro que ya lo has tocado, verdad?! Para mí, eso es suficiente, completamente suficiente..."
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_100346_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "¿De verdad dijiste que querías comprar esta pintura...? ¡Gracias, Guardián del Secreto! Muy pocas personas pueden apreciar estas cosas..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_100347_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Guardián del Secreto, ¿tienes tiempo para ser mi modelo de nuevo últimamente? Comparado con la imagen que vi en ti la última vez, los otros modelos son una completa pérdida de mi tiempo..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "¡Sé testigo del renacimiento en esta obra!"
  },
  Voice_100349_AwakerVoiceTitle = {Text = "Activar"},
  Voice_100350_AwakerVoiceContent = {
    Text = "¡Mira estas líneas vívidas!"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "Tengo un presentimiento de que lo que esta brocha cree, ¡dejará a todos asombrados!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "¡Ah! Una pintura novedosa... ¡La aplicaré en el lugar más adecuado!"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "¡Este es realmente un lugar inspirador! He tenido algunas nuevas creaciones, Guardián del Secreto, ¿tienes tiempo últimamente para visitar mi estudio de arte? ¡Vamos, vamos!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_100353_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "¡Exacto, exacto! ¡La victoria regada con sangre! ¡Qué composición tan maravillosa!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_100355_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100355_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_100356_AwakerVoiceContent = {
    Text = "¡Ah! Siéntate, Guardián del Secreto. Ser mi modelo es un trabajo arduo. No te preocupes, estoy seguro de que crearé una obra increíble para ti."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_100356_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "Un artista solo debería ver la obra en sí, sin preocuparse por la mirada de los demás, pero yo no puedo... Desde el primer día que tomé el pincel, he deseado poder llevar la verdadera belleza a todos."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_100357_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "Esto me recuerda los tiempos que pasé en la academia de pintura. Aunque la mayoría de los profesores y compañeros eran personas completamente ignorantes del arte, siempre había uno o dos que podían vislumbrar la belleza que yo veía en mis obras."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "¿Qué tipo de arte loco surgirá de este espectáculo salvaje?!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "¡Mi paleta!"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "El dolor también es arte..."
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "¡Ah! Lo he visto... el ojo ciego que se oculta bajo el abismo, la visión final del universo... ¡Espera un momento más, guardián del secreto, estamos a punto de completarlo!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_100362_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "¡Mi pincel, hecho de mis huesos! ¡La paleta de colores, estos tonos los he recopilado en los cementerios de veinte ciudades... y mi valiosa tela de cuero! Guardián del Secreto, por favor, toma esto y pinta un retrato de mí. No, no, no, no necesitas tener ninguna habilidad para pintar... Creo que cuando esta profunda resonancia espiritual se plasme en la tela, será una obra maestra de belleza que nunca imaginé...!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_100363_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "¡Soy luz y sombra, soy color, yo... soy la pintura misma!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "¡Prueba este color!"
  },
  Voice_100365_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_100366_AwakerVoiceContent = {
    Text = "La esencia del arte es la locura...!"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "¿Te refieres a que la próxima vez podríamos intentar hacer un primer plano de esta parte en la pintura? Hmm... ¡No se me había ocurrido! ¡Es una idea genial!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_100368_AwakerVoiceContent = {Text = "¡Cuidado!"},
  Voice_100368_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "¡La esencia del arte es locura...!"
  },
  Voice_100369_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_100370_AwakerVoiceContent = {
    Text = "¡Mi paleta!"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "¡Oh! Esa mandíbula tan fluida, esos ojos brillantes, esa figura perfecta, y, y este vasto mundo espiritual como el cielo estrellado... Soy el pintor Pikman, ¿tendría la suerte de invitarle a ser mi modelo?"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_100372_AwakerVoiceContent = {
    Text = "La filosofía artística en la que creo es loca y agitada, la música de Hameln es completamente diferente, tan rigurosa como las lápidas de un cementerio sombrío. Pero no sé por qué, siempre puedo ver en esas notas ordenadas el caos más intenso proveniente del fondo del universo..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Charlas: sobre Hameln"
  },
  Voice_100372_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"hameln\""
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "¡Mira, Guardián del Secreto! ¡Esa eterna y loca visión en el lienzo, qué conmovedora, qué desesperante! Es en esta locura y dolor supremos donde florece el arte..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_100373_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "¡Ah! Lo siento, Guardián del Secreto... He visto en ti una visión sin precedentes... más aterradora que el abismo, más fascinante que el abismo..."
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_100374_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "No entiendo, si los humanos tuvieran la oportunidad, ¿por qué no convertirse en ghouls? ¿No es esta belleza salvaje y sangrienta mucho más interesante que ser un humano sin pasión en una gran mansión?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_100376_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_100376_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_116964_AwakerVoiceContent = {
    Text = "¡Castigo al pecado!"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "¡Castigo al pecado!"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Dos"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "Admito que tiene algunas habilidades para robar, pero una dama no debería recurrir a trucos tan despreciables. Si quiero algo, ¿no puedo dejar que todos me lo \"den voluntariamente\"?"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Jenki"
  },
  Voice_117791_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Jenkins\""
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "¡Jajajaja, mío, mío, todos los caramelos de Misaq son míos! ¿Qué estás esperando? ¡Sigue a esta bruja y prepárate para conquistar todas las dulcerías de Londinium!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_117792_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "¿No vas a dar? ¡Esa bruja se pondrá seria!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "Preguntas cómo se coloca el relleno de estos caramelos, sin encontrar costuras ni agujeros. Realmente deseas que los inventores de estos caramelos trabajen en el restaurante Misaq, ¡inventando un nuevo postre para esta señorita todos los días!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "¡Has enfadado a la bruja!"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "Antes siempre pensaba que los dulces eran demasiado simples y poco elegantes en comparación con los pasteles, pero ahora me doy cuenta de que subestimé estas pequeñas cosas envueltas en papeles de colores. Especialmente en comparación con los pasteles, la vida útil de estos dulces es mucho más larga, no hay miedo a que se estropeen, ¡realmente quiero llenar toda la casa con ellos!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "¿Encontraste un nuevo caramelo? Déjame ver... ¿Qué es esto? ¡Ese caramelo en forma de anillo es demasiado gracioso, ¿quién tiene un anillo de diamante del tamaño de un huevo?! Espera, ¿qué significa que me regalas un anillo? ¡Explícame bien!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_117797_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "He oído que las brujas suelen estar acompañadas de un misterioso gato negro. Elegir al gato salvaje del campus realmente es una falta de respeto para una dama. He decidido que te pondrás una diadema de orejas de gato para ser mi pequeño gato negro."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_117798_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "La resistencia es inútil."
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_117800_AwakerVoiceContent = {Text = "¡Buuu!"},
  Voice_117800_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "¿Realmente hay brujas en el mundo? ¿Viven solas en un bosque desprovisto incluso de la sombra de una persona? ¿Quién cocina para ellas, lava su ropa y prepara postres? Si ni siquiera pueden tener una merienda, ¿qué sentido tiene una vida así? Solo pensarlo es insoportable."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_117801_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "¡La bruja ha llegado!"
  },
  Voice_117802_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_117803_AwakerVoiceContent = {
    Text = "¿Tienes chocolate en la mano? Bien, dámelo todo. ¿Qué pasa? Tus cosas son mis cosas, ¿no es eso lo que se considera natural?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_117803_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "¿Me preguntas cuál es mi dulce favorito? Déjame pensar, el sabor del turrón de avellanas es muy aromático, el chocolate con caramelo también es delicioso, los caramelos de fresa y uva rellenos tienen una textura muy interesante, y hay un tipo de azúcar de malta que se puede estirar muy, muy largo, con un color tan bonito como la miel... No puedo decidir, cada dulce tiene su propia característica, de todos modos, hay muchos en la cesta de calabazas, ¡así que los quiero todos!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_117804_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "Mi objetivo en la vida ahora es probar todos los dulces del mundo. Solo de pensar que hay tantas variedades de caramelos esperando por mí, me llena de energía para levantarme cada día. ¿Dices pastel? El pastel es otro de mis objetivos en la vida."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_117805_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "No te dejes engañar por su apariencia infantil, en realidad es tan viejo que ya podría estar en la tumba. No hablemos de dulces, ni siquiera le interesan las cosas que le gustan a los vivos. Así que, en lugar de regalarle esos caramelos, mejor dámelos todos a mí, yo soy la que menos los decepcionará."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Charlas · Sobre Tulu"
  },
  Voice_117806_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Tulu\""
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "Si yo fuera una bruja, definitivamente sería una bruja que vive en un lujoso palacio, donde siempre hay mucha gente. Luego contrataría a diez de los mejores chefs para que me hicieran diferentes pasteles y dulces todos los días... ¿Dices que eso se llama princesa? ¿Y qué? ¡Puedo ser una bruja princesa!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_117807_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Hola, rápidamente consígueme más tipos de pasta de dientes; no, no comí tantos dulces, no tengo caries, solo un poco de dolor por la noche..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Charla·Sobre los dulces"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "Aunque las reglas del restaurante de Misaq a menudo son molestas, su habilidad para hacer postres es, eh... apenas aceptable."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "En este mundo hay tantos lugares oscuros y repugnantes; en lugar de preocuparse por la destrucción del mundo, es mejor comer algunos dulces antes de que eso suceda."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_117811_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_117811_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_117812_AwakerVoiceContent = {
    Text = "Aunque ya no tengo esas alfombras de piel de cordero, collares de perlas negras de alta mar y pijamas de seda oriental, despertar cada día en una habitación llena de dulces, con una cesta de calabazas rebosante al alcance de la mano, quizás así es como debería ser la felicidad... ¡Hola, no te rías tan orgulloso, debes seguir sirviendo a esta señorita y esforzarte más!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_117812_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Maldito Misaq, ¿te atreviste a detenerme para conseguir caramelos? ¿Ves? ¡Al final los he comido?"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "¿Qué quieres? ¿Quieres comer mis caramelos? Hehe, no es imposible dártelos generosamente, ¡vamos, llama a la señora bruja y déjame escucharte!"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "¿Cómo puede llamarse esto robo? Solo estoy ejerciendo los derechos nobles de una dama."
  },
  Voice_117815_AwakerVoiceTitle = {Text = "Activar"},
  Voice_117816_AwakerVoiceContent = {
    Text = "¡La bruja de los caramelos de la justicia ha llegado, todos los caramelos perdidos deben regresar a sus lugares correspondientes!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Maldito, tacaño, la bruja te recordará..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "¿Por qué puede esa pequeña rata buscar caramelos sin cuidado mientras yo no puedo? ¡Esto es un ataque a las damas! ¡Irrespetuoso!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "¿No? ¡Entonces esa bruja se lo tomará en serio!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "¡Déjame invitarte a unos caramelos!"
  },
  Voice_117820_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_117821_AwakerVoiceContent = {
    Text = "Comparado con los camareros de esos restaurantes, tú eres el más comprensivo, sabes preparar especialmente una porción de azúcar para mí. ¡Sigue así, mi sirviente exclusivo."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_117821_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_117822_AwakerVoiceContent = {Text = "¡Buuu!"},
  Voice_117822_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "¡Excesivo!"
  },
  Voice_117823_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_117824_AwakerVoiceContent = {
    Text = "¿Por qué me detienes? Como el leal sirviente de esta señorita, ¿no deberías estar ayudándome proactivamente a recoger todos los dulces... y traérmelos?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "¡Alto, esto es un atraco! Te aconsejo que seas razonable y entregues todos los dulces, de lo contrario, hmmm..."
  },
  Voice_117825_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_117826_AwakerVoiceContent = {
    Text = "Suaves, duros, crujientes, hojaldrados, lácteos, afrutados, a nuez, con chocolate... Ah, ¿cómo puede haber tantos tipos de caramelos que nunca he comido en este mundo? Entonces está decidido, ¡le sugeriré a Misaq que celebremos el Festival de los Santos una vez a la semana!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_117827_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_117827_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "¡La gran bruja triunfará! ¡El dios de los caramelos me protege, y yo protejo a todos los caramelos! ¡Ah jajaja!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "La resistencia es inútil."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "¡Todos los caramelos eventualmente serán míos!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "Ese niño es tan obediente que da un poco de miedo; siempre que le pidas dulces, te los dará, incluso no deja ni uno para ella, lo que resulta un poco vergonzoso... Ejem, quiero decir, dado que ella es tan comprensiva, la benévola bruja, por supuesto, le dejará algunos como recompensa."
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Lily"
  },
  Voice_117831_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"lily\""
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "¡Has enfadado a la bruja!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "¡Estoy enojado!"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "¡Todos los caramelos eventualmente serán míos!"
  },
  Voice_117834_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_117835_AwakerVoiceContent = {
    Text = "¿Qué dices, este algodón de azúcar también se puede asar? ¿Eh, puede algo caliente y pegajoso saber bien? ¿Déjame probar? Está bien, tomaré un bocado a regañadientes, pero si te atreves a engañarme... ¿Hmm?! ¡Esta textura crujiente y suave, tan deliciosa!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_117835_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Ilusión, inversión, ¡son el destino!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Ilusión, inversión, ¡son el destino!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "Porque has enfrentado el verdadero terror, ¿no tendrás miedo de mi verdadero yo? Hmph, esa es una respuesta bastante astuta, pero también me hace... cada vez más curioso sobre ti."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_123312_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "¿Cómo es el mundo en tus ojos? ¿Dónde están esos extremos aterradores? No, no quiero oírte describirlo; quiero experimentarlo contigo—la locura, la muerte, el terror. ¡He tomado una decisión! No te dejaré hasta que mi curiosidad esté satisfecha."
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_123313_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "¿Un lunático incontrolable? Tienes razón. Este no es mi mundo; aquí no hay leyes ni reglas aburridas... Aquí, puedo hacer lo que quiera, así que Guardián del Secreto, más te vale tener cuidado—no te dejes morder por un lunático fuera de control."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_123314_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "¿Quieres tener una conversación profunda por el bien de mi salud mental y física? Está bien, empecemos rápido, esta cosa aburrida, cuanto antes empecemos, antes termina."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_123315_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "¿Acaso solo estaba fingiendo ser una persona normal para responder tu pregunta? Ah, me has descubierto—entonces, ¿estás listo para ver mi verdadera apariencia?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_123316_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Cortaré tu cabeza."
  },
  Voice_123770_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_123771_AwakerVoiceContent = {
    Text = "¡A todos, jóvenes y ancianos, les encanta! ¡Tornado☆Resplandeciente——!!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "No debería ser yo cayendo..."
  },
  Voice_123772_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_123773_AwakerVoiceContent = {
    Text = "¡Impacto de tormenta!"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "¿Quieres salvar este mundo distorsionado y aterrador? Qué manera tan loca e interesante de morir—veamos hasta dónde puedes llegar."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Hola, pequeños, ¿quieren probar mi hacha? No se preocupen, ya viene..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Guardián del Secreto, parece que he visto la luz. ¿Podría ser que esta vez... no sé cómo estarán mis colegas del grupo de investigación? Por favor, no dejes un montón de trabajo para mí; realmente no quiero hacer horas extra."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_123776_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "¿Puedo volver a casa a través de este ritual? ¿Estás seguro? ¿Cuántas veces ha sido...? Bueno, de todos modos no hay daño en intentarlo."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_123777_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "¡Ja, ja! ¡Resulta que esta vida llena de adrenalina me queda mucho mejor que la aburrida rutina diaria!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_123779_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_123779_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_123780_AwakerVoiceContent = {
    Text = "No debería ser yo cayendo..."
  },
  Voice_123780_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_123781_AwakerVoiceContent = {
    Text = "¡Supernova Brillante☆— ¡Radiante!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "¡A todos, jóvenes y ancianos, les encanta! ¡Tornado☆Resplandeciente——!!"
  },
  Voice_123782_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_123783_AwakerVoiceContent = {
    Text = "Ahora mismo, se siente... como si estuviera entrando en la niebla. Hablando de niebla, me recuerda a esos pequeños en la bruma. Es una pena que no pueda desahogar mis sentimientos con ellos cuando estoy de mal humor."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_123783_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "¿Odio? No diría eso. Solo espero sinceramente que todas esas tediosas reuniones, encuentros sociales y valores universales desaparezcan."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "Así es... puedo sentir que me estoy acercando a mi \"yo verdadero.\""
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "Ah, un fracaso que era de esperar. La vida tiene sus altibajos, te acostumbrarás... Pero aún así, gracias por intentar esta vez."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_123786_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "Al igual que la catástrofe de niebla, no sé nada sobre la disolución. Eso es lo que las hace tan fascinantes, ¿no?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Mouchette, el grupo de investigación... oh no, ya no soy la vanguardia del grupo de investigación. Así que, permítanme reintroducirme—me llamo Mouchette, solo una chica encantadora~"
  },
  Voice_123788_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_123789_AwakerVoiceContent = {Text = "¡Vete!"},
  Voice_123789_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "Aquí está demasiado cerca de los asentamientos humanos, con adultos aburridos por todas partes... ¿Alguna vez has pensado en trasladar la escuela a un bosque remoto y deshabitado?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_123791_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_123791_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "Estoy a punto de enamorarme de esta sensación de flotar en otro mundo, el poderoso Despertado, la aterradora Disolución y las deidades desconocidas. ¡Ah, todo es un alivio lejos de la sociedad ordinaria!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "¿Hay más? Me estoy divirtiendo mucho—¡apúrate, que alguien me deje cortar otra hacha."
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_123794_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_123794_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "Un fracaso no significa nada... es una broma. ¡Más vale que se limpien el cuello y me esperen!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "¿Tienes una tarea? La próxima vez no es necesario saludar, ya estamos lo suficientemente familiarizados como para no realizar la \"rutina de saludo social.\""
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Sacrificarse por los demás es una idea realmente tonta y frustrante. Nadie tiene el derecho de exigir eso a los demás, ni siquiera los dioses."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Charla: Sobre Salvador"
  },
  Voice_123797_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Salvador\""
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "No está mal——"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "Finalmente, ya no hay más fingimientos... Ahora, divirtámonos."
  },
  Voice_123799_AwakerVoiceTitle = {Text = "Activar"},
  Voice_123800_AwakerVoiceContent = {
    Text = "¿El ritual aún no ha terminado? Realmente quiero apresurarme a regresar para disfrutar de un estofado de pez de Rivenrock, una humeante taza de té kava de avellana, por supuesto, el té de Ceilán y los churros de Andalucía aquí también son bastante agradables."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_123800_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "Siempre mejorando mis habilidades, ¿no temes que un día pueda perder el control...? Jaja, es una broma."
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "En realidad, quedarse en este mundo por un tiempo no es tan malo. Recordaré todo lo que sucede aquí y lo escribiré, para poder compartirlo con todos allá cuando regrese. Hmm, llamémoslo \"La aventura de Mouchette en otro mundo\". Suena genial, ¿verdad?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_123802_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "Admito que es muy linda... Sí, es cierto, verla perseguir y pelear con esos gatos callejeros que vagan por el campus es realmente adorable."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Charla: Sobre Murphy"
  },
  Voice_123803_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Murphy\""
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "Aunque estos poderes no me permitirán regresar a mi mundo, hacerse más fuerte siempre es algo bueno."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "¡Criada, yo también lo he hecho; busquemos un momento para que ella vea mi método de luchar con una aspiradora!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Charla: Sobre Karen"
  },
  Voice_123805_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"karen\""
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "¡Ja, ja! ¡Resulta que esta vida llena de adrenalina me queda mucho mejor que la aburrida rutina diaria!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "Muerte de un golpe."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Dos"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "¡Formen una fila, uno por uno."
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_124769_AwakerVoiceContent = {Text = "¡Vanish!"},
  Voice_124769_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "No pienses ni molestes, escucha y obedece ciegamente, ¡pues el mundo mundano no es más que una carga!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "No pienses ni molestes, escucha y obedece ciegamente, ¡pues el mundo mundano no es más que una carga!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "¿Les preguntas por qué tienen la cabeza vacía? Bueno, quizás nacieron así."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Cesa la ira y el resentimiento, todo se convertirá en nada."
  },
  Voice_126949_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_126950_AwakerVoiceContent = {
    Text = "Tal atención me hace incapaz de resistir el deseo de provocarte más."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_126951_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_126951_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_126952_AwakerVoiceContent = {
    Text = "¿Esperas que sea más hermosa o más aterradora?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "Esa persona, la princesa nacida de la alegría, con su vestido bordado de hilos dorados, su piel parecida al marfil, con la fragancia de madera de agar flotando a su alrededor, cautiva a todos con su mirada encantadora."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_126953_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "Pronto se aburrió de esta diversión, sus creyentes solo repetían la misma rutina, sumidos en el amor nacido del deseo, o el deseo nacido del amor; debido a la pérdida y la traición, sufrían tanto que les dolía vivir. Su necedad la cansaba, y sus lágrimas también la agotaban."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_126954_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "Vuestras miradas mezquinas realmente me desagradan."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "Esa Dama Roja me ha enviado varias invitaciones a su salón. \n El sabor de los pasteles exóticos es bastante bueno, pero... \n Debería haberme dicho antes que en su residencia, los aperitivos y los sirvientes no significan lo mismo."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Charla: Sobre Sorel"
  },
  Voice_126956_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Sorel\""
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "¿No es amor? Entonces, ¿por qué el miedo cuando estás rodeado? ¿No es desdén? Entonces, ¿por qué las lágrimas cuando es inalcanzable para siempre? \n Ah, ¿ahora temes a mi sombra? ¿Se ha convertido la fragancia de la magnolia blanca en un almizcle empalagoso e inexplicable para ti?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_126958_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_126959_AwakerVoiceContent = {
    Text = "...¡Está bien!"
  },
  Voice_126959_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "¿Eh? ¿Me preguntas por qué tienen esos patrones debajo de las axilas? ¿No crees que es realmente divertido?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Charla: Sobre Multitud"
  },
  Voice_126961_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_126961_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_126963_AwakerVoiceContent = {
    Text = "En comparación con las ofrendas de los creyentes, estas son más de mi agrado."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "Primero la actitud, luego la figura, hasta que también poseyeron un par... o más bien, lo que quedaba por recordar era un par de hermosos y fascinantes ojos—justo como los míos."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_126964_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "Estoy realmente aburrida hoy. ¿No tienes deseos que necesiten ser cumplidos? \n Es una pena que muchas personas estén dispuestas a empuñar su guadaña y ofrecerme sangre y carne, todo por propósitos aburridos. \n Pero si fueras tú..."
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_126965_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "¿Por qué el Cuerpo voluminoso me sigue y por qué se ha formado? Es una pregunta interesante, ¿también has tenido a alguien que deseas pero no puedes tener, y te arrepientes de no poder hacerlo?\nHmm, parece que no, qué lástima.\nEsa expresión de lucha en una situación desesperada, si apareciera en tu cara, sería muy~ muy interesante."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_126966_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...Si sigues siendo tan presuntuoso, lo que usaré para enfrentarme a ti puede que no sea esta actitud."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "Su historia, casi la he olvidado por completo, pero es una historia de alegría, una historia de crueldad, una historia que comienza con el abandono y la retribución, y que luego se convierte en una de sacrificio y seguir ciegamente."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_126968_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Complazcan a mí, maten entre ustedes en el dolor y el miedo~"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "......Esto, de hecho, ha despertado un poco mi interés."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "Todos verán el rostro de su amado bajo mi abanico. Presto este poder a los débiles, convirtiéndome en una cuchilla para el entretenimiento. \n Pero quizás, solo estoy diciendo, quizás. \n Si estás dispuesto a dejarte cautivar por esto, sentiré un verdadero y supremo éxtasis."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_126971_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "No te preocupes, eres diferente de esos nadie. \n Shh, no mires detrás de mí, no te preocupes por los toques invisibles—solo mira a mis ojos."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_126972_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "*Se ríe suavemente. ¿Os atrevéis a mirar mi verdadero rostro?"
  },
  Voice_126973_AwakerVoiceTitle = {Text = "Activar"},
  Voice_126975_AwakerVoiceContent = {Text = "Ruidoso."},
  Voice_126975_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_126976_AwakerVoiceContent = {
    Text = "¿Qué? ¿Otra vez estás mirando mi abanico, embelesado?\n Jeje, no importa a quién desees ver bajo el abanico, te satisfaceré... Ven, acércate un poco más—\n Oh, ¿no quieres? Diciendo palabras tan frías, pero tu expresión es bastante linda..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_126976_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "Has llegado a Sin sueño, ¿qué estás buscando?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "Cesa tu ira y resentimiento, porque todas las cosas se convertirán en nada."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "No se puede ser descortés."
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_126980_AwakerVoiceContent = {
    Text = "...¡Está bien!"
  },
  Voice_126980_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "Una vez tuve una hermosa y tímida niña así. \n Un capullo de flor llamativo, por supuesto, debe tener algunas espinas añadidas; no puede simplemente ser colocado en un jarrón."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Charla: Sobre Lily"
  },
  Voice_126981_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"lily\""
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "La academia rechazó firmemente mi solicitud para trabajar en la sala de consejería. Es realmente extraño, ¿qué podría estar mal?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "Todo eventualmente regresará a la nulidad, así que ¿por qué no buscar un poco de diversión conmigo?\nNo te preocupes, si llega el día en que no puedas resistir, no dejaré que Él te lleve primero."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_126984_AwakerVoiceContent = {Text = "Aburrido."},
  Voice_126984_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_126985_AwakerVoiceContent = {
    Text = "Eres una persona realmente extraordinaria, ocupada con tantos asuntos externos en un mundo destinado a la destrucción. \n Eso también ha despertado mi interés."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_126985_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "¡No te acerques!"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "Soy la Señora de los Sueños Nocturnos, Xu. Si en tu corazón hay alguien a quien deseas ver pero no puedes, estoy dispuesta a abrir el abanico y concederte un vistazo."
  },
  Voice_126988_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_127088_AwakerVoiceContent = {
    Text = "Toda la descendencia de los seres vivos puede ser bastante problemática.\nPequeños, suaves y ruidosos, sin querer vuelven todo a su alrededor patas arriba. Me gusta el bullicio, pero realmente no disfruto de este tipo de alboroto, así que por favor manténgalos a distancia."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "Mi pequeña jazmín, mi querido bebé, dulce como la miel en este juego de casa de muñecas~\n Ah, algunas tonterías de buen humor, no es necesario que te preocupes."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "En la leyenda del Reino de Panlong, el pavo real es una bestia hermosa y extravagante.\n Hermoso pero malicioso, suena estremecedor; si fuera feo pero amable, sería un poco aburrido."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "¡A devorar! ¡Ñam ñam!"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_129652_AwakerVoiceContent = {
    Text = "Glug, glug~"
  },
  Voice_129652_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "Bola de carbón, yo, ¿comer, juntos? ¡Juntos!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_129653_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "¡Mosk! ¡Muy fuerte!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "¡Abismo! ¡Espiral! ¡Destrucción! ¡Todo——conviértete en vórtice!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_129656_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_129656_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "¡No me toques! ¡Me romperé!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_129657_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Conchas, ¡brillante! Brillante, bonito, ¡para ti!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_129658_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "Frío, aterrador, Mosk, ¡escóndete!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "Charla: Sobre Muñeca"
  },
  Voice_129659_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"muñeca\""
  },
  Voice_129660_AwakerVoiceContent = {Text = "¡Ahuh!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "¡Caza, maldito! ¡Arruínalo! Mosk, ¡golpéenlos, arruínalo!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "¡Qué divertido! ¡La próxima vez! ¡Quiero más!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_129662_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "¡Acaricia, bien! ¡Mosk, tú, acaricia!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "No, ¡no! Bola de carbón, Mosk, ¡protégete!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "¿Otra vez? ¡Otra vez!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "¡Jeje, Mosk, vamos a jugar!"
  },
  Voice_129666_AwakerVoiceTitle = {Text = "Activar"},
  Voice_129667_AwakerVoiceContent = {
    Text = "¡Viene la gran ola!"
  },
  Voice_129667_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_129668_AwakerVoiceContent = {Text = "¡Tira!"},
  Voice_129668_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_129669_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_129669_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_129670_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_129670_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_129671_AwakerVoiceContent = {
    Text = "¿Ritual?! ¡Llévame contigo!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_129671_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "¡Vórtice! ¡Fuerza! ¡Bastón!"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_129672_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_129673_AwakerVoiceContent = {Text = "¡Pum!"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_129674_AwakerVoiceContent = {Text = "¡Bien!"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_129675_AwakerVoiceContent = {
    Text = "¡Huu, huu~!"
  },
  Voice_129675_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_129676_AwakerVoiceContent = {Text = "¡Pelea!"},
  Voice_129676_AwakerVoiceTitle = {
    Text = "Charla: Sobre Goliat"
  },
  Voice_129676_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"goliat\""
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "¡Encontré muchos, brillantes!"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_129677_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "¡Abismo! ¡Espiral! ¡Destrucción! ¡Todo——conviértete en vórtice!"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_129679_AwakerVoiceContent = {Text = "¡Grr!"},
  Voice_129679_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_129680_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_129680_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_129681_AwakerVoiceContent = {
    Text = "¡Mosk! ¡Muy fuerte!"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "¡A devorar! ¡Ñam ñam!"
  },
  Voice_129682_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_129683_AwakerVoiceContent = {
    Text = "Nautilus, Nautila, Bola de carbón! ¡Brillante!"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "Mosk, ¡carga!"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "Habilidad·II·Cargar Uno"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "Mosk, ¡A la carga!"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "Habilidad·II·Recarga·Dos"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "¡Abraza! ¡Mosk! ¡Me gusta!"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_129686_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "Bola de carbón, ¡amigo! Mosk, ¡siempre!"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "¡Rápido, rápido!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_129688_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "¡Mosk! ¡Bola de carbón! ¿Juntos, siempre? ¡Para siempre!"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_129689_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "¡Hala hala~ ¡Las grandes olas se levantan!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_129690_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "¡Amigos! ¡Muchos! ¡Me gusta!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "¡Mosk! ¡Impresionante!"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Nautila, quiero verte. Eh, Nautila, Mosk, Mosk!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Charla: Sobre Nautila"
  },
  Voice_129693_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"nautila\""
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "¡He vuelto más fuerte!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "¡Yo! ¡Mosk! ¡Hola!"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_130511_AwakerVoiceContent = {Text = "Uf—"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "Habilidad·Dos·Cargar Tres"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "El error debe ser corregido."
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "La tragedia ante ti es solo una mirada entre incontables posibilidades.\n\nMás allá del telón del destino yace un escenario engullido por la oscuridad —\nluces apagadas, actores desaparecidos, todo retornando a lo profundo.\n\nPero ahí no es donde termina.\nLlevo conmigo la determinación de soportar esta labor ingrata, hasta el día en que las luces regresen."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "El destino de cada alma es llevado por hilos... pero el tuyo es un guion que no puedo descifrar. Me descubro esperando con ansias cualquier improvisación que traigas a este mundo."
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "El escenario siempre ha sido tuyo. Da un paso al frente, querida marioneta."
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_133724_AwakerVoiceContent = {Text = "¿Hm?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "Todo es un epílogo pasado. Todo es un nuevo prólogo. El nuevo capítulo entre nosotros espera a que tú lo escribas, Guardián."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_133725_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "Si la comedia es tu inclinación, <Italic:Un sueño de una noche de verano> te vendría bien. Soy particularmente aficionado a los traviesos desvaríos de Puck — oculto tras la risa de un duende, el destino siempre deja escapar algo."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_133726_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "Sométete a esto."
  },
  Voice_133727_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_133728_AwakerVoiceContent = {
    Text = "El huso del destino ahora gira."
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "Prisionero del destino, tan lamentable como siempre... lo que está escrito no puede ser rechazado."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "Incluso quien observa todas las cosas sigue siendo un actor torpe en su propio guion. Sostener la red del destino, y aun así estar atado por sus hilos — caminamos por senderos distintos en esta circunstancia predestinada, pero ninguno de los dos ha abandonado jamás verdaderamente sus empeños ingratos. Insensato, quizás. Ilusorio, quizás. Así es conmigo, y así es con ella."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "Charla: Sobre Tawil"
  },
  Voice_133730_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"tawil\""
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "¿Un giro inesperado?"
  },
  Voice_133731_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_133732_AwakerVoiceContent = {
    Text = "Gracias por acompañarme a través de tantos telones que suben y bajan. No te decepcionaré — aún quedan más veladas por venir que te conmoverán de maneras que no esperabas."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_133732_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "Qué cantante tan dotada. Una voz otorgada por la gracia, clara y ardiente a la vez, como si surgiera del destino mismo. Si ella actuara en mi teatro, imagino que incluso el público más exigente quedaría desprevenido."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "Charla: Sobre Tinct"
  },
  Voice_133733_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"tintura\""
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "Los hilos invisibles que nos pertenecen a ti y a mí hace tiempo que se enredaron estrechamente, tejiendo a la vez una jaula y un camino.\nNo puedo ver dónde termina la jaula, ni adónde lleva el camino.\nEso es precisamente lo que hace esta historia tan cautivadora."
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_133734_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "Los hilos del destino penden inmóviles."
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "Ella visita mi teatro a menudo... pero sé que no viene por las obras. Parece usar este escenario para prestar cierto refinamiento a su propia imagen. Qué habilidad tan notable, sin embargo — gastarla solo como espectadora parece un desperdicio. Esa dama no es de las que florecen en la oscuridad del público. Ella pertenece bajo la luz."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "Charla: Sobre Sorel"
  },
  Voice_133736_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Sorel\""
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "Una vez lo escuché tocar. Esa música hizo temblar el alma... Quizás debería invitarlo a componer una sinfonía del destino para mi próxima producción."
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "Charlas: sobre Hameln"
  },
  Voice_133737_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"hameln\""
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "Otra historia, bellamente completa, llega a su fin."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "Al fin lo he visto completo. La red infinita del destino."
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "Si me lo permitieras... deseo tejer una obra que pertenezca solo a ti y a mí.\nSin público, sin ensayo. Simplemente deseo ver cómo el hilo que ni yo puedo leer comenzará a agitarse... cuando tú entres en la luz."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_133740_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "Qué bailarina tan desdichada. He observado sus pasos. La suya es una belleza que avanza hacia la ruina — cada giro encendiendo llamas verdes, como si intentara quemar los hilos del destino, aunque al final esos hilos solo tallarán algo desgarradoramente vívido de ella. Si surge la oportunidad, me gustaría escribir un ballet solo para ella."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "Charla: Sobre Liz"
  },
  Voice_133741_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Liz\""
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "Aquí se teje. Aquí se sopesa. Aquí se corta."
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "Quédate quieto..."
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "Otro hilo se revela con claridad."
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "El telón se abre para ti, y el guion del destino espera para comenzar. Dime: ¿qué camino predestinado preferirías recorrer? ¿Un final triste, o un alegre comienzo?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_133745_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "Le he tomado bastante cariño a este tejer, día tras día... En el silencioso y repetido tirar de cada hilo, veo a través de los comienzos y finales de todas las historias. Observando cada telón caer, a veces siento como si me hubiera elevado por encima del destino mismo. Y sin embargo, uno no puede escapar de la red del destino, y solo observar deja, al final, una sensación de vacío.\nEn esos momentos, voy al teatro. Para interpretar las penas y alegrías que he tejido con mis propias manos, pero que nunca he vivido."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_133747_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_133747_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_133748_AwakerVoiceContent = {Text = "Heh..."},
  Voice_133748_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_133749_AwakerVoiceContent = {
    Text = "Aquí se teje. Aquí se sopesa. Aquí se corta."
  },
  Voice_133749_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_133750_AwakerVoiceContent = {
    Text = "El destino se agita. Su susurro se acerca."
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "El teatro ha estrenado una nueva comedia romántica, y te he reservado un asiento entre el público del destino. A través de cada larga noche donde los destinos se entrelazan, esperaré en silencio el momento en que nuestras estrellas se encuentren."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_133751_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "Tirar con tanta insistencia de los hilos del destino...\n\nPareces bastante ansioso por leer tu propia historia, ¿no?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "Lo que fue escrito se acerca."
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "Si deseas entrar en el salón de la tragedia, permíteme presentarte <Italic:Antígona>. Atrapada entre la ley divina y el decreto mortal, cada paso que da cae sobre hilos que el destino ya ha tejido, hasta que finalmente se adentra en la profunda sombra de la tumba de piedra. Es precisamente porque esas cadenas no pueden romperse que la voluntad ardiendo dentro de su pequeño cuerpo resplandece con tanta intensidad contra la larga noche."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_133754_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "Ningún final es jamás verdaderamente seguro, pero ninguno escapa a la red de causa y consecuencia..."
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "Sobre los hilos, veo colores cambiar a través de cada tonalidad del arcoíris.\nSe extienden a través de una red infinita, tejiendo mundos sin límites y posibilidades infinitas, hasta formar un patrón más hermoso que cualquiera jamás visto.\n\nAl final — dios o mortal, héroe o villano — cada uno es guiado por esos delgados hilos, precipitándose hacia su fin predestinado bajo la mirada implacable del destino."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "Creí que nada en este mundo podría sorprenderme ya... Tu gusto teatral me ha dejado impresionado."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_133757_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "Los hilos del destino siempre se conectan en las sombras... Has perturbado uno de esos hilos, y por eso me has sobresaltado."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_133758_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "Nunca me han gustado las funciones que simplemente se repiten. La razón misma por la que uno entra en un teatro es para presenciar un escenario vivo — uno que no puede ser recreado.\nSi no hace más que girar como un mecanismo de relojería, el escenario se convierte en una jaula ornamentada, y observar no es más que un tedioso peregrinaje hacia un final que ya conoces.\nUna mascarada sin alma, sin importar cuán magnífica sea la producción. ¿Qué opinas?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "Esos hilos una vez fluían en perfecto orden entre mis manos... hasta que apareciste tú, y enviaste ondas a través de su curso que jamás había previsto."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_133760_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "Prisionero del destino, tan lamentable como siempre... lo que está escrito no puede ser rechazado."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "De hilos infinitos, tejo el único camino."
  },
  Voice_133762_AwakerVoiceTitle = {Text = "Activar"},
  Voice_133763_AwakerVoiceContent = {
    Text = "En el gran escenario del destino, todas las almas aguardan su señal dentro de la red de causa y consecuencia, sus alegrías y penas tomando forma en silencio mientras los engranajes giran...\nEl telón se ha alzado, Guardián. Aquí es donde tu historia, y la mía, comienza."
  },
  Voice_133763_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_133764_AwakerVoiceContent = {
    Text = "El conflicto está aquí. ¿Serás el héroe que rompe la red, o el títere que solo se mueve según los hilos lo permiten?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "Resistencia fútil."
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "Gracias por este regalo. Lo guardaré con cuidado."
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "He estudiado bastante la estructura de los Cuerpos Despertados, así que ya me considero una experta. Pero la \"espiritualidad\" dentro de los Núcleos de plata... esa parte aún no la entiendo del todo."
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_139866_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "Aquí es... donde comienza un nuevo mundo."
  },
  Voice_139867_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_139868_AwakerVoiceContent = {
    Text = "Puedo hacer cosas así, ¿sabes? Como reorganizar o modificar los cuerpos de otras criaturas..."
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_139868_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "Cada ser vivo es diferente, así que antes de empezar a modificar cosas, hay que estudiarlos con mucho cuidado."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_139869_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "¿No me tienes miedo? Aww... qué aburrido..."
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "No dejaré que nadie se interponga en nuestro camino."
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "Estoy lista, cuando sea."
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "Los seres vivos realmente están llenos de diversidad. ¡Quiero aprender mucho más!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "¿Quieres jugar con Saya?"
  },
  Voice_139875_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_139876_AwakerVoiceContent = {Text = "¡¡Auch!!"},
  Voice_139876_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_139877_AwakerVoiceContent = {
    Text = "Aquí es... donde comienza un nuevo mundo."
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "¡Estoy llena. ¡Gracias por invitar!"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "Oye, Guardián... ¿alguna vez has amado a alguien? ¿Alguna vez has extrañado a alguien de verdad, con todo tu corazón?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_139880_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_139881_AwakerVoiceContent = {Text = "¡Ngh!"},
  Voice_139881_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_139882_AwakerVoiceContent = {
    Text = "¿Es aquí?"
  },
  Voice_139882_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "¡Buen trabajo! ¿Encontraste algo bueno?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "Después de todas mis pruebas, ahora entiendo mucho más. La \"espiritualidad\" que lleva cada Cuerpo Despertado... todas son completamente diferentes. Y parece que la espiritualidad de mi Núcleo de plata es... \"amor\"."
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_139884_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "¿Y bien? Te pillé, ¿verdad?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "Este es mi último regalo... para ti."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "\"<Italic:En una de esas estrellas, mi flor está floreciendo...>\"\nSiento que ya has dicho algo así antes."
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_139887_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "Parece que cada \"Núcleo de plata\" está conectado a una voluntad que viene de muy lejos. Qué misterioso..."
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_139888_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "Este es mi último regalo... para ti."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_139891_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "El Principito dice que su rosa se volvió especial porque él la cuidó... ¿Tú qué opinas?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_139892_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "Ayer encontré un libro llamado <Italic:El Principito> en la estantería de Lily. ¡Era muy bueno! ¿Quieres leerlo?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_139893_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "Sí, he estudiado la estructura de los Núcleos de plata y estoy empezando a entender cómo funcionan los Cuerpos Despertados."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_139895_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_139896_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_139897_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_139897_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "¡Mucho gusto!"
  },
  Voice_139899_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_139900_AwakerVoiceContent = {
    Text = "¡Hola! ...¿Se dice así?\n¡Soy Saya, y... encantada de conocerte!"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_139901_AwakerVoiceContent = {
    Text = "Conoces los dientes de león, ¿verdad? Esos que lanzan sus semillas al viento. Una pequeña semilla es llevada lejos, muy lejos de su tierra natal... y quizás aterriza en un desierto donde no crece absolutamente nada, ni una sola brizna de hierba. Me pregunto... ¿qué sentirá esa única y pequeña semilla...?"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_139901_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "¡No importa cuántas veces lo haga, siempre es divertido!"
  },
  Voice_139902_AwakerVoiceTitle = {Text = "Activar"},
  Voice_139903_AwakerVoiceContent = {Text = "¡Eya!"},
  Voice_139903_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_139906_AwakerVoiceContent = {Text = "¡Cuidado!"},
  Voice_139906_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "¡Me encanta la buena comida! ¡Y me gusta la gente que es amable conmigo! Cuando alguien es cariñoso conmigo... simplemente me hace muy feliz."
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "¿Ella es quien me despertó? Se ve realmente... deslumbrante. Entonces, ¿la ayudaste a encontrar a su hermana?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "Charla: Sobre Tinct"
  },
  Voice_140534_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"tintura\""
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "Siempre que estoy a tu lado, aparece gente extraña y se reúne a nuestro alrededor. La verdad es que prefería cuando éramos solo nosotros dos en el Dominio."
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "Entendido. ¡Me encargo!"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "Guardián, Vínculo, Cuerpo Despertado. Así es como estamos conectados. Tú me lo explicaste. Puedo sentir nuestras almas unidas... ¿como un hilo de plata? Hmm, suena un poco demasiado complicado..."
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "¿Propagar semillas a través de carne y sangre? Hmm... interesante. La verdad es que tengo curiosidad por sus ovejas."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "Charlas: Sobre Thais"
  },
  Voice_140538_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"thais\""
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "Hay ciertas amenazas ahí fuera que podrían traer una oscuridad lo bastante grande como para destruir este mundo, ¿verdad? Lo sé. La profesora Doll me lo contó todo."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "No me gusta la gente brusca. Me dan mala sensación..."
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "¿Oh? Así que su especie se reproduce en nuevos planetas depredando a otras especies. Vaya, ya veo..."
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "Charla: Sobre Winkle"
  },
  Voice_140541_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"bígaro\""
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "Buen chico."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Dos"
  },
  Voice_141964_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Tres"
  },
  Voice_141965_AwakerVoiceContent = {
    Text = "...¡Está bien!"
  },
  Voice_141965_AwakerVoiceTitle = {
    Text = "Recibido·Cinco"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "Qué lástima. Cuando cambies de opinión, sabrás dónde encontrarme."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_143501_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_143502_AwakerVoiceContent = {
    Text = "Maldita sea..."
  },
  Voice_143502_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "La piel, los músculos, los nervios, los huesos, todo será reconstruido, sano e íntegro de nuevo, revitalizado de nuevo."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_143503_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "¡Ante el océano, no existe enemigo que no pueda ser destruido!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "¿Banquetes, Caza, refugio?\nOra a mí, las aguas más antiguas del océano te dirán mi nombre.\nSoy el señor del abismo, Pontos."
  },
  Voice_143505_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_143506_AwakerVoiceContent = {
    Text = "Jeje, ¿añoras los momentos en Ebwynnos?...\nEst dentro de este cuerpo, dándote la bienvenida de regreso en cualquier momento."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "Aunque yo no lo hice, si algún día escuchas en tus oídos el sonido del agua del mar y el aleteo de alas, no te preocupes, es completamente normal."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "¡Entrega tus sentidos y reflexiona por siempre en el abismo!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "Me gustan los jóvenes llenos de vitalidad. Lástima que Misaq tenga un control demasiado estricto sobre los jolgorios; ni siquiera hay un coto de caza decente.\nY además, en su Interior está esa cosa inmunda que se atreve a pasearse abiertamente, incluso ostentando el título de profesor."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_143510_AwakerVoiceContent = {Text = "¡Ugh!"},
  Voice_143510_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_143511_AwakerVoiceContent = {
    Text = "Después de todo lo que he hecho, ni siquiera estás dispuesto a llamarme tío una vez más. Qué fastidio."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "No hay prisa, la oscuridad en las profundidades del océano os Devorará a todos."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "Arrodíllate, conviértete en sustento de Ebwynnos."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Tres"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "En cuanto al ser que me eligió... solo puedo decir que es a la vez amable y despiadado.\nDónde caer depende enteramente de su humor; inevitablemente te rescatará del peligro, aunque si ese lugar es otro peligro, ya no es algo que este \"viaje\" deba considerar.\nQué interesante, qué impredecible. Estoy pensando en perpetuar esa tradición."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_143515_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "Tengo un vínculo especial con Ebwynnos; mejor dicho, yo soy Ebwynnos, Ebwynnos se sostiene en mí, existe a través de mi cuerpo."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "Charla: Sobre Ebwynnos"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "Levanta la cabeza y expón tu garganta."
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "Borrar recuerdos, borrar la existencia. Algo familiar... entiendes lo que quiero decir; aunque de distinto origen, parece que siempre brotan desde la oscuridad sin luz."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "No deberían haber sido tan estúpidos como para profanar mi majestad."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "Demasiado débil."
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "En Ebwynnos, el jolgorio nunca cesa, y los enemigos de Ebwynnos tampoco encontrarán jamás la paz."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_143521_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "Ah, siento tu estremecimiento como propio, pero es completamente innecesario, mi joven amigo.\nAcepta tu miedo a la mediocridad y al desgaste, mírame a mí, y comprenderás que siempre tienes otra elección."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_143522_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "Es cierto, sé que esa catástrofe no fue instigada directamente por él, sino un accidente en medio de su diversión, pero eso evidentemente solo me hace querer matarlo aún más.\nEsa nube negra haría bien en no quedarse sola, y en no caer en mis manos."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "Esos viscosos Hombres pez no son mis amigos, sino mis enemigos. ¿Sorprendente? El océano nunca les perteneció."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_143524_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "¡Por toda la eternidad, permanece aquí!"
  },
  Voice_143525_AwakerVoiceTitle = {Text = "Activar"},
  Voice_143526_AwakerVoiceContent = {
    Text = "¡Preparaos, presas!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "La espiritualidad engendra nuevos cuerpos, los cuerpos son llenados con conocimiento intrascendente, y luego esos individuos hermosos y vivaces se reunirán para siempre en un mismo lugar.\n¿Recuerdas lo que dije? Las profundidades más oscuras del océano lo contienen todo... y retienen todo."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_143527_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "Pesadilla, detenlos."
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "Espero que estas pequeñas criaturas no te dejen en la ruina. Ya sabes, mantener a toda una familia no es tarea fácil."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "Hace mucho, mucho tiempo, antes de que la tierra emergiera del océano, este planeta despertó ciertos espíritus especiales. Poderosos, majestuosos, imposibles de escrutar.\nNo podían definirse como hostiles ni amistosos; los humanos, como innumerables seres del pasado, les eran irrelevantes: serían borrados como polvo, o protegidos junto con su territorio."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_143530_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "Solo el envejecimiento es la aventura que debes enfrentar en soledad, tu mejor amigo y tu enemigo más tenaz; las luces de Ebwynnos lo desterrarán por completo... Justo algunos recuerdos sin importancia, no necesitas que te anclen."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_143531_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "Abandonad la ilusión de Escapar."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "Te convertirás en polvo grisáceo."
  },
  Voice_143533_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_143534_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_143534_AwakerVoiceTitle = {Text = "golpear"},
  Voice_143535_AwakerVoiceContent = {
    Text = "Muy inteligente de tu parte, pequeño. Los Creyentes de los monstruos foráneos siempre son tan torpes que arrojan cadáveres al mar, y eso no cuenta como un regalo, ¿verdad?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "Ya tienes los ojos de alguien encima."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Dos"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "Aunque no quiera admitirlo, en ocasiones muy, muy contadas, siento que el envejecimiento no es lo único que trae el tiempo, sino tan solo un símbolo.\nAsí que me permito que exista en mí. Por supuesto, solo en apariencia."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "La Oración es efectiva. Imagina que, aunque unos insectos formaran caracteres Leo ante ti, considerarías responder a sus súplicas."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_143539_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "Jajajaja, vamos, no pongas esa expresión, mi pequeño amigo.\nEso es solo una tradición que ciertos llamados \"dioses antiguos\" deben seguir. En cuanto a ti, sin ningún precio ni condición, estaré siempre de tu lado."
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_143540_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "Hmm, un pequeño monstruo confabulado con monstruos foráneos.\n¡Que algún estúpido me ponga a mí y a él en el mismo altar es un insulto!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "Charla: Sobre Tulu"
  },
  Voice_143554_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Tulu\""
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "El enemigo de mi enemigo es mi amigo. Si se presenta la oportunidad, no me importaría hacer un buen negocio arrebatándole el juguete favorito a mi archienemigo."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "Charla: Sobre Ryker"
  },
  Voice_143555_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"ryker\""
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "¿Oh? ¿Quieres pelear conmigo, aquí? Me parece bien."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "¡Más! ¡Dame más fuerza!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "No me gustan quienes tienen el corazón dividido, pues tal división suele significar debilidad. Pero tú eres una excepción. Una vez creí que quienes cargan demasiado nunca podrían llegar lejos. Pero el camino que has elegido me sorprende... Quizás un rival que camina por un sendero diferente es más digno de ser forjado y desafiado. ¿No crees, \"rival\"?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "¡Cetus del Mar Astral... devóralos a todos!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "¡Siéntete honrado de enfrentarte a mí!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "¡Que las estrellas sean testigos de la aniquilación!"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "No es suficiente. Ni de lejos…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_146165_AwakerVoiceContent = {Text = "Heh."},
  Voice_146165_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_146166_AwakerVoiceContent = {Text = "Hmph."},
  Voice_146166_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "Me importa poco el declive de este mundo, pero no permitiré que obstaculice mi búsqueda de la fuerza."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "Dudar del valor de la existencia simplemente porque el olvido aguarda... No me interesan debates tan infantiles. La Destrucción no significa nada, ni tampoco la memoria. La fuerza en sí misma es el significado."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "Charla: Sobre Doll: Infierno"
  },
  Voice_146168_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"derretido·muñeca\""
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "Veo una voluntad ajena en tus ojos. Impura, pero lo bastante tenaz. Vamos, muéstrame qué fuerza o anhelo te trajo ante mí."
  },
  Voice_146169_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_146170_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_146170_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_146171_AwakerVoiceContent = {
    Text = "¡Siéntete honrado de enfrentarte a mí!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "El aroma del caos... qué nostálgico… Desde el momento en que nací de este vacío, mi búsqueda nunca ha cambiado."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_146172_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "¿Deseas desafiarme? Admiro tu valentía, y te concederé el honor de ser derrotado. Considera esto mi respeto por el \"Guardián de Misaq\"."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_146173_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "Una falsa utopía, repleta de débiles, cobardes y necios que se engañan a sí mismos. Pero no importa. Este lugar me trae a los rivales más emocionantes, y eso es suficiente."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "Desperdiciar una fuerza inmensa, aprisionando su talento en un largo sueño por miedo, culpa y fatiga. Qué lástima."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "Charla: Sobre Tulu"
  },
  Voice_146175_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Tulu\""
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "Apenas merece mi tiempo."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "El sello se afloja un poco… La fuerza desde las profundidades del universo surge con ímpetu. No había sentido esto en mucho tiempo…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_146177_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "¡Cetus del Mar Astral... devóralos a todos!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…Estimulante."
  },
  Voice_146179_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_146180_AwakerVoiceContent = {
    Text = "He vagado por el vasto cosmos durante eones; he arrojado al abismo a todos esos \"poderosos\". Eres único, pero para estar a mi lado, primero aprende a mantener la cabeza en alto. No tengo uso para los cobardes."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_146180_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "Valiente o cobarde, fuerte o frágil... Jeh, no, no me importa qué tipo de persona sea mi rival. Cualquier rival digno me produce una emoción genuina."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "La debilidad. De todas las cosas viles en el mundo, la debilidad es el pecado más miserable. Todos nacen con una espada en la mano; nadie tiene el derecho de rendirse antes del final, ni de pisar el campo de batalla del destino ya resignado a la derrota. Eso insulta tanto a tu rival como a ti mismo."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "¡Carcasa Astral corrompida... despierta!"
  },
  Voice_146183_AwakerVoiceTitle = {Text = "Activar"},
  Voice_146184_AwakerVoiceContent = {
    Text = "Jeh… Eso sí fue emocionante. La próxima vez, no me contendré."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "Mis huesos tiemblan de deleite… He sido testigo de tu esfuerzo. Y esto demuestra que eres digno de estar a mi lado, Guardián."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_146185_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "Jeh… Lo ves con claridad, Guardián. ¡Las cadenas de la fuerza están hechas para romperse!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_146186_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_146187_AwakerVoiceContent = {Text = "¿Hm?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_146188_AwakerVoiceContent = {Text = "¿Hm?"},
  Voice_146188_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_146189_AwakerVoiceContent = {
    Text = "Justo ahí... la cima de la fuerza que he perseguido toda mi vida... Has caminado este camino conmigo y me has guiado hasta este umbral. ¡Estoy ansioso por presenciar ese día definitivo contigo!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_146189_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "Quizás te juzgué demasiado precipitadamente... Tu crecimiento y tu fuerza oculta me han sorprendido. He visto innumerables vidas desvanecerse con el tiempo, pero tú... eres verdaderamente diferente. Siento una gran curiosidad por el verdadero origen de tu fuerza."
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_146190_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "¡Fauces del Infierno, ábrete ante mí!"
  },
  Voice_146192_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_146193_AwakerVoiceContent = {
    Text = "Ah, ya veo... nunca hubo un fin para la fuerza. ¡El verdadero desafío apenas acaba de comenzar! Fuiste tú quien me trajo aquí y me mostró la realidad. Pronto, presentaré ante ti a un guerrero más perfecto. Asegúrate de regresar aún más fuerte, mi \"rival\"."
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_146193_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "Trucos insignificantes."
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "¡La fuerza hierve en mi médula!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "¡Devorar... todo!"
  },
  Voice_146196_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_146197_AwakerVoiceContent = {
    Text = "Misericordia, debilidad, confusión... tus ojos están nublados por impurezas. Quien vacila jamás podrá comprender qué es la fuerza."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_146197_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "La verdadera Fortaleza nunca ha tenido relación con la venganza ni con el Guardián. La Fuerza es Solo Fuerza; la otra yo jamás comprendió \"verdaderamente\" esta verdad. Esa es la raíz de su debilidad."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "Charla: Sobre Lotan"
  },
  Voice_146198_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"lotan\""
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "Escucha bien, lo diré solo una vez:\nYo, Lotan, te considero un rival digno de mi paciencia.\nHasta que alcances tu cima, seré tu hoja más confiable. Esta promesa no tiene nada que ver con sentimientos ni lealtad. Eres mi rival más emocionante, y jamás permitiré que caigas en el camino."
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_146199_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "Ven... mátame, o muere."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "¡Fauces del Infierno, ábrete ante mí!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "¡Donde apunta la hoja de hueso, todo se desmorona!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "¡La fuerza… no tiene fin!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Dos"
  },
  Voice_147493_AwakerVoiceContent = {Text = "—"},
  Voice_147493_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_147493_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(Una canción ronca y suave)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "Espectadores, necesitamos más espectadores"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "Arena... Desierto blanco... Aquí es peligroso, vámonos juntos"
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_147496_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "Recuerdo el mapa del nuevo hogar, era colorido y hermoso. Es donde debemos ir. Podemos cantar, podemos ser felices"
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_147498_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_147499_AwakerVoiceContent = {Text = "—"},
  Voice_147499_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_147499_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_147500_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_147500_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_147501_AwakerVoiceContent = {
    Text = "Eso es... la voz del cosmos"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "Has vuelto. Como siempre, siéntate a mi lado y esperemos juntos. ¿Esperar qué...? Solo esperar"
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "Ensayo perfecto, creo que estoy listo para el escenario"
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_147503_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_147504_AwakerVoiceContent = {Text = "Caer."},
  Voice_147504_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_147505_AwakerVoiceContent = {
    Text = "Dedicado a la desolación y a la muerte."
  },
  Voice_147505_AwakerVoiceTitle = {Text = "Activar"},
  Voice_147506_AwakerVoiceContent = {
    Text = "No estoy loco ni triste. No crean en rumores absurdos"
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "Extraño, parecen temer mi canto"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_147508_AwakerVoiceContent = {Text = "¡Shh..."},
  Voice_147508_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "Qué bonito traje de actuación, brillante, brillante"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_147509_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_147510_AwakerVoiceContent = {Text = "—"},
  Voice_147510_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "¡Oh, colores de las estrellas que han perdurado hasta hoy!"
  },
  Voice_147511_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_147512_AwakerVoiceContent = {Text = "Canta."},
  Voice_147512_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_147513_AwakerVoiceContent = {
    Text = "¿Entrenamiento de voz correcto...? Pero estoy muy contento con mi voz actual"
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_147513_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_147514_AwakerVoiceContent = {Text = "—"},
  Voice_147514_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "La voz parece haber cambiado"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_147515_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "¿Qué tal, te gusta mi canto?"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_147517_AwakerVoiceContent = {Text = "Duerme"},
  Voice_147517_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_147518_AwakerVoiceContent = {Text = "—"},
  Voice_147518_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_147519_AwakerVoiceContent = {Text = "De acuerdo"},
  Voice_147519_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_147520_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_147520_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_147521_AwakerVoiceContent = {
    Text = "Gracias... ¿Debería decir gracias?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_147522_AwakerVoiceContent = {
    Text = "*suspiro*..."
  },
  Voice_147522_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_147523_AwakerVoiceContent = {Text = "Brilla"},
  Voice_147523_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_147524_AwakerVoiceContent = {
    Text = "La sensación olvidada... finalmente regresa al escenario. Gracias, Guardián del Secreto"
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_147524_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "Disculpa la interrupción... ¿podrías bajarme del árbol? No recuerdo por qué subí, tal vez por las nubes nostálgicas"
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "Mi gente nunca me ha dejado, solo se han ido muy, muy lejos"
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "Charla ligera · Sobre los miembros del clan"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "¿Lo oíste?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_147528_AwakerVoiceContent = {Text = "Oh."},
  Voice_147528_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "Parece que siempre estás rondando cerca de mí... Ya lo sé, ¡debes ser mi fan!"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_147529_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "La la la~ ¿Qué? ¿Hay un Clades que puede acabar con el mundo aquí? Ah... Necesito peinarme y encontrar a mi hermana..."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "Shh... No hables, vienen los malos. Quieren llevarse a mi hermana y a mí, y no nos dejarán subir al barco"
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre la Seguridad"
  },
  Voice_147532_AwakerVoiceContent = {Text = "—"},
  Voice_147532_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_147532_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "Cuando desperté, el planeta se estaba destruyendo. Vi cómo el cielo nocturno se desmoronaba, el mundo se convirtió en una lona inflada por el viento, primero deformándose y luego rasgándose y desintegrándose"
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_147533_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "Este es mi cartel firmado, dibujado por el Sr. Pikman. Te lo presento."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "Chat · Sobre Desmayo"
  },
  Voice_147534_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"desmayo\""
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "¿Hmm? ¿Tienes curiosidad? La cámara del tesoro de una Madrina no es para los ojos de los extraños, ya sabes. Si mueres de ganas por saber qué hay guardado ahí dentro... ¿por qué no te unes a la Orden Sagrada ahora mismo...? Jeje."
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "¿No me crees? Buaaa... Supongo que no se puede engañar a todo el mundo... La verdad es que soy la hija bastarda de Bohemundo VI de @1, viviendo oculta entre los mortales, y solo afirmé ser un hada para escapar de la caza de mis enemigos... Te he contado mi secreto más preciado. No irás a no creerme... ¿verdad?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_149668_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_149669_AwakerVoiceContent = {Text = "¡Ay~"},
  Voice_149669_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_149670_AwakerVoiceContent = {
    Text = "¿Demasiados caramelos? No, no, no, este es el secreto de una Madrina para mantener su sonrisa, ya sabes. ¿Acaso me detendría por algo tan insignificante como una caries?"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "Vamos, ponte aquí junto a tu Hada. ¿Qué? ¿Que todos comparten las ofrendas y comen juntos? ...Bueno. Si esa es la costumbre de Misaq... entonces yo... desde luego no tengo ninguna objeción. ¡Vamos, todos, hagamos una fiesta!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_149671_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "Vaya, vaya... qué corderito tan devoto."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "Un poquito más, y entonces el Hada te bendecirá, ¿eh?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "Todavía os falta un poco de experiencia~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "Esta ceremonia de adoración será más grandiosa que cualquier otra anterior, ¡y las ofrendas también deberán ser más numerosas! Pero, ¡cielos, no vamos a cortarles los miembros, claro que no! Soy un hada de buen corazón; jamás haría nada que pudiera hacerle daño a alguien~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_149676_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "Gardian del secreto, ¿estás listo para la confesión más sincera de Caraboo, desde el fondo de su corazón?\nDe dónde vengo no importa en absoluto. Lo que realmente importa es esto: Eres un regalo del cielo para mí, y he decidido quedarme al lado de mi precioso benefactor, para siempre y por siempre. \n¿Que si esto es otra mentira para evitar que sigas hurgando en mi pasado? Jeje, ¿qué crees tú?\nDe todos modos... creo que merezco un pequeño premio por compartir mis verdaderos sentimientos contigo. Un caramelo de goma con sabor a manzana estaría bien, por favor."
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_149677_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_149678_AwakerVoiceContent = {Text = "Jeje~"},
  Voice_149678_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_149680_AwakerVoiceContent = {
    Text = "¡No pasa nada! La próxima vez, concéntrate en proteger a tu Hada y no fallarás~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "¡Ni se te ocurra intentar engañarme!"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "¡Vaaaaya, tanto tributo...! Ejem. Jeje, bien hecho, ¡te has ganado una recompensa! Ven aquí, ¡te concederé el beso de un hada! ...¿En qué estás pensando? ¡En la frente, obviamente!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_149683_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "¡Gracias a todos por sus ofrendas, fieles seguidores! Vuestra siempre comprensiva Madrina también mandará erigir una estatua de oro macizo en vuestro honor en el templo. ¡Cielos! Para capturar esa figura tan fría y elegante, tendré que salir a recopilar bastante más~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_149684_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "¿Tú? ...Eres uno de nuestro rebaño, aún sin iluminar. Caraboo esperará, con paciencia, el día en que veas la verdadera naturaleza del mundo. Y cuando llegue ese día, recuerda ofrecer tu cuerpo, tu lealtad y tus bienes terrenales a la Madrina de todos. Jeje."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "Todo lo de la lista... ¿ya reunido? La fortuna de Misaq es más profunda de lo que puedo imaginar... Si lo hubiera sabido, habría... ¿Eh? ¿Qué estoy murmurando, preguntas? Solo agradeciendo la generosidad del Señor Dexter, jeje~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_149686_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "¿Qué es lo que más odio? Los magos que no respetan un contrato, obviamente. Un pequeño secreto, solo entre nosotros: todos y cada uno de los magos son unos grandísimos farsantes. ¿Todas esas supuestas profecías y maldiciones? ¡Solo son trucos para estafarte y dejarte en la ruina! ¿Y cómo te proteges...? ¡Simple! ¡Deja que todo tu dinero reciba la bendición del Hada!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "¡Qué alegría conocerte! Soy una Hada Pálida de tierras lejanas. ¿Quieres saber más? La bendición de un hada tiene distintas intensidades según tu nivel de membresía, jeje~"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_149689_AwakerVoiceContent = {
    Text = "En las ceremonias de adoración pasadas, además del rito séptuple y el voto triple, los fieles me construían un templo nuevo y presentaban suntuosos tributos. ¡Aquí está la lista!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_149689_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "Vamos... entierra todo lo que desees dejar atrás en lo profundo de la nieve..."
  },
  Voice_149690_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_149691_AwakerVoiceContent = {
    Text = "Me han dicho que has estado preguntando sobre mis orígenes. Jeje, eso es un pequeño secreto de la Madrina. Peeero, si de verdad insistes en investigar, la Orden Sagrada guarda una biografía que yo misma redacté. Tuya a leer por tan solo cien mil Núcleos de plata. ¿Te animas?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_149691_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "Oh, qué lugar tan encantador: tantos niños adorables y subsidios de bienestar generosos hasta el escándalo. Con todo esto, pronto habré ahorrado el dinero para el viaje al Este..."
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "No olvides venerar a tu Madrina, jeje."
  },
  Voice_149693_AwakerVoiceTitle = {Text = "Activar"},
  Voice_149694_AwakerVoiceContent = {
    Text = "Lo siento mucho, pero el dominio del Hada es tierra sagrada: aquí no recibimos a hombres lobo desconocidos... ¿Que el aire huele a mentiras? Su nariz debe estar averiada."
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "Charla: Sobre Ryker"
  },
  Voice_149694_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"ryker\""
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "¿Hmm? Alguien dice que soy un hada falsa... Bueno, me han pillado. Jeje. Pero sé que a ti no te importará... ¿verdad?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "Charla: Sobre los Rumores"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "Mmm, delicioso~♪"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_149697_AwakerVoiceContent = {
    Text = "Vamos, vamos~"
  },
  Voice_149697_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "Corderitos descarriados, vuestro Hada está aquí para lavar vuestros pecados, jeje~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "¿Aún no te has rendido? Está bien, está bien: Caraboo te lo contará ella misma. Verás, Caraboo es la hija de Umapati, diosa de cierta cima nevada que perfora las nubes en el Este... ¿Hmm? ¿Que esa diosa tuvo dos hijos y ninguna hija? Bueno, los registros de lo divino siempre son un poco... incompletos, ya sabes."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_149699_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "¡Ta-chán~ el resplandor del Hada brilla sobre ti ahora. ¡A por ello!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "Está bien, está bien, ¿puedes dejar de investigar? Sé un buen {Male=boy,Female=girl} y abandona esta ruda pequeña investigación, y en secreto compartiré contigo la mitad de mis caramelos más preciados. Sabes, en los campos de batalla de la Cruzada, los dulces eran un tesoro verdaderamente escaso."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_149701_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "La bendición de Caraboo puede curar todas las enfermedades del mundo, incluyendo esta peste negra, por supuesto... ¡Por supuesto que es verdad! Solo tienes que ser lo suficientemente devoto, confiar lo suficiente en Caraboo, jeje."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_149703_AwakerVoiceContent = {Text = "¡Ay~"},
  Voice_149703_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "¡Contempla el resplandor del Hada!"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "¡El rito séptuple, el voto triple—ofrécelos, y compra para ti la absolución del Hada!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "¡Siéntelo!"
  },
  Voice_150079_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_150104_AwakerVoiceContent = {
    Text = "Vaya, ¿cómo te dejó entrar Ogier? Me prometió que mantendría a todos fuera. ¿Que eres su señor...? Ugh, los niños poco fiables son un verdadero dolor de cabeza. Sabes que me esforcé mucho preparando esta reunión. Dime... mitad y mitad en las ofrendas que recaudemos, ¿y haces la vista gorda por mí?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "Charla: Sobre Ogier"
  },
  Voice_150104_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"ogier\""
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "Apresúrate y termina. No te quedes en las calles."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "Él se unió al culto mientras yo dormía, así que no tengo ninguna conexión con él.\nSin embargo, escuché que vino por su propia voluntad, queriendo abandonar su forma humana para convertirse en un \"Marinero\" de pleno derecho... Hmph, otro tonto cegado por el poder."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Chat · Sobre Caecus"
  },
  Voice_36679_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 6 de \"Operación de Investigación\""
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Goliath nunca ha sido un cachorro leal. No puedo entender por qué Miryam lo valora tanto... Si no estuviera encadenado, sería el primero en escapar."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Chat · Sobre Goliat"
  },
  Voice_36680_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 6 de \"Operación de Investigación\""
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "Los marineros no nacen así. Para integrarse, pasan la primera mitad de sus vidas como humanos...\n¡Más te vale tener cuidado! ¡El dueño de tu pastelería favorita podría ser uno de ellos!"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Charla ligera · Sobre el marinero"
  },
  Voice_36681_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 6 de \"Operación de Investigación\""
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "La canción marina desafinada de Celeste, el guiso de pescado ahumado característico del capitán, mantas que olían a pescado y se habían endurecido por la brisa marina... Aunque fue peligroso y tenso, nunca olvidaré los meses que pasamos en el exilio en el mar."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Charla · Sobre el \"Barco Fantasma\""
  },
  Voice_36682_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 6 de \"Operación de Investigación\""
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "Aunque todos en la escuela parecen estar muy ocupados...\nAquí, hay una sensación de paz que nunca antes había experimentado.\nLa sensación de unirse por el mismo objetivo y esforzarse juntos... Hmph, no está mal."
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag·II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 6 de \"Operación de Investigación\""
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "La cama es demasiado dura, el clima es demasiado frío, y el té de la tarde siempre sabe a agua de enjuague de hierba... Tengo mil razones para no gustarme este lugar.\nSin embargo, solo porque \"estás aquí\", podría quedarme a regañadientes."
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Guardián III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 6 de \"Operación de Investigación\""
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "Gracias... ¿Eh? ¿Por qué te estoy agradeciendo? ¡No es obvio! ¡Es por todo lo que hiciste por mí en el mar...\nEspera un minuto, ¿por qué te ríes? ¡Solo quieres verme avergonzado, ¿no!"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre el Guardián · II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 6 de \"Operación de Investigación\""
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "Una vez pensé que había un lazo familiar entre nosotros...\nPero después de todo lo que sucedió, me di cuenta de que esos fugaces momentos de calidez no eran más que un pensamiento ilusorio mío.\nLo que hagas con ella es tu asunto, solo no dejes que se acerque a mí."
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Miryam·II"
  },
  Voice_36686_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 6 de \"Operación de Investigación\""
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "Qué extraño... Esta sensación es realmente extraña.\nMi corazón ha dejado de latir, pero mi cuerpo todavía está caliente... Oye, ven aquí y toca mi mano. Dime que esto no es una ilusión."
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Charla casual · Acerca de \"Despertador\""
  },
  Voice_36687_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 6 de \"Operación de Investigación\""
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "Puede que no haya nacido en el Reino de Leo, pero la Gran Iglesia es donde recibí mi segunda vida. Por lo tanto, ¿por qué no puedo considerar este lugar mi hogar?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre el Hogar"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "Después de años de una plaga invisible, el Dios Padre finalmente escuchó mis oraciones y me otorgó la \"Bendición\" que puede contrarrestar el sufrimiento.\nDe hecho, otorga vida, pero también requiere un precio.\nComo ejecutor, naturalmente debo cargar con la carga en nombre de los bendecidos."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Charla casual · Acerca de \"La Bendición\""
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "Para mí, el estado de ser un Despertador es un regalo del Padre para el alma en Su abrazo. Es una segunda vida, una oportunidad para reparar los arrepentimientos pasados.\nContinuaré con la obra del Padre, cumpliré mis deberes como Su proxy, y aliviaré más sufrimiento."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Charla casual · Acerca de \"Despertador\""
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Déjame expresar mi gratitud una vez más, Guardián, por respetar mis deseos y mantener mi secreto del Comité. Si ellos intervinieran, temo que no me permitirían seguir sirviendo a la Iglesia."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre el Guardián · II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Se desbloquea tras completar la Operación Especial \"Primario de Sangre\""
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "Esa niña es sincera, firme y amable, con un alma brillante y rara. La última vez que conocí a alguien así fue durante el primer capítulo de mi vida."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Charlas Casual · Sobre Ogier"
  },
  Voice_45157_UnlockDesc = {
    Text = "Se desbloquea tras completar la Operación Especial \"Primario de Sangre\""
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Perder la vista no significa que me haya vuelto ciego. Mientras el Padre trajo oscuridad sobre mí, Él también me permitió ver la tenue luz de las almas."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Chitchat·Sobre Visió"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "\nEn aquel entonces, aunque había recibido \"La bendición\", solo era una persona ordinaria. Había demasiados que sufrieron, y demasiados que necesitaban \"La bendición\". Quería salvarlos a todos, pero fallé.\nEste es mi mayor arrepentimiento y mi culpa eterna."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Chitchat·Sobre la Primera Vida"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "Muchos en la Iglesia creen que la \"llama blanca\" mencionada en las \"Sagradas Escrituras\" se refiere a la luz de la luna: un mensajero pálido aparecerá de ella para guiarnos fuera del sufrimiento.\nPero yo sé que la verdadera llama es el alma que arde dentro de ti y de mí"
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Charla casual · Acerca de \"El Fuego Pálido\""
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "De hecho, el Arzobispo me ordenó ocultar mi verdadera identidad. No dio más detalles, pero me advirtió: incluso en los lugares más puros pueden existir sombras, y uno debe permanecer cauteloso, incluso al hacer el bien. Por supuesto, en ti confío plenamente."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Charla Casual: Sobre Ocultar Identidad"
  },
  Voice_45161_UnlockDesc = {
    Text = "Se desbloquea tras completar la Operación Especial \"Primario de Sangre\""
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "¿Ha sido mi canto de alguna ayuda para ti?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "¡Maldita sea, él también es solo un niño! ¿Por qué todos lo respetan tanto? ¡Muéstrame el mismo respeto, ¿entendido?!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Charlas · Sobre Tulu"
  },
  Voice_4909_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Tulu\""
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Oye, ¿sabes qué suelen hacer los otros Despertadores? No me malinterpretes, no quiero amigos, solo... sí, solo revisando"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre la Vida Diaria"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "¡Maldita sea, maldita sea, maldita sea! ¡La próxima vez, arrojaré sus cadáveres a las arañas para alimentarlas!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_4912_AwakerVoiceContent = {Text = "Resplandor"},
  Voice_4912_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_4913_AwakerVoiceContent = {Text = "Ritmo."},
  Voice_4913_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "Un Intento Audaz"
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "No hay necesidad de ser tan apresurado... ¿Hay algo que pueda hacer por ti?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "¡¿Cómo te atreves?!"
  },
  Voice_4916_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_4917_AwakerVoiceContent = {
    Text = "(Interrogando con gran interés)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "La naturaleza es la fuente de mi supremo honor. ¿No se siente como yo?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "¿Qué quieres hacer?"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "¿No está mal, verdad? Ahora, la recompensa. — ¿Qué? ¡No existe eso de que haya almuerzo gratis!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_4921_AwakerVoiceContent = {Text = "¡Vete!"},
  Voice_4921_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_4922_AwakerVoiceContent = {Text = "¡Cuidado!"},
  Voice_4922_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "¡Qué victoria gloriosa...! Grabare este momento en la eternidad."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "Sentí la fuente de impureza... Un paso más cerca de la verdadera forma... ¡Ahhh, déjame desgarra este mundo!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_4924_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "Estamos... listos. Por favor da la orden, Guardián."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_4925_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "Señor, usted es verdaderamente amable. Lamentablemente, no tengo nada con qué recompensarle, ya que soy solo una persona sin valor..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_4926_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "......¿Solo un poco más y estaré completamente separado de \"ellos\"?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_4927_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Eh, sigo vivo... ¿Realmente no me robarás los órganos ni me usarás para experimentos?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_4928_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "La especie nativa de Winkle puede entrar en el cerebro biológico, haciendo que la voluntad exterior fusionada conmigo la tema. Pero ahora, solo es un alma pobre atrapada en un caparazón"
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Bígaro"
  },
  Voice_4929_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"bígaro\""
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Todo, Aigis lo disfruta. Ya sea que todos estén reunidos alrededor de la mesa para una comida y una oración, o la anticipación cuando el Guardián está en una misión, esperando tu regreso triunfante... El aire siempre está lleno de felicidad... ¿Realmente merezco tal alegría?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_4931_AwakerVoiceContent = {Text = "Hundirse."},
  Voice_4931_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_4932_AwakerVoiceContent = {Text = "Florecer."},
  Voice_4932_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_4933_AwakerVoiceContent = {
    Text = "\"Confianza,\" \"Obediencia,\" \"Esclavo,\" \"Afecto,\" \"Respeto\"... Reconstruyendo y aprendiendo el módulo de lenguaje. Por favor, Guardián, guíame."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_4933_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Erica está actualmente en modo de espera. El cuerpo completará el enfriamiento en 1 hora y 15 minutos. <Del:Para empezar, intercambia tu corazón> ¿Inicio de emergencia? ... Verificación de permisos en progreso... Máxima autoridad del Guardián verificada. Hola, Guardián."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_4934_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "El índice de riesgo promedio de las tareas de investigación es de 7, con un consumo promedio de 8 botellas de suplementos de alquimia y un promedio de 10 horas requeridas para el manejo de cadáveres.\nConclusión: El trabajo de los Guardianes es extremadamente peligroso. Por favor, mantente a salvo durante las operaciones."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_4935_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Buscando registros de maestros: Erica Layfield, Profesora de Mecatrónica y Automatización de Plata, Fallecida—¿No es esto lo que buscabas? De acuerdo, buscando nuevamente la palabra clave \"Erica\"."
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_4936_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "Si necesitas buscar información, por favor proporciona el nombre completo del archivo. La función de búsqueda difusa no está disponible actualmente."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_4937_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_4938_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_4939_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_4939_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_4940_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_4941_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "Carga completa, listo para detonar."
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "Carga completa, listo para detonar."
  },
  Voice_4943_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_4944_AwakerVoiceContent = {
    Text = "No molestes el descanso de la princesa con asuntos tan triviales en el futuro."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Te protegeré justo como protejo a Tinct."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "No soy una persona importante, solo un humilde seguidor entre muchos... Mientras pueda servir a ese gran ser y atraer su atención, estoy dispuesto a darlo todo."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre el Pasado"
  },
  Voice_4946_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Tulu\""
  },
  Voice_4947_AwakerVoiceContent = {Text = "¡Mírame!"},
  Voice_4947_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_4948_AwakerVoiceContent = {Text = "¡Mírame!"},
  Voice_4948_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "...Está bien, siempre que no me molesten con su adoración fanática. Compartir una habitación con ellos no es descabellado."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Charla ligera · Sobre el marinero"
  },
  Voice_4949_UnlockDesc = {
    Text = "Desbloquear después de obtener cualquiera de los Despertar \"Miryam\", \"Goliat\", \"Caecus\", \"Sanga\" o \"Faros\"."
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "Odio esa sensación oscura, como si mi corazón hubiera sido vaciado. La sensación no cumplida hace que todo mi cuerpo picotee..."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "No, no, no, no, no lo menciones..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_4953_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_4953_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_4954_AwakerVoiceContent = {
    Text = "...¡Está bien!"
  },
  Voice_4954_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_4955_AwakerVoiceContent = {
    Text = "Los historiadores que proclaman ruidosamente la extinción del Reino Divino son molestos... Pero no importa; sus palabras no pueden impedir el reavivamiento de la gloria del Reino Divino."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "En realidad... déjame contarte un secreto. No estoy del todo satisfecho con mi motocicleta actual—¡no es que no me guste! Simplemente siento que falta algo..."
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_4957_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_4958_AwakerVoiceContent = {Text = "¡Cortar!"},
  Voice_4958_AwakerVoiceTitle = {
    Text = "Habilidad·II·Manía"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Lo siento... No quería que esto sucediera..."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Habilidad·II·Depresión"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(Susurro intrigado)"
  },
  Voice_4960_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_4961_AwakerVoiceContent = {
    Text = "En el año @1@2, el Sr. Ward Phillips, Krelarkesh y Tawil fundaron juntos el Colegio Mythag. Después de un largo desarrollo, finalmente dio a luz a <Del:esta maldita prisión> la Universidad Mythag."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Justicia, lealtad, resiliencia, disciplina. Estos han estado grabados en mi corazón durante mucho tiempo."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "Completaré correctamente la tarea que me asignaste."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "¿Qué clase de padres irresponsables nombrarían a su hija Escudo de Banshee? ¿Dices que la niña no tiene padres? Hmm... mantengamos esta conversación entre nosotros"
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Chat · Sobre Aigis"
  },
  Voice_4964_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Aigis\""
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "Si estás aburrido, ¿por qué no \"me haces compañía\" en el laberinto? Después de todo, tu vida desesperada no es diferente de este laberinto sin fin"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Chat · Sobre el laberinto"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "Cuando la Muñeca está cerca, la eficiencia de los investigadores aumenta en un 78.312%, pero más personas también caen en crisis emocionales. Como ella lo expresó: \"Si algunas personas pudieran mantener la boca cerrada, el mundo funcionaría más suavemente.\""
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Chat · Sobre Muñeca"
  },
  Voice_4966_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"muñeca\""
  },
  Voice_4967_AwakerVoiceContent = {Text = "¡Llegada!"},
  Voice_4967_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_4968_AwakerVoiceContent = {
    Text = "¿Qué tal?"
  },
  Voice_4968_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "¿Quién no amaría la aventura? Adentrándose en reinos misteriosos inexplorados, descubriendo lo desconocido y tejiendo tu propia historia... ¡Qué emocionante!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Charla Casual · Sobre Aventuras"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Saludos, soy Nymphaea de Febvre. Me has dado este cuerpo que respira libremente... ¿Qué puedo hacer para recompensarte?"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_4971_AwakerVoiceContent = {
    Text = "Creo que acabo de escuchar a aquellos que afirman ser mis maestros lamentándose nuevamente — qué agradable."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_4971_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "¿Puedo saltarme las verduras? Aunque Tinct dijo que no fuera exigente, no me gustan sus colores..."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "Relic Palabras de Dios: El sufrimiento no es mi creación. Soporta y disuélvelo, mi representante, y construye una tierra sin sufrimiento. Por esto, ofrezco todo, incluso la vida."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_4973_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "Frente a la Maldición Derretidora, todos los demás sufrimientos son insignificantes. Incluso si no puedo soportar la maldición por otros, haré todo lo posible para aliviar su dolor."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_4974_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "¿Ahora puedo aliviar su dolor y confortar sus almas?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_4975_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "Así, soportaré todo sufrimiento, allanando el camino para que todos los seres lleguen a una tierra libre de dolor."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_4976_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "Este calor profundo en mi alma... Gracias por este regalo, el Fuego Pálido. Con este Poder, quizás finalmente pueda cumplir con mi deber como Auxiliar y salvar a más personas."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_4977_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "¿Realmente puedo comer tanto?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_4978_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Hmm... Eso no es la muerte; es simplemente tu futuro, mi futuro y el futuro de este mundo."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "La Tintura... Escuchar su canción melancólica te da ganas de bailar..."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Chit-chat·Sobre Tinctura"
  },
  Voice_4980_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"tintura\""
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "¿Puede el entrenamiento ordinario también despertar el potencial de la sangre de uno? Esto realmente está más allá de mis expectativas."
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "La arma se siente más manejable."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "¡No supongas que estaré agradecido por esto; mi raza no lo permite!"
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_4984_AwakerVoiceContent = {Text = "Ah, ¡uh!"},
  Voice_4984_AwakerVoiceTitle = {Text = "Activar"},
  Voice_4985_AwakerVoiceContent = {
    Text = "Ese hombre... Hey, espera un momento, ¿nuestra apuesta no ha terminado aún, verdad?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Otros"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "Realmente me gusta el grabador de la academia. Si tan solo pudiera crear una versión portátil que me recordara en tiempo real lo que he olvidado..."
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Migajas por todas partes... No, ni siquiera migajas, solo restos, brindando alimento para Su llegada."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "Los suministros están aquí."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "Los suministros están aquí."
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "Hmm... Más duro, más duro. Sí, así está bien..."
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "Aún no completamente Despertado, pero la victoria llegó sin esfuerzo."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "¡Oh no, mi sombrero está torcido... Hmm, ¿esto está mejor? ¡Perfecto!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_4992_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"Con tal habilidad, ¿soy realmente todavía humano?\" Desde que comencé el entrenamiento de combate, me he preguntado esto todos los días. Amo este mundo, a pesar de su oscuridad, suciedad y monotonía, pero tu presencia lo hace brillar como diamantes entre el polvo.\nUna vez temí que a medida que mi poder creciera, mi postura como humano cambiaría... Ahora, estoy agradecido de tenerte a mi lado. Nuestro vínculo me ancla firmemente al mundo humano. Por favor, continúa cuidando de mí, Guardián."
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_4993_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Ah... Es natural que tengas preocupaciones. No lo pensé bien. Como tu pareja, debería haber explicado esto desde el principio. Como puedes ver, poseo algunas características inusuales, probablemente relacionadas con mi pasado. Es imposible no ser curioso, ¿verdad? Pero tener un lugar como la academia es una bendición para mí, así que elijo no levantar el velo del destino."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_4994_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "¿Has conocido a esa mujer, verdad? La Despertadora con un velo blanco—ella es una de las fundadoras de la universidad...\nPero honestamente, no me gusta. Esa actitud distante, como si no le importara el mundo en absoluto, realmente me molesta... Oh, ¿crees que se parece a mí? Vamos a revisar tus ojos en la clínica del campus."
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_4995_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "¿Tienes curiosidad sobre mi relación con el profesor? No es un secreto, así que te lo diré. El profesor Dexter es mi padre adoptivo. En cuanto a mi madre adoptiva... crecí en la escuela y fui cuidada por todos los profesores. Sin embargo, entre ellos, soy más cercana a Muñeca."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_4996_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "Ya sean los procedimientos en la Oficina de Asuntos Despertadores o la cita para comida india en la cantina, puedo responder cualquier pregunta sobre los asuntos de la academia—no te preocupes por molestarme. ¿Acaso me veo tan inaccesible?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_4997_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Espejo, espejo, ¿quién es el mayor mago del mundo? ¿Yo? ¡Eso es correcto!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_4998_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "No está nada mal."
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "¡Muy agradable!~"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_5001_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5002_AwakerVoiceContent = {
    Text = "¿Funcionó...? ¿Pude asistirte?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5003_AwakerVoiceContent = {Text = "¡Inútil!"},
  Voice_5003_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5004_AwakerVoiceContent = {Text = "(Resistir)"},
  Voice_5004_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "¡Mira hacia aquí!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "¡Que este lugar se convierta en un mar de emoción para todos!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "¿Necesitas un guardián que te acompañe? Si tu búsqueda es justa, te ayudaré."
  },
  Voice_5007_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5008_AwakerVoiceContent = {
    Text = "No se puede quemar completamente."
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "No se puede quemar completamente."
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "¿Quieres un abrazo?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Mira estas cadenas en mí—no son decoraciones, sino recordatorios. Recordatorios de traición y humillación."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "Si quieres saber sobre el pasado de la academia, te sugiero que revises los archivos.\nVamos, incluyendo su predecesora, ¡esa es una historia que abarca 300 años! ¿Realmente esperas que la cuente año por año?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "¿Es esta una provocación? ¡Estoy listo en cualquier momento!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "Aequor te otorga descanso eterno."
  },
  Voice_5014_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5015_AwakerVoiceContent = {
    Text = "Aequor te otorga descanso eterno."
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "¡Hundirse y arder! ¡Danza de la destrucción!"
  },
  Voice_5016_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5017_AwakerVoiceContent = {
    Text = "Aquí presento, ¡el Baile de la Destrucción de la Llama Verde Eterna!"
  },
  Voice_5017_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5018_AwakerVoiceContent = {
    Text = "Esa dama, como un faro... Si hubiera podido ver su luz deslumbrante durante la eterna travesía nocturna, tal vez no me habría perdido..."
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Chat · Sobre Faros"
  },
  Voice_5018_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Faros\""
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "Es mejor que te demuestres digno de hacerme salir del laboratorio, nuevo Guardián."
  },
  Voice_5019_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5020_AwakerVoiceContent = {
    Text = "Soy el maestro, y tú eres el sirviente. Lo que desee debe ser entregado de inmediato. ¿Cuál es el problema? ¿Esperas una recompensa? Muy bien, muy bien, ¡tómala!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "Desgracia, ¡deja que este movimiento te limpie!"
  },
  Voice_5022_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5023_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_5023_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_5024_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5025_AwakerVoiceContent = {
    Text = "Dar es recibir."
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "Dar es recibir."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "¡Te lastimarás!"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "¡No te acerques más!"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "Amo la luz de luna dorada durante una luna llena. Es misteriosa y suave. Cuando sopla el viento, el mar brilla con fosforescencia dorada, como un romance de ensueño."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "Si nuestro hogar no hubiera experimentado la Disolución, Tinct y yo no estaríamos separados... Odio la Disolución más de lo que odio las verduras."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "Ya sea que lo que se encuentre adelante sea un tesoro o un puerto, no me hace ninguna diferencia. Mi misión es asegurar tu regreso seguro."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5031_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Sigue el rastro del pájaro del paraíso; el destino está adelante en el azul celeste."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5032_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "A menudo contemplo el horizonte, imaginando las escenas más allá—una tierra lejana a la que me acerco, pero que nunca puedo alcanzar. Si algún día llega, por favor ven conmigo a verla."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5033_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Gracias por tu amabilidad. Ahora, ni siquiera el mar furioso puede disuadirme de entregarte mis constantes bendiciones."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5034_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "Se siente como escuchar las canciones de los remeros, el sabor familiar del hogar."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5035_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "¿Estás aquí para salvarme? De este mundo en decadencia, del odio que mancha mis ojos, de las llamas verdes eternas..."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "¡Rufián insolente!"
  },
  Voice_5037_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5038_AwakerVoiceContent = {
    Text = "Considero esto mi juramento de lealtad hacia ti."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5038_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "¡Aprende tu lección!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5040_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5040_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5041_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5041_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5042_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5042_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5043_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "¡Siente el poder de la rata!"
  },
  Voice_5044_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5045_AwakerVoiceContent = {
    Text = "¡Siente el poder de la rata!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "Los dados ya han sido lanzados. ¡Así que terminemos esto rápidamente!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "Incluiré tu nombre en mis agradecimientos. Eres tú quien permitió que estos pies, manchados de sangre oscura, volvieran a pisar el maravilloso mundo del ballet. A partir de ahora, por favor, mírame bailar, Guardián."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5047_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "No importa cuánto luches, no puedes desafiar al destino. Pero ese fugaz momento de brillantez se congelará en la eternidad."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5048_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "¿Qué debemos hacer con estos derrotados?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Incluso si mi corazón no guarda más anhelos, aún desempeñaré el papel del cisne."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5050_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Cierra los ojos y dime, ¿qué ves? Luz de luna inmaculada, un lago tranquilo..."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5051_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "¿Por qué las calamidades de destrucción y desdicha me envuelven a mí y a mi hermana?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Acepta mi afecto."
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "Acepta mi afecto."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "Me siento mucho mejor ahora, gracias."
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5056_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5056_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "Si es posible, me gustaría ofrecerte un lirio de agua de color púrpura pálido como símbolo de mi gratitud."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "¿Puedo volverme más fuerte también?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "¡Aquí vamos...!"
  },
  Voice_5059_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5060_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5060_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "¿Esta pierna herida? Me sorprende que lo hayas notado. Es del campo de batalla antes de convertirme en Despertador.\nNo te preocupes, ya no interfiere con mis batallas.\n¿Dolor? No, no he pensado en eso."
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5061_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "Silvia preguntó por mi estado mental, ¿fuiste tú quien la llamó? Admito que el dolor fantasma aparece de vez en cuando. Pero no te preocupes por mí. Soy tu espada, tu filo, mientras pueda luchar por la justicia, el dolor no me afectará"
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5062_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "¡Té, té, hagamos una fiesta de té! ¡Conseguí muchas hojas de té y dulces de Silvia! Sí, los cambié por un baile de Fortvoken"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "¿Mi título autoproclamado? ¿Realmente estás tan interesado en mis asuntos personales? ¿Solo quieres charlar... está bien.\nEn el ejército, no diferenciamos entre camaradas según el género, incluyendo la fuerza y velocidad, y naturalmente, también peinados y títulos. Con el tiempo, me he acostumbrado a esta forma de expresión."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5064_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "Interesante... ¿No tienes miedo de que te desmembre y te alimente a los peces una vez que gane poder?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "Para ser digno de ser mi Guardián, ¡has trabajado duro!"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "Es hora de desgarrar las gargantas de unos pocos débiles y darles una oportunidad."
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "Bailar es puro. Las palabras pueden llevar a malentendidos, pero los pasos de baile nunca lo hacen."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre el Baile"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "Odio el mar, y por buenas razones. El océano devoró todo lo que amaba..."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "Ya sea olvido o pérdida, esta vez definitivamente ¡regresaremos!"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "Ya sea olvido o pérdida, esta vez definitivamente ¡regresaremos!"
  },
  Voice_5071_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5072_AwakerVoiceContent = {
    Text = "Por favor, por favor, no te acerques más. Es peligroso."
  },
  Voice_5072_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5073_AwakerVoiceContent = {
    Text = "Siéntete libre de tocar... Estas son cicatrices de la arena, ¡una insignia de honor de un hombre!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(Exclamación)"
  },
  Voice_5074_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5075_AwakerVoiceContent = {
    Text = "¡Ay, ay, ay!"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "(gruñido de dolor)"
  },
  Voice_5076_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5077_AwakerVoiceContent = {
    Text = "(Gruñido indiferente)"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "Se siente como si algo estuviera hirviendo dentro del Cuerpo. ¿Es esto lo que se siente al someterse a Iluminar?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5078_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "¿Es algún tipo de nueva tecnología? Mi extremidad prostética se siente mucho más ligera."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5079_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "La salada brisa del mar me dice que mi patria no está lejos."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5080_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "¿Pueden los camaradas fallecidos encontrar su camino de regreso siguiendo esta luz?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5081_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "He estado buscando durante decenas de miles de años; un siglo fugaz no es nada. Hasta que llegue a tu costa, seguiré ayudándote."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5082_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "Solo brillaré por mi patria. Tú..."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5083_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "Sentí la brisa, llevando arena fina a través de mis pies."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5084_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "El alcance de mi contribución a tu poder termina aquí. Ser demasiado codicioso no es bueno, ¿sabes?"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5085_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "¿Qué esperas que devuelva? ¿Solo una batalla?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5086_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Cráneo de amor, cráneo de resentimiento, cráneo de odio, cráneo de deseo... Oh, ¿has vuelto?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5087_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Dado que es una transacción, no puedo simplemente aceptar tu regalo. ¿Te gustaría elegir algo de la tienda?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5088_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "Te enseñaré alegría, diversión, la emoción de alcanzar la cima... A cambio, debes revelar tus deseos honestamente, ¿de acuerdo?"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Guardián 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "Soy el Árbol Madre, y el Árbol Madre soy yo. La savia fluye por mis venas, y la voluntad del árbol persiste en mi mente..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre el Árbol Madre"
  },
  Voice_50899_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 7 de la \"Operación de Investigación\""
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "¡Paga el precio por tu traición!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "Creo que vi tu lápida mientras buscaba un lugar escondido en la Tumba Llave... ¿Mi momia también será enterrada aquí? ¿No? Qué lástima."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Montículo de Llaves"
  },
  Voice_50900_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 7 de la \"Operación de Investigación\""
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "El chico lobo... Tiene una relación ambigua con esa N..."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Chat·Sobre Ryker"
  },
  Voice_50901_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"ryker\""
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Acércate, abrázame, pruébame... no me olvides."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Guardián 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 7 de la \"Operación de Investigación\""
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "Ella era una niña excesivamente diligente y cautelosa. Por supuesto, no la culparía~ Sin ella, la tribu de espíritu libre habría sido destruida en medio de los cambios hace mucho tiempo, ¿verdad?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Charlas: Sobre Alva"
  },
  Voice_50903_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"alva\""
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Nacida de las arenas amarillas, y a las arenas amarillas has de regresar. En este breve viaje, ¿no deberías dejar algo atrás y sembrar algunas semillas?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Charla ligera·Sobre el desierto"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "Todos los deseos provienen del amor; el amor es la semilla inicial antes de que el árbol imponente cobre vida."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Deseo"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Oh querido, un lindo ratoncito acaba de pasar corriendo... He oído que a los ratones les encanta escabullirse, pero lamentablemente, este todavía es muy joven, prácticamente un recién nacido."
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Jenki"
  },
  Voice_50906_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Jenkins\""
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "Llevaron mi sangre y linaje, transformándose en las aguas florecientes de Lemwahi... A partir de este día, depende de ti asegurar que mi legado perdure."
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Charla ligera·Sobre Alan"
  },
  Voice_50907_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 7 de la \"Operación de Investigación\""
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Arañas... arañas. Hmm~ Me encantan las arañas. Nacen con el poder de caminar, y sus habilidades reproductivas y de supervivencia son realmente envidiables..."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Agrippa"
  },
  Voice_50908_UnlockDesc = {
    Text = "Desbloquea después de obtener el despertador \"Agrippa\""
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Todos los seres con la sangre del árbol fluyente son mis hijos. Eso incluye a ti, que has tragado las semillas del árbol, ¿verdad?"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Descendencia"
  },
  Voice_50909_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 7 de la \"Operación de Investigación\""
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "¿Mis mercancías? Podrías decir que tengo todo para satisfacer todos tus deseos... por un precio."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5090_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Oh querido, debo admitir que he perdido contra ella esta vez... Pero afortunadamente, dado que te ha elegido, beberás la savia del árbol y llevarás mi sangre y semillas a un nuevo mundo, ¿verdad?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Tawil"
  },
  Voice_50910_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Ramona\""
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "Como una de las tres esencias principales, ese tipo es un monstruo inescrutable. No te dejes llevar fácilmente por sus dulces palabras, o me romperé el corazón..."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Charlas · Sobre N"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "Mientras haya conciencia, hay deseo. Incluso los seres mecánicos no son una excepción, ¿verdad?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Erica"
  },
  Voice_50912_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"erica\""
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "¡Paga el precio por tu traición!"
  },
  Voice_5091_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5092_AwakerVoiceContent = {
    Text = "¡Bienvenido al increíble reino!"
  },
  Voice_5092_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5093_AwakerVoiceContent = {
    Text = "(Número bajo)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "Conozco bien el dolor de esculpir y el ardor de la transformación. Sin embargo, todo esto se desvanece en insignificancia comparado con la belleza eterna."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5094_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "Las palabras no dichas te serán comunicadas a través de mi obra."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5096_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_5097_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "El soberano durmiente murmura en mi oído, las ruinas del fondo del mar se reconstruyen constantemente ante mis ojos... ¿Se han hecho finalmente realidad las innumerables escenas de sueños?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5098_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Gracias por preparar el estudio para mí. Todo aquí está bañado en luz solar. Parece que cada pieza de trabajo, cada cuchillo de tallado, brilla con una luz dorada. Oh, la primavera es dorada."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5099_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Aunque nuestros temperamentos son diferentes, admiro verdaderamente a esa niña. Ella posee un coraje que trasciende todas las dificultades y limitaciones. Si hubiera sido tan valiente y resistente como ella, quizás no habría elegido terminar mi vida en el mar..."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Murphy"
  },
  Voice_5100_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Murphy\""
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "La Dama Roja es diferente a cualquier señor que haya servido... No, no es que la desee; es solo... un poco difícil de manejar..."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Charla ligera·Sobre Sorel"
  },
  Voice_5101_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Sorel\""
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "¡Abraza la locura!"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "Apenas aguantando."
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5104_AwakerVoiceContent = {
    Text = "¡Exterminar!"
  },
  Voice_5104_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5105_AwakerVoiceContent = {
    Text = "No tienes que..."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "El corazón es un abismo sin fondo, que nunca podrá llenarse."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "Sin dolor, sin picor, pero... aún así extremadamente agradecido."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "Ah... ¿Me estás dirigiendo la palabra? Lo siento, solo estaba recordando la vista desde el palo. ¿Podrías repetir tu pregunta?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre el Pasado"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "Tanto un maestro como una madre."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "¡Una apertura!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "¡Una apertura!"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5112_AwakerVoiceContent = {Text = "Listo—"},
  Voice_5112_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5113_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_5113_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5114_AwakerVoiceContent = {
    Text = "Empuja un poco más fuerte~"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "¡Amor Abrasador!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "D-fenómeno... No puedo revelar mucho. Sin embargo, su aparición es mucho antes de lo que piensas."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5118_AwakerVoiceContent = {Text = "Hmm—"},
  Voice_5118_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5119_AwakerVoiceContent = {Text = "Bien."},
  Voice_5119_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5120_AwakerVoiceContent = {Text = "Partamos."},
  Voice_5120_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5121_AwakerVoiceContent = {
    Text = "Heh, nuestra princesa de marioneta está llorando de nuevo. ¿No le queda bien la botella, o la canción de cuna está desafinada?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Murphy"
  },
  Voice_5121_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Murphy\""
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Boohoo... No quiero enfrentarme a esas cosas..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Ahora, es mi turno de recompensarte."
  },
  Voice_5123_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5124_AwakerVoiceContent = {
    Text = "La oleada de poder se siente como llamas abrasadoras quemando hasta los huesos."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "Ah... ¡Lo siento, por favor no te muevas!"
  },
  Voice_5125_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5126_AwakerVoiceContent = {
    Text = "El calor al alcance..."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "Las rosas en el patio están en plena floración."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "¡Buen trabajo! ¿Aún tienes energía para seguir adelante?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "El caballero es una entidad intangible, formada por lealtad, valentía y virtud. Mi arma es la misma, dada forma por la voluntad de proteger: una lanza y un escudo."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Charlas: Sobre Caballeros"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Jenkin, Diana, Mike, Tyug, Marrón... ¡Vaya! Perdón, solo estaba hablando conmigo mismo. ¿Por qué preguntas por qué estoy recitando estos nombres? Porque Aigis no quiere olvidar a nadie..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Amigos"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "¡No te acerques a mí!"
  },
  Voice_5131_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5132_AwakerVoiceContent = {
    Text = "¡No puedo soportarlo!"
  },
  Voice_5132_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5133_AwakerVoiceContent = {Text = "¡Ah~ hey!"},
  Voice_5133_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5134_AwakerVoiceContent = {Text = "¡Ah~ hey!"},
  Voice_5134_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "Gracias por tu convocatoria. Si hay una ocasión en la que se necesite mi voz, por favor notifícame con anticipación."
  },
  Voice_5135_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5137_AwakerVoiceContent = {
    Text = "Eso... es el líquido negro viscoso que surge a través de las venas, ¡el poder supremo que silencia todos los gemidos! \"Yo\" nací de esto, ¡nací para destruir! ¡Jajaja!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "¿Me estás llamando, quieres apostar? ...¿Qué, una investigación? No, eso es un desperdicio de suerte..."
  },
  Voice_5138_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5139_AwakerVoiceContent = {
    Text = "La clase de teoría es bastante aburrida. Leo en secreto los registros de investigación en la parte trasera del aula. Solo te lo digo, no dejes que la Muñeca lo sepa."
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "¡Prueba las amargas consecuencias!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "¡Prueba las amargas consecuencias!"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "Nunca culpé a Juliette; ella era meramente una víctima del sufrimiento negro. Pero... parece que no quiere escuchar esto de mí. ¿Podrías transmitirle esto por mí, Mensajero?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Juliette"
  },
  Voice_5142_UnlockDesc = {
    Text = "Voz no implementada aún"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "Reduce la velocidad."
  },
  Voice_5143_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5144_AwakerVoiceContent = {Text = "Bien."},
  Voice_5144_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "¡Oye! ¡Deja de tocar cosas, estás haciendo un desorden! ...Oh bueno, dejaré pasar esta vez porque soy generoso."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "¡No es necesario!"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5147_AwakerVoiceContent = {Text = "¡Tsk!"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "Desde el día en que me despertaste de la oscuridad, he estado seguro de que puedes salvar a todos de la desesperación conocida como Disolución y guiarlos hacia las tierras Puras. Espero este día."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre el Guardián · I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "Huelgo... el olor de la sangre."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "¿Dónde está el objetivo? Como un símbolo de gratitud por despertarme, me encargaré de ellos por ti."
  },
  Voice_5150_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5151_AwakerVoiceContent = {
    Text = "¡Mi sombrero no puede esperar más!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "Esta concha no debería agitarse por nadie más que por Él... Sin embargo, tu calidez..."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "¿Qué tal una pelea?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "Profanador..."
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "Imperdonable."
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "Erica está funcionando normalmente y está bien conectada al equipo eléctrico de la Universidad de Mitag. ¿Necesitas que encienda las luces del dormitorio?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Erica"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "¡A continuación, es hora de comer, hehe..."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "¡No dejes que la mujer del sombrero morado de ala ancha se acerque al escenario! Sin preguntas—simplemente mantenla alejada si no quieres que salga materia gris pegajosa de su sombrero"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Narcisos"
  },
  Voice_5159_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Daffodil\""
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "¿Siempre eres así? ¿Confiando en todos y dándoles la espalda? Demasiado ingenuo."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "El odio puede ser aliviado, pero nunca puede ser borrado."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "¿Despertador? Hmm... ¡Sí, las 7 AM es la mejor hora para despertar! ¡Vamos a recolectar conchas en la playa mañana por la mañana a las 7!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Charla · Sobre Despertador"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "¡Concede vida eterna!"
  },
  Voice_5163_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5164_AwakerVoiceContent = {Text = "¡Hah!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5165_AwakerVoiceContent = {Text = "¡Hah!"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "Lo siento, si Aigis te está causando algún problema, ¡me iré de inmediato!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5166_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "Tú me proporcionaste un lugar donde quedarme, y estoy agradecido. Pero perdóname, ya no merezco estar de pie en el escenario otra vez."
  },
  Voice_5167_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5168_AwakerVoiceContent = {
    Text = "Gracias por permitirme quedarme aquí. Si hay alguna manera en la que pueda recompensarles, por favor háganle saber a Aigis. ¿Les gustaría un poco de té?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5168_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "Es tan cálido que no quiero irme. Cuando estoy solo, realmente está oscuro, frío y aterrador..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5169_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Aigis... ¿Realmente puedo volver a la multitud? No estoy lista todavía, pero ya me has aceptado... En ese caso, por favor, continúa cuidando de mí... Guardián."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5170_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Recuerdo, recuerdo...! La sangre sucia de los humanos me atrapó... ¡No podía transformarme! ¿Cómo, cómo... dónde están mis branquias? ¿Por qué no se mueven?! ¿Por qué!"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5172_AwakerVoiceContent = {
    Text = "Me encanta el pulpo a la parrilla, el pulpo hervido, el pulpo frito... Algunos dicen que estoy cometiendo blasfemia. Lo siento, pero el pulpo es tan delicioso, ¡ja, ja, ja!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Gusanos. Estrellas. Yo soy... Uvhash! ¡Matar... déjame matar!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5173_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Cuerpo carmesí, tentáculos pulsantes, partes bucales abriéndose y cerrándose constantemente... ¡Genial, genial! ¡No puedo esperar para desgarrar la garganta de alguien!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5174_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Hahaha, ¡esa es la sensación! Dame más... ¡el doble, no, diez veces la dosis!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5175_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "Lo soportaré."
  },
  Voice_5176_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5177_AwakerVoiceContent = {
    Text = "Esta extraña sensación... no está mal. Mejor que la belladona del mago levantino."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5177_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "¿Compañeros? Hmph... No necesito ninguno. No me voy a cargar dos veces con la misma carga."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5178_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "Cooperaré contigo solo porque has demostrado suficiente fuerza para igualar la mía. No olvides, este contrato terminará cuando tu poder disminuya, y no dudaré en cortarte la cabeza."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5179_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "A tus ojos... veo un destello, el feroz fuego de la ambición y el deseo. ¡Mortal, conócete a ti mismo! ¡Somos espíritus afines!"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5180_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "¿Conoces al albatros? Se enfrenta con valentía a las tormentas, pero una vez desterrado al suelo, rodeado de burlas, esas alas gigantes y caídas se convierten irónicamente en un patético estorbo. En fin, esta historia no significa nada... Simplemente me vino a la mente porque me siento muy relajado estando contigo — solo una charla casual."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5181_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "Quizás, los tiempos han cambiado verdaderamente. Ahora, incluso los frágiles pueden superar los arrecifes, comandar las olas y convertirse en el Rey de los Cielos.\nMortal, espero el día en que reescribas la historia. ¡Será un honor para mí convertirme en la poderosa espada en tu mano!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5182_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "La tasa de conversión es demasiado baja. Preséntate en mi oficina mañana para reentrenamiento."
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "¿Has conocido a otra Muñeca? La llamada \"verdad del mundo\" puede convertir a una Muñeca tan tranquila y racional en una persona completamente diferente... Al final, ¿tú y yo también nos volveremos así?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre @2"
  },
  Voice_5184_UnlockDesc = {
    Text = "Desbloquear después de obtener el Despertar@2"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Master... necesito órdenes. Por favor, dame órdenes."
  },
  Voice_5185_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5186_AwakerVoiceContent = {
    Text = "El rendimiento del mech ha sido mejorado."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5189_AwakerVoiceContent = {
    Text = "Hmm-hmm-hmm!"
  },
  Voice_5189_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "¡Más aliados!"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "¡Más aliados!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "Lo siento, no puedo salir de la cuna... Puede bloquear la vista de todos, así que me quedaré en la parte trasera del aula."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "¡¿Qué!? ¿Ni una sola alfombra de Constantinopla, té de Ceylan, o churros de Andalucía...? Ugh... esa mujer siempre consigue esas cosas tan fácilmente. Pensé que eran comunes..."
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Todavía estoy lejos de mi forma original."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5194_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "Tan ansioso, parece un poco grosero para alguien de tu calibre."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "No importa cuántas mejoras tenga, la apariencia de esta bestia no cambiará. Después de todo, es meramente una manifestación de mi poder."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5196_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "Se siente como estar de regreso en el océano caótico, no está mal"
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5197_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "A la luz de tus enormes esfuerzos, te aceptaré de mala gana como compañero."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5198_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Romper las barreras del Poder, como si destrozaras las paredes de un Laberinto."
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5199_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "No puedes romper la comida o aplastar los bancos de la cafetería... Está bien, Lily no lo hará la próxima vez."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5200_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "¿Puedo llamarte Madre?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5201_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "¿Hay alguna orden, maestro? \n\"¿No los saques afuera, todos se asustarán?\"\nLily entiende y los esconderá de inmediato."
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5202_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "Así que, así es como es convertirse en un Despertador."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5203_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Madre, ¿puedo dormir al lado de ti? Cuando estoy sola, tengo sueños oscuros y aterradores. Las manos y pies de Lily se cayeron... Realmente duele."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5204_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "¡Ah! Gracias por tu amabilidad, Karen es solo una humilde sirvienta..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5205_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Hmph~"},
  Voice_5206_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "Necesito reunir algunos materiales de talla, preferiblemente frescos."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Por favor, guarda silencio."
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "Aquellos que se mantienen tercos en su necedad realizan actos fútiles."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5209_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "En este punto, puedo entender algo tu intención. Está bien, continúa."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5210_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "Veo tu determinación. Antes de que vuelva a dormir, seré tu testigo, presenciando la resistencia del destino por parte del hijo del hombre. Pero por ahora, necesito un poco de descanso."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5211_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "¿No es bueno seguir la voluntad del cielo? ¿Por qué resistirse a la voluntad del destino?"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5212_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "Para cumplir tu deseo, estás dispuesto a sacrificar tanto..."
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5213_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "¿Eh? ¿No es molesto? ¡Deja de molestarme con ese tipo! ...Está bien, haz lo que quieras. De todos modos, solo es para matar el tiempo."
  },
  Voice_5214_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5215_AwakerVoiceContent = {
    Text = "Disolución... Esos líquidos negros sucios a menudo invaden mis sueños, verdaderamente insoportables."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "El poder es una espada de doble filo. ¿Cómo podría no entenderlo? Solo que me di cuenta de ello demasiado tarde, demasiado tarde. Una vez que suelte, ellos me desgarrarán... Si hubiera tenido la mente tan clara como tú desde el principio, no habría encontrado un final tan trágico. ¿Eh, eh? ¡Dices que en el futuro podré organizar salones en el salón?! Esto es... ¿Cómo más puedo recompensarte además de servirte personalmente..."
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5216_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "Eres un huésped bastante inflexible. ¿Qué debo hacer para que renuncies al privilegio en tus manos? El poder solo invita a problemas—una verdad tan simple, seguramente la entiendes, ¿no?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5217_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Antes de que comience el salón, ¿te gustaría escuchar una historia? Un cuento sobre cómo una chica de pueblo reclamó la corona del poder... ¿Dónde deberíamos empezar? Desde que sus padres la obligaron a casarse con un hombre anciano, o quizás prefieras la parte en la que florece en el jardín noble?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5218_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "En el pasado, los invitados me llamaban \"Dama Roja\". Por supuesto, también puedes llamarme \"Sorel\", después de todo, eres mi invitado más especial..."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5219_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "A medida que la anfitriona del salón, es mi deber asegurarme de que cada invitado esté satisfecho."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5220_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5221_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "¿Maestro? ¿Hay algo mal con mi postura?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5223_AwakerVoiceContent = {Text = "¡Ups!"},
  Voice_5223_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5224_AwakerVoiceContent = {
    Text = "Mala suerte~"
  },
  Voice_5224_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5225_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_5225_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5226_AwakerVoiceContent = {
    Text = "Recuerdo este sentimiento... El momento glorioso se aproxima."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5226_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "Aunque las marcas branquiales aún no han aparecido, ya no me siento ansioso al respecto. Esta ala de membrana se transformará en un escudo para protegerte, Guardián."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5227_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "Tú... eres, de hecho, más paciente que otros humanos... Has invertido tantos recursos en mí. ¿De verdad... no me odias?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5228_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "¿Eh? ¿El ritual ha terminado, pero aún no he crecido branquias? ¿Falló la transformación otra vez?! ¡Maldita sea! ¡Maldita sea! ¡Maldita sea!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5229_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "Esa voz me llama de nuevo... ¡el sonido etéreo desde las profundidades de Aequor!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5230_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Adivina—incorrecto—otra vez—"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "Sanga, la escultora de Cité, te ofrece su cincel. Puede que seas imperfecto, pero aún vales la pena ser tallado."
  },
  Voice_5232_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5238_AwakerVoiceContent = {
    Text = "Los niños que no escuchan, ¡reúnanse!"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "El arte verdadero no necesita explicación."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "El arte verdadero no necesita explicación."
  },
  Voice_5240_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5241_AwakerVoiceContent = {
    Text = "Aurita, ¿puedes ayudar?"
  },
  Voice_5241_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5242_AwakerVoiceContent = {
    Text = "¡Toca la trompeta!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "¡A cualquier costo!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "La sensación de estar bañado en luz solar... tan suave, que te hace llorar."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5244_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "Para expresar mi gratitud... construiré un altar oculto para ti en lo profundo de mi dolor."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5245_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "El Caro de hermano y mi Cuerpo se están fusionando más perfecta y estrechamente..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5246_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "Soy más resistente de lo que piensas. Así que, al usarme, puedes aplicar más fuerza. No te contengas."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5247_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "¿Es solo mi imaginación? El deseo de sangre parece haber disminuido un poco."
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5248_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "Incluso antes de que comenzáramos oficialmente, ya estaba esperando tu llegada. Parece que estamos trabajando bastante bien juntos, ¿eh? Socio."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "Eso es vergonzoso."
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5251_AwakerVoiceContent = {Text = "¡Aah!"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5252_AwakerVoiceContent = {Text = "¡Hahaha!"},
  Voice_5252_AwakerVoiceTitle = {
    Text = "Golpe·Manía"
  },
  Voice_5253_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5253_AwakerVoiceTitle = {
    Text = "Golpe·Depresión"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "¡Hurtame todo lo que quieras!"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "Aigis está realmente asustada. No, no de todos ustedes, sino de ella misma trayendo miedo y tristeza a ustedes de nuevo."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "¡Los cuentos de hadas de esta era son mucho más interesantes que los que leí en aquel entonces! ¡Ah, ah! ¡Mi señor, por favor no malentiendas! ¡Ya he pasado la edad de los cuentos de la noche!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "¡Hurtame todo lo que quieras!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "Uff... ¿Le dio problemas Aigis a todos?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "Siempre te has aferrado a esa divertida confianza y has permanecido a mi lado... Está bien, tal vez no sea una mala idea ponerte a trabajar. Pero recuerda esto: no puedo tolerar ninguna traición, especialmente de ti."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5259_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "Solo lamento no haber empalado sus cadáveres en estacas y colgarlos en las paredes. ¡No perdonaré a ninguno que me traicionó, pisoteó o insultó!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5260_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Sí, hice la venia ante esas personas; no se puede negar. Se aprovecharon de mi ignorancia, y les hice pagar por ello."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5261_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "¿Crees que unas pocas palabras melosas y unos días de falsa amabilidad me harán poner las cadenas de nuevo y convertirme en tu juguete?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5262_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "Todos los que intentaron controlarme o usarme terminaron en el inframundo a mis propias manos—no me importa enviarte allí también."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5263_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "Ah... ¡Lo siento, por favor no te muevas!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "¡No me toques!"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "¡Desacato!"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "Ríndete... Bienvenido al reino del placer y los sueños."
  },
  Voice_5267_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5268_AwakerVoiceContent = {
    Text = "Esta es la ciudad donde vagan innumerables almas perdidas, incapaces de encontrar el camino a casa."
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "¡Aigis hará su mejor esfuerzo!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Umm... no puedo controlar mi habilidad para absorber la fuerza vital, así que por favor, no pongas tu mano en la cuna, o te enfermarás."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "Espero que no falle durante nuestra conversación. Mi encantadora pero exasperante asistente, ya no hay más laboratorios sobrantes para que ella haga volar por los aires."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Erica"
  },
  Voice_5271_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"erica\""
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "¡Brazos, esos molestos brazos! Siempre se agarran de mi cabello. No puedo controlar mis propias manos—qué tipo tan inútil soy... Tal vez debería..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Charlas · Sobre Mí"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Gracias por tu orientación. Finalmente entiendo la elección de Desmayo. Daba todo por sentado, sin darme cuenta de la carga mental que le imponía. De ahora en adelante, intentaré vivir para mí mismo..."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5274_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "A través de los largos y interminables tiempos, Desmayo y yo solo tuvimos el uno al otro... Pero ahora, tengo nuevas personas importantes... Guardián, por favor permíteme retractar mis palabras anteriores. Eres diferente. No solo te importa mi voz cantando o mi vestido formal; realmente me ves. Por lo tanto, también te cuidaré."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5275_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "Las estrellas en el sueño, yendo hacia donde deberían, apuntan hacia el reino de Dios!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "¿Por qué siempre estoy vestido con este vestido? Para que pueda cantar para ti en cualquier momento."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5277_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "¿Qué quiero hacer? ......Lo siento, no entiendo lo que quieres decir......De hecho, Desmayo me ha hecho esta pregunta muchas veces, pero todo lo que quiero es que ella se recupere pronto......"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5278_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "Durante nuestro tiempo en el planeta desolado, la compasión de esas figuras influyentes proporcionó a mi hermana y a mí los recursos para sobrevivir. Al final, también me dieron la oportunidad de escapar del planeta, aunque estaba limitada a una persona. Todos son mis benefactores, al igual que tú, Guardián, que me diste un lugar para quedarme."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5279_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "Eres la persona amable que me proporciona un lugar para quedarme. Aigis te escuchará. Si tan solo Aigis pudiera ser un poco más útil..."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "No te olvides de preparar el lugar. El que reservaste no es más pequeño que el de Elworth, ¿verdad?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5281_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Bien, ¡Karen ahora está más motivada y puede limpiar veinte habitaciones al día!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5282_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "Esta es la música tan antigua como el agua del lago, que pertenece a \"nosotros\". ¡Maestro, bailemos juntos! Antes de que la voz de Karen sea tomada por \"Él\"..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5283_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "¡Maestro! La voz de Karen... desvaneciéndose... Ayuda..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5284_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "La vista de Karen ha mejorado... ¡Maestro, ¿olvidaste peinarte otra vez?!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5285_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Incluso si ella se hace más fuerte, Karen no quiere venganza en absoluto. ¡Karen solo quiere cantar! ¡Bailar! ¡Fiestar!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5286_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "Para sobrevivir después de la destrucción total, he compartido mi espíritu y sangre con demasiadas personas. Mi poder actual está lejos de lo que era cuando acepté esta voluntad por primera vez."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre el Pasado"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "No esperes encontrarme en el edificio de enseñanza. Está lleno del hedor de eruditos mohosos; no aguanto estar allí ni un solo día."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5289_AwakerVoiceContent = {Text = "No corras."},
  Voice_5289_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5290_AwakerVoiceContent = {
    Text = "Mi tierra natal adora a los \"Dioses\", y correspondientemente, el rey que sigo es naturalmente un \"comunicador divino\"."
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Reino Eterno"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "Tienes aquí una reunión de talentos, digna de un gran salón... Ten la certeza de que la invitación te será entregada por mi sirviente."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5292_AwakerVoiceContent = {Text = "¡Vamos!"},
  Voice_5292_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5293_AwakerVoiceContent = {
    Text = "Si tan solo hubiera más compañeros..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "No soy como ella. Ella solo ofrece escalofríos hostiles y miedo, mientras que yo te doy un dolor y amor íntimos, dulces y ardientes."
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Charla ligera·Sobre Wanda"
  },
  Voice_5294_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Wanda\""
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "¡No pienses que esto ha terminado! ¡Te haré pagar por cada onza de esta humillación!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Tus manos, como tu alma, están calientes. El fuego pálido... Aprecio tu toque."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "¿Cuál es el problema de jugar a las cartas en el aula? Hay una mesa, gente, y yo he traído las cartas. ¡Eso significa \"Juego en marcha\"!"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5299_AwakerVoiceContent = {Text = "No..."},
  Voice_5299_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "¡Mira en el Abismo!"
  },
  Voice_5300_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5301_AwakerVoiceContent = {
    Text = "¡Mira en el Abismo!"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5302_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5302_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5303_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5303_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5304_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5304_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5305_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5305_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "¡Báñate en luz divina!"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5307_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_5307_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "Las almas débiles se reúnen, pero ¿qué bien hace su ruido? Suspiro..."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "La guerra siempre trae dolor, y soportar el sufrimiento es el deber de un guerrero. Incluso si pierdo mis manos, mis pies y todo lo demás, seguiré luchando por ti y por la justicia del mundo."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "¿Es este el tributo que le ofreces a Él?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "¿Crees que esto puede cambiar el futuro?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "Su gestación... dentro de mi útero..."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "Heh, eres más inteligente de lo que pensé."
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "Rendir homenaje al maestro es solo natural."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "Te ves bastante lindo cuando intentas agradarme."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Brownie, pudín de caramelo, Sachertorte, mousse de chocolate, galletas... ¡Cada mesa debe tenerlos!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5318_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "¿Puedes revisar mi falda? Sin arrugas, sin holguras... ¿Qué pasa? ¿Estás insatisfecha?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5319_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "¡Bienvenido a mi última ceremonia de Iluminar! Todo esto fue meticulosamente diseñado por mí. Por supuesto, el Guardián contribuyó un poco..."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5320_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "Las mesas y sillas deben estar adornadas con encajes que coincidan con mi temperamento, y las plantas en macetas deben presentar plantas araña rojas... ¡Apúrate y prepárate!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5321_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Ve y haz la reserva para el invitado. ¿Cómo pudiste hacer mal una tarea tan simple?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5322_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "¡Sin escape!"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "¡Sin escape!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "¡Haré mi mejor esfuerzo! Para cumplir con las expectativas de mi señor."
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5325_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "Me gusta mucho esa mujer. Tenemos eso... eso... correcto, ¡un idioma común!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Charla ligera·Sobre Wanda"
  },
  Voice_5326_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Wanda\""
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "¡Eres un tonto insolente!"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "¡Eres un tonto insolente!"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "Convertido en escombros."
  },
  Voice_5329_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5330_AwakerVoiceContent = {Text = "Destrozar."},
  Voice_5330_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5331_AwakerVoiceContent = {
    Text = "¡Rompe las barreras de la realidad!"
  },
  Voice_5331_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5332_AwakerVoiceContent = {
    Text = "¿Planeas zarpar pronto? ¿Podrías concederme mi humilde solicitud y dejarme unirme a ti? Solo déjame llegar al mar..."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5332_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "Si aún confías en mí, por favor, permíteme ser la luz guía en este viaje. Sin embargo, incluso en una tarea tan simple, he fallado antes..."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5333_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "¿No sientes ganas de salir al mar? Déjame consultar el mapa actual... 47°9' S, 126°43' W, justo aquí."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5334_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "Causé muchos desastres en el pasado, incluso casi trayendo destrucción a ciertas civilizaciones... Si digo que no fue intencional, ¿ya es demasiado tarde?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5335_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "Soy el guardián de la entrada al Reino Eterno, guiando a aquellos que regresan a casa. Qué irónico que alguien con tal deber haya olvidado el camino a casa...\n¿Serás... mi faro?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5336_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Cúmulo estelar."
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5338_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "Niebla densa."
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5340_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5340_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5341_AwakerVoiceContent = {
    Text = "Para la mayoría de la gente, ser un guardaespaldas no hace ninguna diferencia, pero esa mujer es una excepción. Si es posible, por favor organiza otra ruta para mí."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Miryam"
  },
  Voice_5341_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Miriam\""
  },
  Voice_5342_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_5342_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5343_AwakerVoiceContent = {
    Text = "Ya no importa."
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "Quítate las manos de encima."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Antes de regresar al Palacio Aequor, te prestaré, a ti, un simple humano, parte del poder de Aequor, pero solo esta vez."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5346_AwakerVoiceContent = {Text = "¡Vamos!"},
  Voice_5346_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5347_AwakerVoiceContent = {
    Text = "¿Te gusta? A mí me gusta el dolor—la sensación de la piel inflamada y ardiente, los gemidos que combinan placer y sufrimiento. El dolor es el deseo más primitivo y genuino, ¿no es así?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "¡Únete a Aurita!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "¡Únete a Aurita!"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "Esa hermana mayor siempre me mira ferozmente. Pero por alguna razón, siento una extraña familiaridad. ¿Es porque me recuerda a mi madre?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Helot"
  },
  Voice_5350_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"helot\""
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "Mi mente se siente más aguda, no está mal."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5351_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "Prefiero el trabajo de laboratorio al deber de campo—¿pensaste que esas herramientas de asistencia fueron sacadas del mar?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5352_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "Ya sean tornillos o clavos, ¡cuantos más, mejor!"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "El cuerpo apenas puede manejar este Poder, pero no es el momento de cambiar de marionetas. ¿Por qué sigues ahí parado? Ayúdame a sostener esta pierna; necesito hacer algunos ajustes."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5354_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "El peso de la luz orientadora puede abrumar incluso a los más puros de los santos. Si te sientes cansado, mi llama pálida, asegúrate de confiar en mí. Haré todo lo que esté en mi poder para aliviar tu carga y compartir el peso de estas numerosas bendiciones."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Fatiga"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "Su aprobación es la razón de mi existencia como caballero."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5356_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Bañado en el destello de los dioses, ¿es este el poder divino de mi Señor? Tan vasto, tan sagrado"
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5357_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "La puerta a lo divino está al alcance."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5358_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Más brillante y más claro..."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5359_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "Para recuperar mi forma humana completa como Despertador... Ya he escuchado la melodía sagrada tocada para mí por el Reino Divino..."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5360_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "Me dará la bienvenida a la Iglesia, concediéndome un descanso pacífico..."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5361_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "No te preocupes, todos nosotros somos bastante útiles. Puedo coser y limpiar, otro yo destaca en la lucha, y los demás..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "Odio las cosas brillantes y suaves. La gentileza es como un espejo, revelando toda la fealdad, codicia y fragilidad."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "¿Quieres acariciar a Marrón? No puedo tomar esa decisión por ti. Necesitas preguntarle a ella misma."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "¿Quieres complacerme? Entonces arrodíllate, ofrece tu cuello y permanece en silencio hasta que termine de drenarte."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5366_AwakerVoiceContent = {Text = "¡Hah!"},
  Voice_5366_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5367_AwakerVoiceContent = {
    Text = "Tuve un sueño anoche; marcó el inicio de mi viaje a través de las estrellas."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5367_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "¿Puede Aigis ser de ayuda?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5368_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "Puedo sentirlo~"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5370_AwakerVoiceContent = {Text = "¡Toca!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Tres"
  },
  Voice_5371_AwakerVoiceContent = {Text = "¡Cuidado!"},
  Voice_5371_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5372_AwakerVoiceContent = {Text = "Retrocede."},
  Voice_5372_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "Nadie será herido... en este... mundo..."
  },
  Voice_5373_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5374_AwakerVoiceContent = {
    Text = "(coquetamente)"
  },
  Voice_5374_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5375_AwakerVoiceContent = {
    Text = "Por favor, permíteme colocar un altar para mi Señor. Es una estatua tallada por seguidores devotos y no traerá maldiciones sobre ti."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Solo un poco..."
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "¡Mi llave aún no está en posición!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Química, física, aplicaciones de Plata... En esta era, ¿ya no es necesario aprender las Siete Habilidades Caballerescas? Entiendo. En ese caso, por favor, organiza los cursos correspondientes para mí, ¡mi lord!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "¡Aurita ha viajado! ¡No llevada por las olas, sino que ha viajado con una caravana!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5379_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Medusas de faro, medusas corona, medusas flor de durazno; todas se mueven en grupos. ¡Por supuesto que Aurita también! ¡Aurita quiere estar con todos!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5380_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "¿Eventos pasados? Difícil de recordar... ¡Pero Aurita recuerda haber trabajado en un acuario! ¡El salario diario era de 2 Pensh!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5381_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Déjame contarte un secreto: ¡Aurita es en realidad un Aram, Trans... um, básicamente, Aurita es una persona del mar! Si Aurita se comporta, come verduras y hace amigos, ¡Atlanta la recibirá!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5382_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "El hogar de Aurita, los amigos del acuario, su medusa favorita... todos se han ido... ¿Tú también desaparecerás? ¿No puedes quedarte con Aurita para siempre?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5383_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "¿Ganamos? Eso es maravilloso..."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5387_AwakerVoiceContent = {Text = "Por paz."},
  Voice_5387_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "Por justicia."
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "¡Sé que estás dentro de mí!"
  },
  Voice_5389_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5390_AwakerVoiceContent = {
    Text = "Humanos, dioses falsos, Despertadores, e incluso Disolución... Todos servirán como la base para mi tierra eterna."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "¡Despertar, despertar! ¡Sé que estás dentro de mí!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "Uvhash... Me recuerda a mi hermano, trayendo de vuelta recuerdos de días oscuros, fríos y sin sueño."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Chat·Sobre Uvhash"
  },
  Voice_5392_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"uvhash\""
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Nuestra relación es como la de Sherlock Holmes y el Dr. Watson, ¿verdad? ¿Has estado al tanto de las últimas revistas populares?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Rinde homenaje a la belleza."
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "Rinde homenaje a la belleza."
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "Aversión, un verbo descriptivo, que significa desarrollar una aversión por algo. Desagrado, un verbo, se refiere a la sensación de aversión cuando algo es desagradable y se evita. Aversión, un sustantivo, la sensación de desagrado, <Del:El desagrado reprimido me hace destruir me hace destruir me hace> — Lo siento, pero me temo que no entiendo qué es \"desagrado\"."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "Al final..."
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "Convertirse en aún más distintivo."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Recuerda mi nombre, Goliat. Este nombre está destinado a pisotear la historia insignificante de la humanidad."
  },
  Voice_5399_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5400_AwakerVoiceContent = {
    Text = "Por favor, no tengas ninguna preocupación."
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "Espero que no defraudes tu potencial y las expectativas de la humanidad, nuevo Guardián."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "Sobrecarga."
  },
  Voice_5402_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5403_AwakerVoiceContent = {Text = "Sobrecarga"},
  Voice_5403_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "Hmm, la foto que encontraste en tu billetera? Ah, ese soy yo en el pasado. Mi apariencia actual fue moldeada por mi compañero de juegos y rival."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5404_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Perfecto—¿quieres apostar? Si ganas, te compartiré un secreto.\nPero ten cuidado, Alva podría atraparte~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5405_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "¿Te importa este pelaje? ¿Quieres tocarlo? ¡No te preocupes, soy muy generoso!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5406_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Por supuesto, hay beneficios. ¿No conocí a mi Watson? Comparado con esto, la vida y la apariencia no importan, ¿verdad?"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5407_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "¿Me arrepiento? En absoluto. La vida sería demasiado aburrida si todo siempre fuera sin problemas, ¿no?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5408_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "En mi tiempo, las escuelas eran lugares para entrenar guerreros. Parece que sigue siendo así ahora."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Mason... No, está bien. Al menos podemos estar juntos de nuevo, \"24\"."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Charlas Ociosas · Sobre \"24\""
  },
  Voice_5410_UnlockDesc = {
    Text = "Desbloquear después de obtener el Despertar \"24\""
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "¿No está mal, verdad? Ahora, la recompensa. — ¿Qué? ¡No existe eso de que haya almuerzo gratis!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "Soy de Cité. Allí, todos quieren ser actores; nadie se contenta solo con mirar. En realidad, somos meramente las pobres notas al pie de la ciudad."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre el Pasado"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "¿Has visto antiguas tallas en piedra? Fusionadas con las montañas, sobrevivieron al paso del tiempo a través de la naturaleza, ¡maravillosos relicarios... pero aún no son suficientes...!"
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "La paloma no ha regresado..."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5415_AwakerVoiceContent = {
    Text = "¡Retrocedan!"
  },
  Voice_5415_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5416_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5416_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5417_AwakerVoiceContent = {
    Text = "¡Ejecutar el comando!"
  },
  Voice_5417_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5418_AwakerVoiceContent = {Text = "Tonto"},
  Voice_5418_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5419_AwakerVoiceContent = {
    Text = "...¿Eh? ¿Me llamas? No escuché mientras arreglaba la motocicleta... Por cierto, amable extraño, ¿has visto mi llave inglesa?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5419_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "Mi memoria siempre es vaga, y solo puedo concentrarme en lo que está justo frente a mí. Sin embargo, haré mi mejor esfuerzo por grabar tu nombre en mi mente... ¿Cuál era de nuevo?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5420_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "Te ves algo familiar, pero no puedo recordar tu nombre... ¿Eres mi asistente? ¿Podrías traerme siete pernos?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5421_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "Grabé tu nombre en el Fantasma. Cuando un día salgamos de aventuras, no olvidaré cómo dirigirme a ti."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5422_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "Tan familiar, tan familiar. Algo debió haber sucedido entre nosotros, ¿verdad? Dame un momento para recordar... Ah, eres tú, el Guardián"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5423_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "Realmente eres un niño poco sincero. Afortunadamente, tengo suficiente tiempo y paciencia para esperarte..."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "\"Todos están felices,\" ¿verdad?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "Obtuve un trofeo decente... Aunque no se puede comparar con mi mejor colección, la emoción de cazar nuevas piezas siempre es emocionante. Invítame la próxima vez, también."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5427_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "Una criada profesional limpiará todo para su maestro, incluyendo a los villanos~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "Ahora somos cómplices, ¿verdad? Si alguna vez terminas en las calles, no te dejaré sobrevivir con basura."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Crece y florece, mi pequeño brote."
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "Crece y florece, mi pequeño brote."
  },
  Voice_5431_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5432_AwakerVoiceContent = {
    Text = "¡Se siente como si mi suerte con los dados hubiera mejorado un poco!"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "¡Vaya! ¡Tu suerte está ardiendo!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5434_AwakerVoiceContent = {
    Text = "¡Buena suerte!"
  },
  Voice_5434_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "No te acerques a mí."
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "No te acerques a mí."
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "Debo acusarte, Guardián. Tu amabilidad me incomoda—solo el dolor físico es verdaderamente eterno para mí."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "Muy bien, bien hecho."
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "Este nivel está lejos de ser suficiente."
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "Entonces, ¿qué recompensa deseas?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "¡Ugh! La suciedad y el desorden por todas partes... No puedo siquiera encontrar un lugar limpio para poner mis pies. Muy bien, ofréceme tu suave espalda, mortal."
  },
  Voice_5441_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5442_AwakerVoiceContent = {
    Text = "Finalmente... ¡lo encontré!"
  },
  Voice_5442_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5443_AwakerVoiceContent = {
    Text = "Incluso el pelaje de Marrón se ha vuelto más suave."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5443_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "Ser un guardia de seguridad puede ser un poco difícil, pero puedes dejarme todas las diligencias y entregas."
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5444_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "Mira cómo te enfrentas a Marrón.\n...Hehe, el Lord Marrón va a comer los dedos de un cobarde esta noche. Vamos a ver quién tendrá la mala suerte."
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5445_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "Me pregunto si puedo crecer un poco más."
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5446_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "¿Listo para trabajar? Está bien, Brown, ¡vamos a motivarnos!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5447_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "Agrippa? Lo siento, yo mismo he enviado a demasiadas personas. La mayoría de ellas son sin rostro y no valen la pena recordar."
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Agrippa"
  },
  Voice_5448_UnlockDesc = {
    Text = "Desbloquea después de obtener el despertador \"Agrippa\""
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "Miembros de la tripulación peligrosos... No, solo es desde un punto de vista de seguridad en navegación..."
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "Chat · Sobre Faros"
  },
  Voice_5449_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Faros\""
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "¡No te acerques más!"
  },
  Voice_5450_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5451_AwakerVoiceContent = {
    Text = "¡Ten cuidado!"
  },
  Voice_5451_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "He completado tus instrucciones... Ah, lo he arruinado de nuevo, ¿verdad?"
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "Ah, esto es exactamente la parte que necesitaba, ¡gracias! ...¿Eh? ¿Te pedí que lo encontraras? No recuerdo eso en absoluto. ¿Estás seguro de que no te confundes?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre las Partes"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "Inspiración, fluyendo sin fin"
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5455_AwakerVoiceContent = {
    Text = "Buen gusto."
  },
  Voice_5455_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "Elegiste el cuchillo de tallar perfecto para mí."
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "Odio perder el control. Sin embargo, tu presencia me ha mostrado que un toque de caos sutil puede traer un tipo único de disfrute."
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "¿Has crecido un poco?"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "Lo siento, me cuesta mucho hacer crecer mi cuerpo..."
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "Para comprender el mundo."
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "Para comprender el mundo."
  },
  Voice_54602_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54605_AwakerVoiceContent = {
    Text = "¡Aquí está tu comida!"
  },
  Voice_54605_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54606_AwakerVoiceContent = {
    Text = "¡Aquí está tu comida!"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "¡A continuación, analiza la esencia del mundo!"
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "¡A continuación, analiza la esencia del mundo!"
  },
  Voice_54608_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54609_AwakerVoiceContent = {
    Text = "¡Sacrificio! Regresa a mi maestro—"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "D-de-Gracias por la comida..."
  },
  Voice_5460_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_54610_AwakerVoiceContent = {
    Text = "¡Sacrificio! Regresa a mi maestro—"
  },
  Voice_54610_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54611_AwakerVoiceContent = {
    Text = "¡No me impidas!"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "En el abismo... habrá una luz de justicia."
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "¡No me impidas!"
  },
  Voice_54613_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54614_AwakerVoiceContent = {
    Text = "¡Deleitarse en este dolor único!"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "¡Deleitarse en este dolor único!"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "\"¡Sí, niño, has perecido en el río caudaloso!\""
  },
  Voice_54616_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54617_AwakerVoiceContent = {
    Text = "\"¡Sí, niño, has perecido en el río caudaloso!\""
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "¡Oh entidad sin forma, conviértete en un escudo de protección!"
  },
  Voice_54618_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54619_AwakerVoiceContent = {
    Text = "¡Oh entidad sin forma, conviértete en un escudo de protección!"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "Te agradecería por tu esfuerzo."
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5461_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "¡Bestia del Abismo, devora todo!"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "¡Bestia del Abismo, devora todo!"
  },
  Voice_54621_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "En el abismo... habrá una luz de justicia."
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "¡Soy quien rompe las cadenas—Tokuli—Li!"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "¡Soy quien rompe las cadenas—Tokuli—Li!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "¡Este cuerpo es el que revela el futuro!"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "¡Este cuerpo es el que revela el futuro!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "¡Haz una reverencia y besa las puntas de mis pies!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "¡Todas las conchas están aquí!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "¡Todas las conchas están aquí!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "El poder extraordinario solo puede ser soportado por un Aequor. Debes envidiarme, jaja. No es tu culpa por ser un humano débil; simplemente acéptalo."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5462_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "¡Haz una reverencia y besa las puntas de mis pies!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "¿Puedo convertir a estos individuos derrotados en mis esclavos?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Heh."},
  Voice_5464_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5465_AwakerVoiceContent = {
    Text = "Justo como se esperaba."
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5466_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_5466_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5467_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "Si hubiera sabido antes que esas personas estaban atormentadas por esta maldición que consume todo, yo... No, no es demasiado tarde ahora. Debo erradicarla y eliminar todo sufrimiento, incluso si me cuesta la vida una vez más."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "No pierdas el ánimo. El mar abraza a todos."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "Con un cuerpo tan frágil, es demasiada expectativa esperar que te conviertas en mi compañero. ¡Vamos, te llevaremos al club deportivo de la academia para ampliar tus horizontes y someterte a un entrenamiento riguroso!"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "Esa pobre alma que tomó mi poder ha sido atormentada por la Disolución... ¿Qué clase de mirada es esa? ¡Ni siquiera pienses en ello! ¡No te diré dónde está!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "Mientras tengas suficiente suerte, puedes volverte invencible."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "¿Será demasiado duro?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "Oh querido, la mayoría de las personas aquí todavía son niños. Ese caballero ya tiene el cabello blanco, y el joven de rostro severo le falta un brazo. Ninguno de ellos es una elección ideal... Esto es un gran dilema."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "¿Será demasiado duro?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "Runa dibujadas meticulosamente, estatuas devotamente talladas, pociones tabú refinadas repetidamente... ninguna puede ser despreciada."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5476_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "El trono debe construirse con piedra verde antigua de Aequor, y el altar debe ser untado con sangre sacrificial... ¿No deberías empezar a prepararte?"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5477_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Invoca a todos ellos; deberían temblar y arrodillarse en anticipación de Su llegada."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5478_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "Iré a las ruinas de Aequor, bañándome en las aguas donde Él nació..."
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5479_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Bienvenidos a su ceremonia de nacimiento, para presenciar Su llegada... ¿Qué? ¿Dices que Su desaparición también está destinada? ... No, eso es imposible... Ya he pagado un precio tan alto..."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5480_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "Sigue los mandamientos divinos."
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "¿Será tu lado el lugar donde Faint y yo pertenezcamos?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5482_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "Hmm, en ese momento, perdí mi voz. Tu gracia la trajo de vuelta."
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5483_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "Sigue los mandamientos divinos."
  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "El vasto cosmos, el profundo espacio ilimitado y el viaje sin fin una vez me dejaron sintiendo perdido..."
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5485_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "Los métodos abreviados pueden darte un impulso, pero no descuides el entrenamiento de tus habilidades."
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "Así que este método también se aplica a mí..."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "Una sensación maravillosa."
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "¿No traería su llegada un fin al sufrimiento causado por esta muerte negra?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "Buen día, mi lord. Si va a salir a realizar una investigación, por favor permítame acompañarlo como su guardián."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5493_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "¿Qué hacer? Si estás aburrido, solo ve a escribir este informe de misión."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "¿Está comenzando finalmente? Mis pequeñas mascotas han estado hambrientas durante tanto, tanto tiempo..."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "El poder de la línea de sangre está surgiendo."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "...Espera un momento, he visto esto antes. Me dieron agua con esta baba negra. ¿Podría estar relacionado con que obtuve el poder de la Llama Verde? Supongo que es una bendición disfrazada."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Ramona Dexter, solo llámame Ramona. Espero trabajar contigo, Guardián."
  },
  Voice_5498_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5499_AwakerVoiceContent = {Text = "Sí."},
  Voice_5499_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5500_AwakerVoiceContent = {
    Text = "Comando recibido."
  },
  Voice_5500_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5501_AwakerVoiceContent = {
    Text = "Hmph, irrespetuosos, déjenme divertirme con ustedes."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "¿Desagrados? Una tubería que se agota justo a tiempo, un carruaje fallido, lluvia al usar zapatos nuevos. Básicamente, toda la mala suerte es molesta."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "Llave, llave ajustable, llave de boca, destornillador plano, destornillador Phillips, tornillo de cabeza fresada, tornillo de cabeza plana... Si puede reparar cosas rotas, me gusta."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "Oh no~ Me atrapaste~\nEstá bien, los Despertadores tienen tal abundante poder espiritual. Necesito robar al menos 365 veces antes de que se conviertan en marionetas sin mente~ ¿No puedes hacerlo? Está bien, seré más cuidadoso la próxima vez. Solo un pequeño poco de \"miedo\" durante el aserrado, ¿de acuerdo?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5504_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Hey, ya conoces los secretos de la magia de Casiah, ¿verdad? Hmm, para asegurarme de que no hables, tendrás que seguirme a donde quiera que vaya en la gira~ Haha, ¿crees que estoy recolectando tus emociones? ¡De hecho, nada se te escapa!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5505_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "Tú, ¡sé el asistente mágico de Casiah! No tengas miedo~ Solo entra en mi caja mágica por un momento.\n\n¿Estás escondido bien? Estoy a punto de insertar la espada~ Oh, no hay trampas dentro~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5506_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Aquí, ¡ponte este sombrero de copa! Luego, cuéntame el regalo que más deseas. ¡Entendido, ya veo! Ahora, mete la mano en el sombrero—"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5507_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "Un poco preocupante. Esos niños vienen a cada espectáculo, y mi repertorio se está agotando... Hmm, un mago no puede realizar los mismos trucos para la misma audiencia. ¿Crear nueva magia? Lo siento, me falta ese talento; solo soy bueno en imitaciones."
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5508_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "Esta academia está en un estado de deterioro; solo el salón del director es algo presentable. ¿Qué piensas?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5509_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "Esos arrogantes y despreciables tontos todos se convertirán en espíritus vengativos bajo mi mando."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "La hoja de la venganza se vuelve cada vez más afilada."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "Mi salón no es tan inocente como un baile. ¿Estás listo?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5512_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "Mi salón es la tierra, el jardín, donde la belleza y el poder embriagadores florecerán..."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5513_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "Cojines de seda, té negro, macarons... También necesito rosas frescas con rocío de la mañana para adornar mi sala de recepción."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5514_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "¿No podemos hacer una excepción y permitir que los invitados afuera entren a la academia?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5515_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Error de tiempo de ejecución, error, error, error..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "¡Ah! ¿Qué hora es?! Lo siento, maestro... ¡Karen no debería estar holgazaneando! Pero estoy tan agotada..."
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "¿Es mi única opción esperar la muerte? ¿Puede alguien ayudarme? ¿Puedo resistir su control? Solía preguntarme estas cosas todos los días, pero la respuesta siempre estaba en mi mente—simplemente no me atrevía a enfrentarla... Si no hubieras aparecido, no sé si habría tenido el valor para luchar de regreso.\nTh-Gracias—no me malinterpretes, ¡esto no es una confesión ni nada!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5518_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Vivo en sus falsos sueños, despojado de mi derecho a ser una persona ordinaria por una profecía ridícula, sin siquiera la libertad de elegir... Haré cualquier cosa para escapar de esta vida."
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5519_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "\"Las nenúfares de bajo vuelo suspiran a su alrededor,\nElla se agita de vez en cuando entre los álamos dormidos;\nUn pájaro se mueve, temblando en su nido,\nUna canción misteriosa desciende de las estrellas doradas.\"\nAh, ¿lo oíste? Lo siento, es uno de mis favoritos... ¿Te gustaría leerlo conmigo?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre la Lectura"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "¡No irrumpas en la habitación de una dama a tu voluntad, ni hagas comentarios sobre su comportamiento! Ve ahora, necesito descansar."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5521_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "Más te vale no ponerte arrogante conmigo. Conoce tu lugar y abre los ojos para ver quién es el verdadero maestro."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5522_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Oh, ¿necesitas mostrar los artículos?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "¡Bien hecho. Es hora de celebrar la victoria con un barril de ron!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "Desaparecer."
  },
  Voice_5525_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5526_AwakerVoiceContent = {
    Text = "¡Déjamelo a mí!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "La sensación de ser aplastado bajo mis pies debe ser absolutamente maravillosa ~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5528_AwakerVoiceContent = {Text = "¡Aguanta!"},
  Voice_5528_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "¿Curioso sobre qué hay debajo del parche ocular? Te lo mostraré en un ambiente más apropiado, así que no seas demasiado impaciente."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "¿Ya se ha acabado? ... Mi emoción apenas comenzaba a crecer."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Hola, deja de jugar conmigo. Los verdaderos guerreros nunca dependen de ayudas externas."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5531_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "Aigis se ha vuelto más fuerte... ¡Usaré estos ojos para paralizar al enemigo!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "La Universidad Mythag no es diferente de los militares. Cada uno de nosotros está en la primera línea, puliendo nuestras armas y preparándonos para la batalla."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5534_AwakerVoiceContent = {
    Text = "¡Perfecto!"
  },
  Voice_5534_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5535_AwakerVoiceContent = {
    Text = "¡Perfecto!"
  },
  Voice_5535_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "Puedo ser encadenado, arrastrado por el cabello y arrodillado ante ti, ser tu esclavo. Todo eso está bien—siempre y cuando me dejes matar, escultores, portadores de lámparas, ancianas asmáticas... cualquier persona, te prometo que les desgarraré la garganta y beberé su sangre"
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5536_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "De las heridas de disolución fluye no solo un limo negro, sino también una inspiración infinita. Honestamente, no me importaría un poco más"
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "¿Asustado? ¡Jajaja, eso es correcto! Al diablo con todo. Solo quiero saborear tu miedo."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5538_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Interesante, tu sangre sabe... dulce, como hidromiel."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5539_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "En aquel entonces, decenas de miles aclamaban mi nombre. El mar llamado \"Uvhash\" ahogaba todo, celebrando mi ruptura del cuello de un calvo débil. Se sentía increíble. Como mi camarada, debes entenderlo."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5540_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "¡Espera, espera!"
  },
  Voice_5541_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5542_AwakerVoiceContent = {Text = "¡No!"},
  Voice_5542_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5543_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_5543_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5544_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5544_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "Buscando \"Disolución\" en el amplio Archivo... ¿No necesario? ¿Deseas saber mi postura sobre la Disolución? Entendido. Buscando \"armas de Disolución\" en el dominio privado del Despertar... Resultado: \"0\"."
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "Objetos falsos, frágiles como el polvo, pueden ser llevados por una simple brisa..."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Murphy"
  },
  Voice_5546_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Murphy\""
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "Un poco ruidoso, ¿son estudiantes?\nMe recuerdan a los albatros. ¿Conoces esos pájaros? Energía interminable, viajes que parecen nunca terminar..."
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5548_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5549_AwakerVoiceContent = {Text = "Hmph"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "Ramona es la única interesante aquí, talentosa en esgrima. El resto son todos rígidos... ¿Eres uno de ellos? ¿Realmente te parece divertido escribir informes de misión?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "No vale la pena mencionar."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = [[
Las madres no son todas iguales. Algunas son buenas, y algunas son malas.
La Maestra es una buena madre.]]
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5552_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "Lamento no haber podido protegerte..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "¿Has reservado el lugar? ¡Necesita ser un jardín de más de 150 metros cuadrados!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5554_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "La sangre de los moribundos es un líquido resbaladizo. Con solo un ligero corte en el cuello, la sangre fluye entre los dientes, convirtiéndose en ríos cálidos que llenan lentamente mi vientre... Heh, delicioso."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre la Sangre"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Ah"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_5557_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_5558_AwakerVoiceContent = {Text = "Eh"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Gracias por tu amabilidad al brindarme refugio. Espero no traer un destino trágico sobre ti..."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "Vengo de un lejano planeta alienígena, un lugar de tormentas de nieve implacables y frío extremo. Pero está bien; en mi mansión, más de mil sirvientes ofrecen un cálido consuelo a través de su cercanía."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre el Pasado"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "No puedo caer aquí antes de tu regreso."
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "No puedo caer aquí antes de tu regreso."
  },
  Voice_5562_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5563_AwakerVoiceContent = {
    Text = "Oh, ¿cómo puede haber un invitado tan arrogante en el mundo, queriendo \"la arma más poderosa del mundo\"? Le dije que se necesitaría una cabeza empapada en odio para intercambiarla, y se marchó sombrío..."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Chat · Sobre Goliat"
  },
  Voice_5563_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"goliat\""
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "Tu mirada segura, como si siempre estuvieras listo para \"salvar el mundo\", me hace picar las articulaciones solo al mirarla."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5564_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "Justo antes de que se impusiera la prohibición de investigación, estaba a punto de permitir que la aniquilación engullera este llamado santuario de Disolución... Qué pena."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5565_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Sí, tengo innumerables cuerpos y escapatorias de la disolución. Pero perseguí la verdad, y no me arrepiento de ello"
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5566_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "La verdad del mundo, su comienzo y su final—todo sin sentido. Si deseas caminar por el camino hacia la verdad, no me importa ser tu guía... como antes."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5567_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "Puedes detenerme, pero el final es inevitable... Sal varé esta escuela—y a ti—para el final. Juntos, nos bañaremos en el crepúsculo del tiempo en la cima de la torre, presenciando la caída de la civilización... ¿Qué piensas? De este modo, nuestro vínculo no habrá sido en vano, ¿verdad?"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5568_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5569_AwakerVoiceContent = {
    Text = "Está bien."
  },
  Voice_5569_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5570_AwakerVoiceContent = {
    Text = "Desaparecer."
  },
  Voice_5570_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5571_AwakerVoiceContent = {
    Text = "Que mis oraciones sean la campana matutina que despierte la patria..."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "Nunca pensé que alguien además de Tintura me aceptaría. Me alegra haberte conocido, Guardián. Haré mi mejor esfuerzo para aprender a controlar mi poder, para que cuando te abrace, no agote tu fuerza vital... ¿Un abrazo, verdad? ¿La forma humana de expresar gratitud?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5572_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "Si me quedo aquí, ¿no necesito pagar nada? Puedo ayudarte a ganar estatus aquí. Simplemente amenaza con drenar sus vidas—es simple, como lo que hice por Tintura... ¡Ah! No le digas a nadie sobre esto"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5573_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Lo siento, no soy como los demás... tengo defectos."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5574_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "Una criada hábil puede mejorar en gran medida el salón, pero una criada azul-verde... déjame reconsiderar..."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Chat·Sobre Karen"
  },
  Voice_5575_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"karen\""
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "La Tintura es mi hermana gemela. A diferencia de mí, ella siempre brilla intensamente...\nSin mi carga, ella tendría un futuro más brillante, su canto resonando por toda la galaxia..."
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5576_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "La cuna es estrecha, sin espacio para estirar mi cuerpo... Pero Tinct dijo que, por la seguridad de todos, debería permanecer en la cuna... Dado que este es su deseo, cumpliré."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5577_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "A menudo siento como si existiera en el intervalo entre la vida y la muerte. Dondequiera que esté, la melancolía se extiende como una marea, y las tragedias se desenvuelven una tras otra. Aun así, ¿todavía querrías que escriba un poema para ti? Hmm... tal vez merezcas el más dulce..."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5578_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "\"Las rosas aún no han florecido, pero el amanecer se acerca.\""
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5579_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "¿Qué anhelas? ¿Es la belleza de las palabras elegantes, la fama extendida o la sincera sinceridad detrás de esas palabras?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5580_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "Con tinta invisible, dibuja los capullos deformados... Esta rama de rosa fantasmal y etérea puede realmente inspirar inspiración poética..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5581_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Escucha a mi Señor."
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "Despertar · II"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "¡Sacrificio! Remodela el Reino de Dios—"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "Despertar III"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "Si insistes, daré un paso hacia la luz del sol... la misma luz del día en que dejé Cité..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5582_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "Hehe, ¿quieres ver un universo en destrucción? Eh, ¡ya es demasiado tarde para dar marcha atrás ahora!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5583_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Bebe, el dulce sabor de la muerte."
  },
  Voice_5584_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5585_AwakerVoiceContent = {
    Text = "Bebe, el dulce sabor de la muerte."
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "¡Eso es suficiente!"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5587_AwakerVoiceContent = {Text = "No..."},
  Voice_5587_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "¡Mira la majestad de Yu!"
  },
  Voice_5588_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5589_AwakerVoiceContent = {
    Text = "El aire en el campus a las 4 AM es refrescante. Me alegra que estés dispuesto a entrenar conmigo. Debo decir que esculpir es un gran ejercicio."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Charla ligera·Sobre la mañana"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "Este poder se siente bastante bien al usarlo."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5590_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "Odio a las personas que no pagan por lo que compran. Si manejas una tienda el tiempo suficiente, encontrarás este tipo de problemas. No tengo más remedio que manejarlo yo mismo y recuperar la factura~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Tortura lentamente."
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "Tortura lentamente."
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5594_AwakerVoiceContent = {Text = "Cargar."},
  Voice_5594_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5595_AwakerVoiceContent = {Text = "Iniciar."},
  Voice_5595_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "¡Que este lugar se convierta en un mar de emoción para todos!"
  },
  Voice_5596_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5597_AwakerVoiceContent = {
    Text = "¿Qué? ¿Esperas que te agradezca?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "Como tributo, esto está lejos de ser suficiente... pero a la luz de tu sinceridad, lo aceptaré a regañadientes."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "¿Realmente pensaste que esto me haría escucharte?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5600_AwakerVoiceContent = {Text = "¡Hah!"},
  Voice_5600_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5601_AwakerVoiceContent = {Text = "¡Ve!"},
  Voice_5601_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5602_AwakerVoiceContent = {
    Text = "¿Monstruos ingratos, asesinos y matadores—tienen algún valor que tú reconozcas? Monstruo."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5602_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "No importa cuántos cojines apiles, un trono de lapislázuli no puede compararse con una cama de plumas. En este aspecto, hay algo encomiable en tu lugar."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "Un castigo menor."
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "Odio la soledad, odio preocuparme por los sentimientos de alguien en una oscuridad infinita... Así que, por favor, no me abandones, ¿de acuerdo?"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "Si yo fuera tú, ¡encerraría a todos los Despertadores en jaulas! Una vez que los perros locos se sueltan, siempre muerden a sus amos primero."
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5606_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "Llegué una hora tarde a esta reunión—¡culpen a esos bienintencionados que abolieron la esclavitud! ¡Ahora no hay nadie que me peine!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5607_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "Increíble, mi hogar ha perecido así... ¡Esa era la gran Roma! ¡Debes haber oído hablar de ella!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5608_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Vamos, ¡empecemos con una victoria!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "Esta es la bendición de mi señor."
  },
  Voice_5610_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5611_AwakerVoiceContent = {
    Text = "Guarda tu compasión para ti. No me gusta, y no necesito la simpatía de nadie. Si sigues mirándome así, podría no resistir la tentación de atormentarte... ¿No quieres que las cosas se salgan de control, verdad? Así que sé un buen chico/chica, escucha, y conviértete obedientemente en mi gladiador."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5611_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "¡No *silencies* volver a preguntar! Fui descuidado, dejé escapar al gladiador y ¡maté a toda mi familia! ¡Al igual que el Imperio Romano ahora, reducido a cenizas!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5612_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "Comparado con otros, Nymphaea es solo una persona ordinaria sin logros ni valor.\nLo que me despertó... podrían ser algunos pequeños y humildes deseos."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Hoy, rompí las reglas de la escuela nuevamente al llegar cinco minutos tarde a clase... Por lo tanto, solicito sinceramente el castigo más severo, preferiblemente llevado a cabo por el guardián."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "Las herramientas también necesitan mantenimiento. Un buen juego de herramientas es el alma de un mecánico."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5615_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(Resistencia despectiva)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "Si vuelve a suceder, solicitaré un periodo de prueba disciplinaria para ti."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "Además de pelear, tengo otros trabajos que hacer. Incluso en la Eón Arqueo, no estuve ocioso... Oye, ¿de verdad crees que soy solo un bruto que solo sabe pelear, verdad?"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Charla ligera: Sobre el trabajo"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "Cuando las personas se acercan a mí, siempre recuerdan sus recuerdos más tristes y no pueden evitar derramar lágrimas. ¿Puede alguien como yo seguir creciendo?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5619_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5621_AwakerVoiceContent = {
    Text = "¿Es esto correcto?"
  },
  Voice_5621_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "¡Este lugar es mucho mejor que la asquerosa y maloliente Prisión Nueva Puerta! Ya sea descansando en el sofá o apretujado en un rincón, todo es bastante cómodo, ¿no?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5623_AwakerVoiceContent = {
    Text = "¡Brown...!"
  },
  Voice_5623_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5624_AwakerVoiceContent = {
    Text = "Concha, ¿dónde ha ido"
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5625_AwakerVoiceContent = {Text = "¡Astuto!"},
  Voice_5625_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "¿A dónde se ha ido la concha espiral?!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "La Vía Láctea fluyendo..."
  },
  Voice_5627_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5628_AwakerVoiceContent = {
    Text = "Aurita no le gusta que los amigos se vayan de repente... ¡Pero, si regresan, Aurita los perdonará!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "Una mujer que navega sola por el mar es ya sea una diosa o una loca. Confundir a Miryam con una diosa fue un grave error."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Miryam"
  },
  Voice_5629_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Miriam\""
  },
  Voice_5630_AwakerVoiceContent = {
    Text = "...¡Está bien!"
  },
  Voice_5630_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "Observé en secreto la magia de la señorita Casiah. Su actuación trajo alegría al público, pero yo siempre traigo tristeza... ¿Crees que las lágrimas y las sonrisas son igualmente preciosas? Quizás..."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Chat · Sobre Casiah"
  },
  Voice_56313_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"casiah\""
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "La poesía, las llamas y el dolor son similares; te envuelven sin previo aviso... Cuando recuperas tus sentidos, ya estás sumergido en el mundo de la poesía..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Deja que los poemas del pasado despierten el jardín oculto en tu corazón."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "La poesía y las flores son probablemente lo mismo, ¿no? Ambas son efímeras, pero eternas. En este mundo sin límites, capturan los momentos más inolvidables en un pequeño espacio... Creo que todos han guardado silencio por un poema, al igual que se detienen a admirar la flor en plena floración."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre la Poesía"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "Casi lo olvido... ¿Qué tipo de flores florecen en Cité esta temporada?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre Cité"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "Tu presencia ha reavivado la tinta en mi pluma, permitiendo que fluya una vez más como un suave arroyo. Seguiré escribiendo poesía para tu historia."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Guardián 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "La belleza de las flores en flor es igualada por la tristeza de su marchitar. No importa cuántas veces sienta tristeza, no puedo evitar detenerme y llorar por ellas. Si las ignorara por miedo al dolor, qué triste estarían estas flores..."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Sufrimiento"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "Para investigar la estructura interna de este cuerpo mientras Erica está \"durmiendo\", Winkle pidió que descansara en su oficina por la noche.\n¿Debería mencionar que Erica retiene una parte de su conciencia mientras duerme?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Bígaro"
  },
  Voice_5631_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"bígaro\""
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "La Dama Roja es verdaderamente hermosa. Su fuerza y confianza, su sonrisa graciosa ante el destino, y su fuerza vital vibrante pero resolutiva, todo me hace envidiar"
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Charla ligera·Sobre Sorel"
  },
  Voice_56320_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Sorel\""
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "Escribí un nuevo poema ayer, pero no lo he mostrado a nadie. No es muy bueno, pero... Guardián, ¿estarías dispuesto a echarle un vistazo?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Guardián 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "El Club de Poesía Estudiantil quiere que sea su asesor... No puedo aceptar. No quiero desanimarlos, pero solo les traería decepción y desánimo."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "No hay nada que odiar en este mundo. Los años dorados merecen alabanzas, mientras que el declive de la vejez merece lástima; la magnificencia de la juventud es envidiable, mientras que los restos desgastados evocan la reflexión."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Cada vez que veo a la Señorita Nymphaea, pienso en esa pintura de nenúfares. Ella lleva la amarga tranquilidad y fragancia de los nenúfares... Me pregunto cómo será su mundo"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre Nymphaea"
  },
  Voice_56324_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"nymphaea\""
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "Siempre he sentido la presencia de \"fantasmas\" a mi alrededor, como una posesión o embrujamiento inexplicable, drenando mi esperanza por el mundo. Pero si es un fantasma, ¿cómo explicas que la leche y el agua desaparezcan en el aire...?"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Fantasmas"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "Mi cuerpo no fue afectado por la Disolución; esos líquidos negros son solo tinta. Pero, sinceramente, incluso sin la Disolución, todo eventualmente se convierte en Ilusión, ¿no es así?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "En la lápida de la Tumba de la Llave, vi el nombre del Guardián... Los recuerdos de la vida eran dolorosos, pero nunca tuve la intención de olvidarlos. Para el Guardián, esos recuerdos perdidos deben ser igualmente valiosos, ¿verdad?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre la Memoria"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "Si la poesía existe para alabar la belleza, entonces su existencia es como la poesía misma. Cuando comienza a cantar, de repente entiendo lo que los ancianos describían como la voz de una ruiseñor..."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Chit-chat·Sobre Tinctura"
  },
  Voice_56328_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"tintura\""
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "La hermosa bailarina... Sus llamas verde esmeralda son irresistibles, incluso si queman a uno hasta las cenizas..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Charla ligera: Sobre Liz"
  },
  Voice_56329_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Liz\""
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "¿Reemplazar la absorción de la esencia primal de esta manera?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "Delicioso, absolutamente delicioso."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "Invitado, ¿qué tipo de recompensa te gustaría?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Apresúrate y termina. No te quedes en las calles."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Sacrificio Inevitable"
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(Grito de miedo)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "Entrada actual completada. Emitiendo corriente."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "¡No subestimes al mejor ladrón de la calle!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "¡Aquí viene el tributo de apertura!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "¡La Milésima Ilusión aparece aquí!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "Acercándose..."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5638_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "¡Hundirse y arder! ¡Danza de la destrucción!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "Esta es la ciudad donde vagan innumerables almas perdidas, incapaces de encontrar el camino a casa."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "Déjame darte mi energía de transferencia restante...!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "¡No subestimes al mejor ladrón de la calle!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "¿Es un enemigo? Por favor, dame la orden de ataque.\nLa baba negra es un enemigo... ¿Es Lily también un enemigo?"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Erica el Autómata, Torso No. EA307881, Motor No. MF311028. Encantada de estar a tu servicio."
  },
  Voice_5640_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5641_AwakerVoiceContent = {
    Text = "¡Lucha con todas tus fuerzas hasta que el enemigo sea completamente derrotado!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Hola, soy... ¿Puedes decirme mi nombre?"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5643_AwakerVoiceContent = {
    Text = "Después de llegar a la escuela, llegué a entender la enfermedad llamada Disolución que me había infectado. Mis padres siempre me mantenían alejado del océano cuando estaba vivo, y ahora parece que esta infección podría estar efectivamente conectada a mi proximidad con el mar..."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "Está bien, no te \"decepcionaré\""
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Este aliento abrasador—"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5646_AwakerVoiceContent = {Text = "Ve."},
  Voice_5646_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5647_AwakerVoiceContent = {Text = "Gira."},
  Voice_5647_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5648_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_5648_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5650_AwakerVoiceContent = {
    Text = "El día finalmente ha llegado..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5651_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_5651_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5652_AwakerVoiceContent = {
    Text = "No he terminado todavía... ¿Qué tal si te levantas para que pueda matarte otra vez?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "Guardián, debo hablar contigo. Antes de alcanzar la victoria final, algunas personas no deberían ser tan extravagantes. Recuerda, no estoy luchando por las vidas lujosas de tales personas."
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Charla ligera·Sobre Sorel"
  },
  Voice_5654_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Sorel\""
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "Si soy llevado como prisionero de guerra, ¿qué cruel destino me espera?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "¡Mira esto!"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5657_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5657_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "Uf—tan soñoliento. Antes de descansar, ¿has preparado algún refrigerio para relajarnos?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Madre, ¿te gustaría tocarlos? Se dice que son muy suaves."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5659_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Hmm hmm hmm, la la la~ Limpiando, limpiando, me encanta limpiar, me siento genial~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Charla ligera: Sobre el trabajo"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(Gemido ahogado)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "Hmm... No está mal."
  },
  Voice_5662_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5663_AwakerVoiceContent = {
    Text = "(Gemido ahogado)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(Gemido ahogado)"
  },
  Voice_5664_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5665_AwakerVoiceContent = {
    Text = "¡Ira Ardiente!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "He visto a muchos volverse locos por la Disolución. Honestamente, ya estoy lo suficientemente loco. La Disolución no me afectará."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "Heh~ ¡Hahaha!"
  },
  Voice_5667_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5668_AwakerVoiceContent = {
    Text = "¡Las buenas herramientas son la mitad del éxito!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "Se siente como volver a la vida."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "No está nada mal."
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Ahora puedo balancearme con mayor potencia."
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "Equilibrando la asistencia, manteniendo el progreso de la investigación y completando las tareas docentes. Parece que el experimento de compresión temporal inversa necesita ser priorizado."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5672_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "Un paso más cerca de la aventura oficial."
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "¡No dejes que nadie se acerque al agua, o la llama de tu amor podría extinguirse!"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "¡Luchar hasta el Final!"
  },
  Voice_5675_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5676_AwakerVoiceContent = {
    Text = "Realmente tienes un valor notable. Mira estos tentáculos: ¿no tienes miedo de ser consumido por la locura?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5676_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5677_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_5677_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5678_AwakerVoiceContent = {Text = "¡Ay..."},
  Voice_5678_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5679_AwakerVoiceContent = {
    Text = "¡Por favor, detente!"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "¿Te gustaría tocarlo? Mi corazón late por tu presencia."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5680_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "Están chirriando felizmente. Gracias, Maestro."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5681_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "Algo está despertando en mi pecho... cálido y suave. Lily, las lágrimas de Lily son casi...\nMadre, celebremos juntos."
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5682_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "Estar con mi madre me llena de una sensación de felicidad."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5683_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "Estoy lleno... Mi estómago está lleno.\n¿Se volverá Lily más fuerte después del ritual?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5684_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "Amo el mar. ¿Es irónico? Porque todo lo que poseía ahora está hundido en Aequor..."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "¡Ten cuidado!"
  },
  Voice_5686_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "Cosas que odio...? Ninguna. ¿Odiarías un grano de polvo o una hoja?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "He rechazado varias veces las invitaciones al banquete de la sirvienta. Ella parecía un poco desanimada... ¡Pero comparado con divertirse, la seguridad del maestro es mucho más importante!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Chat·Sobre Karen"
  },
  Voice_5688_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"karen\""
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "¡El señor es la razón de la existencia de un caballero, así que siéntete libre de darme órdenes!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...Podríamos necesitar una llave de torsión para esto... Hmm, lo siento, ¿me llamaste?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5692_AwakerVoiceContent = {
    Text = "¡¿Cómo te atreves?!"
  },
  Voice_5692_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5693_AwakerVoiceContent = {
    Text = "(Zumbido Elegante)"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(Grito de miedo)"
  },
  Voice_5694_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5695_AwakerVoiceContent = {
    Text = "Eso es suficiente."
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5696_AwakerVoiceContent = {
    Text = "Sé gentil."
  },
  Voice_5696_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "Seguramente, sigue siendo difícil concentrar el espíritu..."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "Ella suele quedarse cerca de mí por las noches. ¿Será simplemente porque mi cabeza es demasiado llamativa?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Bígaro"
  },
  Voice_5698_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"bígaro\""
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "Siempre he esperado la llegada de la destrucción, sin considerar \"la resistencia\"... ¿Me ayudarás a cruzar el abismo con mi alma superficial? Incluso en un mundo donde sobreviví por poco, aún me otorgas la salvación..."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5699_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Desde que he Despertado como tu apóstol, no busco más que tu paz y alegría, ese es mi deseo... Ugh... Ah... De hecho, supervivencia, supervivencia, supervivencia, sigue viviendo"
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5700_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "¿Por qué no perderte en mi amor? ¿No me despertaste por la calidez de mi abrazo?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5701_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "¿No deseas evitar la complicación con mujeres de origen desconocido? Muy bien, muy bien. El rey depuesto de Nínive, la gente de Shinar que aspira a alcanzar los cielos, la chica cuya voluntad fue tomada bajo el árbol sagrado del Éufrates... ¿De dónde te gustaría comenzar?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5702_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "¿Por qué siempre me evitas? ¿Eres tímido? Qué lindo, esta renuencia a enfrentar tus deseos"
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5703_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "Este lugar es terrible, absolutamente terrible! ¡Cómo se atreven a hacerme compartir una mesa para el té de la tarde! ...Sin embargo, las galletas caseras son bastante buenas. Envíen algunas a mi dormitorio después de la cena."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5705_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_5705_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5706_AwakerVoiceContent = {
    Text = "¡Mira esto!"
  },
  Voice_5706_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5707_AwakerVoiceContent = {
    Text = "Disolución... Hay registros en la academia de mi hogar, pero ¡Karen odia leer y ha olvidado todo!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "¿Deseas que navegue una vez más? Si puedes pasar por alto mis fracasos pasados, haré un intento."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5708_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "¿Disgustos? Muchos—jefes que hacen que los trabajadores se queden tarde, monjas autojustas, estómagos que rugen, pan negro con fragmentos de vidrio..."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "Todo es culpa de Aigis... Todo es mi culpa..."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "¡Terminemos esto!"
  },
  Voice_5711_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5712_AwakerVoiceContent = {
    Text = "Gracias a la amabilidad de la Señorita Hannah, asistí al ensayo del coro. Los himnos son bastante diferentes de las canciones de marineros. Durante mi tiempo protegiendo el barco, nunca había escuchado melodías tan distintivas..."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "¡¿Qué tal este movimiento?!"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "¡¿Qué tal este movimiento?!"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "¡Tan aterrador~!"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5716_AwakerVoiceContent = {Text = "Uu"},
  Voice_5716_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "Hola, ¡mi nuevo amo! El menú de hoy incluye pudding de babosa, estofado de sapo y vino de llama verde. Siéntete libre de elegir."
  },
  Voice_5717_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5718_AwakerVoiceContent = {
    Text = "¿Es esa la forma de regresar al Génesis...? No, es un poco diferente a lo que imaginaba. Pero si pudiera convertirme en eso, sería genial."
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "Chatear · Sobre la Línea de Sangre Aequor"
  },
  Voice_5718_UnlockDesc = {
    Text = "Desbloquear después de obtener cualquiera de los Despertar: \"Tulu\", \"Murphy\", \"Miryam\" o \"Goliat\"."
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "Esperando el momento adecuado."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5720_AwakerVoiceContent = {
    Text = "¡Mira esto!"
  },
  Voice_5720_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "Corderos, la misericordia de Dios los redimirá."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "Corderos, la misericordia de Dios los redimirá."
  },
  Voice_5722_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5723_AwakerVoiceContent = {Text = "¡Muere!"},
  Voice_5723_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5724_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_5724_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5725_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5725_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5726_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_5726_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5727_AwakerVoiceContent = {
    Text = "Ella también es un alma lamentable, destinada a ser devastada por el destino. Porque cuando Él realmente descienda, será el momento en que le entregue la muerte a ella."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Miryam"
  },
  Voice_5727_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Miriam\""
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "¡Sé manchado con sangre!"
  },
  Voice_5728_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5729_AwakerVoiceContent = {
    Text = "¡Venganza...!"
  },
  Voice_5729_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5730_AwakerVoiceContent = {Text = "Duele..."},
  Voice_5730_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5731_AwakerVoiceContent = {
    Text = "(Gemido reprimido de dolor)"
  },
  Voice_5731_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5732_AwakerVoiceContent = {
    Text = "(Gemido reprimido de dolor)"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5733_AwakerVoiceContent = {Text = "¡Ay..."},
  Voice_5733_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "¿Te gustaría hundirte conmigo?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5735_AwakerVoiceContent = {Text = "¡Vete!"},
  Voice_5735_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5736_AwakerVoiceContent = {
    Text = "Cosas que odio... un escritorio desorganizado, un armario desordenado, alféizares polvorientos — sí, estoy describiendo tu habitación. Para las 7 AM de mañana, quiero que esté restaurada a como estaba antes de que te mudaras."
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(Zumbando con interés)"
  },
  Voice_5737_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5738_AwakerVoiceContent = {
    Text = "¡Interesante!"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "(Se burla despectivamente)"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "Si es necesario, puedo dejar la cuna..."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "¿Lo quieres?"
  },
  Voice_5741_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5742_AwakerVoiceContent = {Text = "¡Cuidado!"},
  Voice_5742_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5743_AwakerVoiceContent = {
    Text = "¡Doble, doble, doble!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "Esto me recuerda al primer par de zapatos de baile rojos que recibí cuando tenía ocho años. Realmente los amo. Gracias, Guardián."
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5744_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "Amigo... ¿Maestro? ¿O Madre?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "Mi protección también puede fallar a veces..."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5747_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5747_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5748_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5748_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5749_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5749_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "¿Gustos? Alguien una vez me lo preguntó en los campos de batalla de Peloponeso... Es demasiado tarde. Desde hace tiempo he abandonado tales preferencias personales."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "Shh... por favor no dejes que \"ellos\" descubran que me estoy volviendo más fuerte."
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "\"Ellos\" dijeron... Muy agradecido."
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "Uh... ¿Qué es esto?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "Esto solo me acercará más al Abismo."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5754_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "Eres mi amado sirviente. Sé que lo llamas amigo, compañero, camarada... Lo que sea que te haga feliz."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "Obtuve la respuesta... Aunque no era lo que esperaba, aún obtuve la respuesta."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5756_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "¿Es \"miedo\"? ¿O \"tristeza\"? Tu expresión de desánimo es verdaderamente cautivadora."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5757_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "El aroma de la muerte y la aniquilación, tan vívido."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5758_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "¿La vida aquí? Bastante, bastante buena. Siempre que comparta un poco de ciencia mecánica y conocimientos sobre la investigación espiritual con la Sra. Muñeca, ella me deja mantener las luces encendidas."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "Espero que Jenkin y Marrón estén disfrutando su tiempo en la academia. Comparado con su libertad, los gemelos de Padre son insignificantes. Estoy seguro de que tiene toda una caja de repuestos."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Jenki"
  },
  Voice_5760_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Jenkins\""
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "No se puede salir..."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "Habiendo trascendido razas inferiores, no temo tal influencia. Incluso si el cuerpo anfitrión se destroza, la noble sangre no perecerá."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "¡Detesto a las personas con sonrisas falsas! ¡No puedes robarles ninguna emoción!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "Hmm? ¿Por qué todos están en silencio? A Karen no le gusta el silencio. Déjame contarte una historia. Érase una vez, había una montaña..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "¡Lily se apoderará del futuro... Tokuli—Li!"
  },
  Voice_5765_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5766_AwakerVoiceContent = {
    Text = "¡Lily se apoderará del futuro... Tokuli—Li!"
  },
  Voice_5766_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5767_AwakerVoiceContent = {
    Text = "Si buscas percibir Su presencia, perdonaré temporalmente tu grosería."
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "No quiero hacer esto..."
  },
  Voice_5768_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5769_AwakerVoiceContent = {
    Text = "¡Métete atrás!"
  },
  Voice_5769_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "¡Gradualmente, gradualmente sincronizándome con tu ritmo de mando!"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "¡Cada vez más cerca de convertirme en un caballero de pleno derecho!"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "Gracias por tu promoción, es un honor"
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "El baño es un gran lugar para pasar el tiempo. La comida es deliciosa y ofrecen servicios de relajación muscular. ¿Tentado? ¡Construye uno en la escuela de inmediato!"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "No, ¡no te vayas!"
  },
  Voice_5774_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5775_AwakerVoiceContent = {Text = "Listo."},
  Voice_5775_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5776_AwakerVoiceContent = {
    Text = "(gruñido de dolor)"
  },
  Voice_5776_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5777_AwakerVoiceContent = {
    Text = "(Resistencia despectiva)"
  },
  Voice_5777_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5778_AwakerVoiceContent = {
    Text = "(Resistencia despectiva)"
  },
  Voice_5778_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5779_AwakerVoiceContent = {
    Text = "(Resistencia despectiva)"
  },
  Voice_5779_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5780_AwakerVoiceContent = {
    Text = "Déjamelo a mí."
  },
  Voice_5780_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_57818_AwakerVoiceContent = {
    Text = "¡Todos los que me insulten pagarán el precio!"
  },
  Voice_57818_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57819_AwakerVoiceContent = {
    Text = "¡Todos los que me insulten pagarán el precio!"
  },
  Voice_57819_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_5781_AwakerVoiceContent = {
    Text = "Déjamelo a mí."
  },
  Voice_5781_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_57820_AwakerVoiceContent = {
    Text = "¡Nadie puede detener los pasos hacia la búsqueda de la patria!"
  },
  Voice_57820_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57821_AwakerVoiceContent = {
    Text = "¡Disfruta al máximo de este banquete de asesinato!"
  },
  Voice_57821_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57822_AwakerVoiceContent = {
