  },
  Voice_57823_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57824_AwakerVoiceContent = {
    Text = "Falsas misiones, futuros definidos... ¡Resistiré hasta el final!"
  },
  Voice_57824_AwakerVoiceTitle = {
