  },
  Voice_57825_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57826_AwakerVoiceContent = {
    Text = "¡Únete a mi ritual y conviértete en mi semilla!"
  },
  Voice_57826_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57827_AwakerVoiceContent = {
    Text = "¡Traidor, prueba mi desesperación y rabia!"
  },
  Voice_57827_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57828_AwakerVoiceContent = {
    Text = "¡Traidor, prueba mi desesperación y rabia!"
  },
  Voice_57828_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57829_AwakerVoiceContent = {
    Text = "¡Únete a mi ritual y conviértete en mi semilla!"
  },
  Voice_57829_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_5782_AwakerVoiceContent = {
    Text = "He tenido demasiada vergüenza para decirle a Aurita que no soy tan joven como ella piensa... ¿Puedes convencerla de dejar de llamarme \"hermana menor\"?"
  },
  Voice_5782_AwakerVoiceTitle = {
    Text = "Chat · Sobre Aurita"
  },
  Voice_5782_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"aurita\""
  },
  Voice_57830_AwakerVoiceContent = {
    Text = "La larga perdida ciudad de Lemuria finalmente ha desvelado su velo."
  },
  Voice_57830_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57831_AwakerVoiceContent = {
    Text = "La larga perdida ciudad de Lemuria finalmente ha desvelado su velo."
  },
  Voice_57831_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57832_AwakerVoiceContent = {
    Text = "Es hora de cumplir mi promesa."
  },
  Voice_57832_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57833_AwakerVoiceContent = {
    Text = "Es hora de cumplir mi promesa."
  },
  Voice_57833_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57834_AwakerVoiceContent = {
    Text = "Todo es parte de Su plan."
  },
  Voice_57834_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57835_AwakerVoiceContent = {
    Text = "Todo es parte de Su plan."
  },
  Voice_57835_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57836_AwakerVoiceContent = {
    Text = "Una invitación de la entidad de las estrellas."
  },
  Voice_57836_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57837_AwakerVoiceContent = {
    Text = "Todavía soy... ¡el Color del Más Allá de las Estrellas!"
  },
  Voice_57837_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57838_AwakerVoiceContent = {
    Text = "Todavía soy... ¡el Color del Más Allá de las Estrellas!"
  },
  Voice_57838_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57839_AwakerVoiceContent = {
    Text = "Una invitación de la entidad de las estrellas."
  },
  Voice_57839_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_5783_AwakerVoiceContent = {
    Text = "¡Retrocedan!"
  },
  Voice_5783_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_57840_AwakerVoiceContent = {
    Text = "¡Todos, ataquemos juntos!"
  },
  Voice_57840_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57841_AwakerVoiceContent = {
    Text = "¡El dios del laberinto subterráneo pronuncia juicio sobre todos ustedes!"
  },
  Voice_57841_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57842_AwakerVoiceContent = {
    Text = "¡El dios del laberinto subterráneo pronuncia juicio sobre todos ustedes!"
  },
  Voice_57842_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57843_AwakerVoiceContent = {
    Text = "Ave que vuela en el cielo azul, por favor escucha mi oración."
  },
  Voice_57843_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57844_AwakerVoiceContent = {
    Text = "Ave que vuela en el cielo azul, por favor escucha mi oración."
  },
  Voice_57844_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57845_AwakerVoiceContent = {
    Text = "¡No te muevas! ¡No te muevas! ¡No te muevas!"
  },
  Voice_57845_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57846_AwakerVoiceContent = {
    Text = "Temblar ante el Helot... ¡Perecer bajo el Helot!"
  },
  Voice_57846_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57847_AwakerVoiceContent = {
    Text = "Temblar ante el Helot... ¡Perecer bajo el Helot!"
  },
  Voice_57847_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57848_AwakerVoiceContent = {
    Text = "¡Todos, ataquemos juntos!"
  },
  Voice_57848_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_57849_AwakerVoiceContent = {
    Text = "¡No te muevas! ¡No te muevas! ¡No te muevas!"
  },
  Voice_57849_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_5784_AwakerVoiceContent = {Text = "Jeje..."},
  Voice_5784_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_57850_AwakerVoiceContent = {
    Text = "¡Mira! ¡Este es el poder del que dependen los Perishtites!"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "¡Mira! ¡Este es el poder del que dependen los Perishtites!"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_5785_AwakerVoiceContent = {
    Text = "Demasiado débil."
  },
  Voice_5785_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5786_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_5786_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "Hmm... ¿El maestro parece molesto? ¡Deja que Karen te anime con una cara divertida, jeje!\n¿Te sientes mejor ahora?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "Revela la esencia del mundo con intelecto humano...!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "Me encontré con algunos individuos inquietantes en el pasillo. Puede que necesites cooperar con ellos debido a las circunstancias, pero mantente alerta. El corazón humano es más cruel que la guerra, y las peores traiciones a menudo vienen desde dentro."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre @2"
  },
  Voice_5789_UnlockDesc = {
    Text = "Desbloquear después de obtener el Despertar \"Helot\" o \"Lily\""
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "¿Su tarea está hecha, verdad? ¿Puede venir conmigo a la ciudad de Londinium... Eh? ¿Su tarea de matemáticas aún no está hecha?!\nAh... lo siento, no esperaba que alguien no entendiera cálculo... Déjame ayudar."
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "Charla Casual: Sobre Aprendizaje"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "Te juro que ese tendero definitivamente apareció en el salón de Fontainebleau... Ya veo, ha sido así desde entonces. Me pregunto cuántos secretos podemos comerciar con ella"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Narcisos"
  },
  Voice_5791_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Daffodil\""
  },
  Voice_5792_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_5792_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5793_AwakerVoiceContent = {
    Text = "No lo rompas."
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "¡A Aurita le encanta jugar con todos! ¿Te unirás? Este es Jelly, aquel es Hela, y allá está Jelly... ¿eh?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "Desgracia, ¡deja que este movimiento te limpie!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "La tienda de Daffodil ya está abierta. Niños que no están preparados, por favor no entren sin más."
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5796_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "Por favor, no toques mi cuello... Solo porque no puedes verlo no significa que no exista."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "Admira a quienes tienen convicciones, sean ellos animales, Despertadores o humanos. Si son buenos luchadores, aún mejor."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5799_AwakerVoiceContent = {Text = "Ve."},
  Voice_5799_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5800_AwakerVoiceContent = {
    Text = "¡No te preocupes!"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "A Ramona le odia perder... Lo siento, quiero decir, no me gustan las despedidas; es demasiado triste."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "No soy bueno tratando con clérigos. Son aburridos y rígidos, y han entregado sus cinturones a su amado \"Dios\". Qué pena, el Sr. Salvador huele tan dulce..."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Salvador"
  },
  Voice_5802_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Salvador\""
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "La emoción de la batalla supera todo, incluida la victoria o la derrota"
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "¿A quién no le encanta una cama suave y un desagüe sin corrientes... habitación?"
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "...No me hagas recordar... los días encarcelada en Elworth..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "¡Quémalo todo!"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "¡Quémalo todo!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "Seguí el olor a sangre hasta este lugar. ¿Puedo preguntar... ofrecen paquetes de sangre fresca aquí?"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5809_AwakerVoiceContent = {
    Text = "Hmm... Agrippa tiene muchos compañeros, pero todos parecen temerle. ¿Podría ser que ella les roba la comida?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Agrippa"
  },
  Voice_5809_UnlockDesc = {
    Text = "Desbloquea después de obtener el despertador \"Agrippa\""
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "Mi vida gira en torno a la danza. Aprender otros conocimientos es difícil para mi crecimiento. Pero todos son amables; no me venderán por vanidad o dinero—lo siento."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "¡Cobarde! Posees un poder formidable similar al mío, sin embargo, te restringes. ¿En qué se diferencia eso de ponerte una collar por voluntad propia?"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Lily"
  },
  Voice_5811_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"lily\""
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "No es suficiente... todavía no hay suficiente poder..."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5813_AwakerVoiceContent = {Text = "Regresa."},
  Voice_5813_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5814_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "Sombreros de copa, bombines, sombreros de caza, boinas... Debo decir, es bastante divertido cómo ustedes, caballeros de la alta sociedad, hacen tanto esfuerzo por ocultar su calvicie."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre la Etiqueta"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "Admiro profundamente a esa persona, el dios marítimo tan puro y elegante como un lirio... ¿Dices que ni siquiera ella pudo controlar su destino y finalmente se hundió en el mar? Es realmente difícil de imaginar..."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Chat · Sobre Celeste"
  },
  Voice_5816_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"celeste\""
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "¡No hay nada en el mundo que un gigante no pueda superar!"
  },
  Voice_5817_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5818_AwakerVoiceContent = {
    Text = "¡No hay nada en el mundo que un gigante no pueda superar!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "Maldita sea, maldita sea...! El poder solo me mantiene atrapado en este cuerpo..."
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5819_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "Deseo quedarme en un lugar que siempre sea brillante... Sí, los polos. En este planeta, solo los polos."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5820_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "Yo... no puedo cargar con grandes responsabilidades. Solo puedo perseguir la luz. Así que, por favor, no dejes de brillar..."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5821_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "Si pudiera migrar, querría convertirme en una estrella..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5822_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "No importa cómo calcule, la fórmula para la transferencia de conciencia sigue siendo irresoluble..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5823_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "¡Bienvenido! ¡Vamos a divertirnos juntos!"
  },
  Voice_5824_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5825_AwakerVoiceContent = {
    Text = "¡Aquí está tu comida!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "¡Buf—Es Aurita! Uno, dos, tres... ¡Guau! ¡Bienvenido, bienvenido! ¡Un nuevo compañero se ha unido! ¿Eh? ¿Soy el nuevo compañero? Bueno, podrías decir eso"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5827_AwakerVoiceContent = {
    Text = "¿Llamas a este pequeño juguete una pistola? Solo los cobardes se esconden en las sombras para emboscar a sus enemigos."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "Es inútil. Hacer esto es completamente sin sentido."
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "No sabes absolutamente nada."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "¿Aún cuentas conmigo para ser el respaldo del \"Salvador\"?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "Lo siento, ¿has visto mi tornillo? Es extraño, pero cada vez que ese niño con orejas de ratón está cerca, parece que olvido dónde he puesto las cosas..."
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Jenki"
  },
  Voice_5831_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Jenkins\""
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "No olvidaré todo lo que has sacrificado por mi reunión con mi maestro..."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "¡Una Canción Magistral!"
  },
  Voice_5833_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5834_AwakerVoiceContent = {
    Text = "¿Has reconocido mi deseo?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "Espero que tu mando no decepcione."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "¿Es este cuerpo o mi conciencia lo que ha mejorado? Un tema intrigante."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5836_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5837_AwakerVoiceContent = {Text = "Retrocede."},
  Voice_5837_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5838_AwakerVoiceContent = {
    Text = "Apártense."
  },
  Voice_5838_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "Mis venas irradian con la voluntad de sobrevivir, gritando y llevándome a derramar sangre en cada rincón de este planeta... Ah, he divagado demasiado; por favor, perdóname. Soy Thais. ¿Me has convocado? ¿Estás listo para fusionarte conmigo?"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5840_AwakerVoiceContent = {
    Text = "Si tan solo Aigis pudiera soportar este líquido negro por todos... Después de todo, Aigis nunca existió, lo que podría ser algo bueno para este mundo, ¿verdad?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "Los hobbies incluyen la Hipótesis de Riemann—esa es la frase de la corneta, no mía. Personalmente, estoy más interesado en los estándares de masa atómica."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "El sabor de estar exiliado y a la deriva en el mar... Una vez es suficiente."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "¡Mira de cerca!"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "¡Mira de cerca!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "Mientras puedas sostener esta justicia, siempre asumiré el deber de la espada."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "¿Sabías de la leyenda del \"Pintor\" aquí? A partir de esos grafitis expresionistas, percibo un toque familiar..."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "Tan doloroso, pero tan emocionante—"
  },
  Voice_5848_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5849_AwakerVoiceContent = {
    Text = "¡Siente mi ira!"
  },
  Voice_5849_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5850_AwakerVoiceContent = {
    Text = "Deja que esta victoria sea registrada en poesía."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "Crecemos—"
  },
  Voice_5851_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5852_AwakerVoiceContent = {
    Text = "¡Mira esto!"
  },
  Voice_5852_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5853_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "Quizás cuando crezca, podré controlar mis impulsos y no drenar la Vida de los demás... Solo un poquito es suficiente para sobrevivir."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5854_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Parece que he ganado peso. ¿La cuna aún puede soportar mi peso?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5855_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "El poder está a punto de desbordarse, y me pica la espalda. ¿Estoy creciendo?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_5856_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Aunque todavía parezco un niño, ahora... tengo el poder para protegerte."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5857_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "Haré todo lo posible por crecer."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_5858_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "Ser ingrato, ¿por qué eres tan persistente en despertarme?"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5860_AwakerVoiceContent = {
    Text = "¡Me convertiré en la Madre de los Dioses!"
  },
  Voice_5860_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5861_AwakerVoiceContent = {
    Text = "¿Cuántas veces he sido convocado... Humano, más te vale tener suficiente \"comida\" preparada, o no puedo garantizar nada."
  },
  Voice_5861_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5862_AwakerVoiceContent = {
    Text = "¡Más Allá de la Puerta!"
  },
  Voice_5862_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5863_AwakerVoiceContent = {Text = "Tonto."},
  Voice_5863_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5864_AwakerVoiceContent = {Text = "¡Haha!"},
  Voice_5864_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5865_AwakerVoiceContent = {
    Text = "Hmph, no está mal. Pondré todo en nuestro próximo duelo."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "¡Eres una persona insolente!"
  },
  Voice_5866_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_5867_AwakerVoiceContent = {
    Text = "A veces, la belleza del arte radica en su aniquilación. Pero tu fracaso... claramente no entra en esta categoría."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "Eres mi oyente más importante. Siempre que lo necesites, estoy listo para cantar y darte todo."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "¿Cosas favoritas? Algas, bancos de peces, columnas, laberintos... ¡Claro que los he visto! ¡Todos están en el libro del Tío Ornn!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "¿Es esta una preparación para una misión de investigación? Entiendo."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5870_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "Mi nombre es Celeste. Mientras aún me necesites, estaré aquí."
  },
  Voice_5871_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5872_AwakerVoiceContent = {
    Text = "¡Aprende tu lección!"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "Muestra un poco de respeto, joven. En el ejército, se respeta la antigüedad, y las órdenes deben seguirse sin excepción. Tal comportamiento impropio será castigado."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "Estaría dispuesto a proporcionar un servicio postventa para esos \"juguetes pequeños\", pero la pregunta es, ¿te atreves a aceptar mi servicio?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Charla Casual · Sobre Invenciones"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "Eres el maestro aquí, pero también un invitado en mi salón. Prepararé la mejor hospitalidad para tu visita—¿prefieres una enagua escarlata o un camisón de color rosa blanco?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Lo siento, la luz del sol aquí es un poco deslumbrante... Un ratón de una cueva oscura no puede adaptarse rápidamente."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Capaz de corroerlo todo, borrando todo... Era un arma realmente impresionante. Si tan solo lo hubiera sabido entonces... Jeh."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "Se rumorea que los cuerpos que contorsionan en las llamas parecen estar bailando."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Chitchat·Sobre el Fuego"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "No salgas de noche. Incluso con una luz de 2000 lúmenes, no es completamente seguro... Una vez que pises en la oscuridad, el mal que acecha más allá de tu vista te perseguirá, te devorará, te perseguirá, te devorará... hasta que no quede nada."
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre la Noche"
  },
  Voice_5881_AwakerVoiceContent = {Text = "Grita."},
  Voice_5881_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5882_AwakerVoiceContent = {Text = "Recibido."},
  Voice_5882_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "Es el anhelo de la vida lo que impulsa al cisne a luchar por su regreso al cielo distante."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5883_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "¡Está empezando a cambiar!"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5885_AwakerVoiceContent = {Text = "¡Ayuda!"},
  Voice_5885_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5886_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_5886_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_5887_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5887_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5888_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "Ah, ¡Brown se ha escapado! Debería... debería retroceder un poco...\nQuería ser su amiga, pero terminé convirtiéndome en su pesadilla... Probablemente no quiere verme de todos modos..."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Jenki"
  },
  Voice_5889_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Jenkins\""
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "¿Capilla? Gracias, pero no soy tan anticuado. Mientras mantenga las enseñanzas del Dios de la Bondad en mi corazón y siga su voluntad, mi alma nunca se alejará de Su gloria."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la Capilla"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "Mi nombre es Ogier. Según nuestro contrato, prometo mi lealtad caballeresca a ti, proteger tu bienestar y eliminar a tus enemigos. Este juramento lo hago, nunca olvidaré."
  },
  Voice_5891_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5892_AwakerVoiceContent = {
    Text = "Esa mujer demacrada con pupilas dobles huele exactamente igual que un bicho espartano."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Agrippa"
  },
  Voice_5892_UnlockDesc = {
    Text = "Desbloquea después de obtener el despertador \"Agrippa\""
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "¿Gustos? Por supuesto, buena suerte. Siempre busco un buen augurio antes de salir cada día."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "P-Por favor, no le digas a la señorita Hannah que me estoy escondiendo aquí. No estoy listo aún..."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre Hannah"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "¿Qué tal esto?"
  },
  Voice_5895_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5896_AwakerVoiceContent = {
    Text = "Eres mi estimado invitado. Recuerda, eres el único que tiene permitido acumular deuda. Después de todo, han pasado años desde que vi un cráneo tan perfecto..."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5897_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_5897_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5898_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_5898_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5899_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_5899_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "¿Gustos...? Un rey no debería mostrar tales preferencias, pero si pudiera escapar de los molestos memoriales y oraciones, ciertamente disfrutaría de un poco de ocio en un suave sofá."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "Tomaré tu falta de respeto como una súplica por un descanso eterno."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "¿Lo odias? Odio un destino inescapable y una tragedia inevitable."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5903_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(Tarareo ahogado)"
  },
  Voice_5904_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5905_AwakerVoiceContent = {
    Text = "¡No te acerques más!"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "Oh, ¿curioso acerca de mi secreto? Este nombre, este cuerpo, este rostro, esta voz—todo proviene de la mujer que poseía una cabeza de San Pedro. Hizo un trato conmigo... Después de su muerte, me convertí en ella. En cuanto a su paradero... bueno, esa es mi colección más exquisita, ¿sabes?"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5906_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "Eres un huésped encantador; incluso yo estoy cautivado por tu cabeza única... Si alguna vez consideras separarte de ella, asegúrate de visitar mi pequeña tienda. Haha... solo es una broma."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5907_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "¿Tienes curiosidad sobre mi verdadera identidad? Aún es muy pronto para eso. Solo cree en esto: los niños perdidos pueden encontrar su camino en mi tienda. Quizás eso te incluye también a ti"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5908_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "Nadie será dañado."
  },
  Voice_5909_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5910_AwakerVoiceContent = {
    Text = "¡No ha terminado aún!"
  },
  Voice_5910_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5911_AwakerVoiceContent = {
    Text = "Al ver lo duro que trabajas, casi me siento culpable de recoger mi recompensa tan pronto. Así que, por ahora, dejaré tu cabeza donde está.\nPero no olvides que ya está reservada como mi propiedad personal, ¿de acuerdo?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5911_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "No siempre fui así; ella me dio una nueva vida. En ese sentido, tú también me has dado una segunda vida, así que atesoraré tu cabeza también."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5912_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "Escapa completamente de la oscuridad."
  },
  Voice_5913_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5914_AwakerVoiceContent = {
    Text = "Entonces la aventura es tan peligrosa..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "¿Por qué esa niña tonta huye en cuanto me ve? La próxima vez, le pisaré su hilo y veré a dónde puede ir."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Chat · Sobre Aigis"
  },
  Voice_5915_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Aigis\""
  },
  Voice_5916_AwakerVoiceContent = {Text = "¡Ugh!"},
  Voice_5916_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5917_AwakerVoiceContent = {
    Text = "Hmph~ ¡Hahaha!"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5918_AwakerVoiceContent = {Text = "¡Hahaha!"},
  Voice_5918_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "Ese chico es perspicaz; la supervivencia en la calle requiere ese tipo de ingenio. Si todavía estuviera investigando, definitivamente me haría amigo de ella."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Jenki"
  },
  Voice_5919_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Jenkins\""
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "El Santo Padre no puede salvar a todos. Puede ser capaz de ayudar a un alma desafortunada, pero no puede arrastrar a todos fuera del fango... Espero ansiosamente su caída, el colapso de su fe."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Salvador"
  },
  Voice_5920_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Salvador\""
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "Puedes encontrar todo en las alcantarillas de Londinium: salmón, jabón, whisky medio bebido... \n¿Qué? ¿Preguntas por qué sé esto? Una vez arrastré el cadáver de mi hermano a través de cinco millas de ello..."
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Charla ligera · Sobre las alcantarillas"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "¡Arrodíllate ante mí!"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "Arrodíllate ante mí."
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "Después de vislumbrar el mundo real más allá del campo de batalla, alguna vez cuestioné el valor de los \"héroes\". Pero afortunadamente, te conocí: honesto, valiente y puro. Bajo tu liderazgo, lucharé incansablemente por la paz y la estabilidad. Esta vez, sin duda completaré mi redención."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5924_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "¡Vaya! Oh no..."
  },
  Voice_5925_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5926_AwakerVoiceContent = {
    Text = "Sucio, repugnante, caótico—este es nuestro Poder."
  },
  Voice_5926_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5927_AwakerVoiceContent = {
    Text = "Odio tu acto pretencioso. ¿Crees que estoy loco, patético, verdad? Para mí, eres como Ícaro, deslumbrado por el sol. Ustedes son los verdaderamente patéticos."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "¡Déjame tomar la delantera!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "Esos tipos se sienten desconocidos. No deben ser formas de vida nacidas naturalmente en este planeta."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Chit-chat: Sobre los Viajeros Estelares"
  },
  Voice_5929_UnlockDesc = {
    Text = "Desbloquear después de obtener cualquiera de los Despertar \"Bígaro\", \"Tintura\", \"Desmayo\" o \"Wanda\"."
  },
  Voice_5931_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5931_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_5932_AwakerVoiceContent = {Text = "¡Vanish!"},
  Voice_5932_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Por favor, no..."
  },
  Voice_5933_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5934_AwakerVoiceContent = {
    Text = "Ser un monstruo está bien. Todo lo que siempre he querido es el poder para la venganza."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5934_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "Además de eliminar a tu oponente, ¿tienes algún otro deseo? A cambio, concederé tu deseo... dentro de mis posibilidades, por supuesto."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_5935_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_5936_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5936_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "¿Un compañero? ... Lo consideraré. No mueras antes de que tome mi decisión."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_5937_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "Desde que se documentó claramente por primera vez, el D-fenómeno ha afectado las vidas de más de un millón de personas. Nuestras acciones son cruciales para la supervivencia de toda la población humana."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "¡A toda velocidad!"
  },
  Voice_5939_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5940_AwakerVoiceContent = {
    Text = "Ten cuidado con la Furia del Mar"
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "Ten cuidado con la Furia del Mar"
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5942_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_5942_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5943_AwakerVoiceContent = {
    Text = "Soy Su princesa y Su madre. En cuanto a ti, no eres más que una insignificante hormiga ante Él."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Todo está bien, levantemos las velas triunfantes."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "¡Mantente alejada de mí! ¿Deseas convertirte en el juguete de la princesa o en un sacrificio para el nacimiento divino?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5945_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Una victoria fácil, ¡una victoria total!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Una victoria fácil, ¡una victoria total!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "Te permito convertirte en testigo, para contemplar el momento radiante que desafía la ética."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5946_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "¿Hollow? Los huecos a menudo se crean durante la telequinesis. ¿Los huecos creados por Casiah están vinculados a otra dimensión, como los de Disolución?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Guardián, por el poder de la Diosa Madre, he reservado un lugar para ti junto al Trono de Aequor. Serás testigo de la era de renacimiento después de la Destrucción. ¡Alégrate, porque esta es la promesa de la Diosa Madre!"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5948_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "En reconocimiento a tu respetuosa actitud, te otorgaré una respuesta. Al principio, de hecho, había lucha. Pero ahora entiendo: mi vida de lujo proviene de Él. La muerte no es el final; Él me renacerá, otorgando vida eterna a través de este ciclo retorcido..."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5949_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "El deseo de esa mujer es risible. Nada puede sobrevivir a la aniquilación, ni siquiera un \"dios\"."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Charlas: Sobre Thais"
  },
  Voice_5950_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"thais\""
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "Soy un practicante de Espiritismo, no un ser omnipotente, y por lo tanto soy propenso a errores. Las acciones de esa mujer, que han arrastrado a todos a la ruina, fueron mis inadvertidos errores... Por lo tanto, necesito tu ayuda. Para asegurarme de que puedas responder a mi llamado en cualquier momento, se te permite colocar una cama en mi habitación."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5951_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "Soportas el peso de enfrentar a los Clades, un peso pesado para alguien de tu edad... Si hubieras sabido desde el principio que no podrías cambiar el futuro, ¿seguirías habiendo llevado a cabo tu misión fielmente? No te apresures a responder; medítalo mientras descanso. Tengo curiosidad por tu respuesta."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5952_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "Ha pasado un tiempo desde que desperté, ¿no tienes nada que preguntarme? Las revelaciones de Dios, la profecía absolutamente verdadera, incluso el tesoro de la tierra hundida, ¿no tienes curiosidad? \nHm... extraño."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5953_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "Nunca he exigido adoración de nadie. La necedad de otros solo me agota aún más... Apártate, es hora de descansar."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5954_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "No veo ninguna de las cualidades de mis subordinados en ti... Quizás eso sea para mejor. El pensamiento de esa mujer me agota."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5955_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "Dios trata a todos por igual."
  },
  Voice_5956_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5957_AwakerVoiceContent = {
    Text = "Sé, eres una audiencia especial. No puedo simplemente enviarte a otra dimensión; eso causaría muchos problemas. Oye, ¿alguna vez has hecho eso con alguien más? No preguntes, ¡es mi secreto!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Eek, ¿te interesa esta apariencia? Parece que siempre hay un costo. ¡Esto debe ser uno de mis golpes de suerte, la suerte de Ryker!"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Mitag es el lugar donde tengo más recuerdos, y también... mi hogar más cálido."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Déjamelo a mí."
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5961_AwakerVoiceContent = {
    Text = "¡Qué ingenuo!"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "¡Himno de Aequor!"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "Aquello que me han otorgado—"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "Habilidad·uno·Mar tranquilo"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "Si estás dispuesto a reconocer que aún soy \"Ramona\", por favor continúa llamándome así."
  },
  Voice_5964_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5965_AwakerVoiceContent = {
    Text = "¿Qué? ¿También quieres aprovecharte de mi ira?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_5965_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "La verdad... se revela aquí."
  },
  Voice_5966_AwakerVoiceTitle = {Text = "Activar"},
  Voice_5967_AwakerVoiceContent = {
    Text = "Según las reglas de la calle, la comida debe ser comida inmediatamente."
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "Se siente como estar lleno."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Hmm... Me pica. Marrón, rasca mi espalda para mí."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "Nuevas piezas mecánicas ayudarán enormemente a que mi sistema funcione—¿no cuenta eso como gustar de algo? Lo siento, me temo que no entiendo tu pregunta. Las preferencias no tienen sentido para las muñecas mecánicas."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_5971_AwakerVoiceContent = {Text = "Mira esto."},
  Voice_5971_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5972_AwakerVoiceContent = {
    Text = "¡Mira esto!"
  },
  Voice_5972_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "Piénsalo bien."
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "Mantén la calma y piensa."
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "La señorita Bígaro, como yo, no es de este planeta... No hay nada que me una a mi hogar excepto la Tintura. Me pregunto qué piensa la señorita Bígaro sobre su tierra natal"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Bígaro"
  },
  Voice_5976_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"bígaro\""
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "¡No te acerques a mí por detrás, a menos que quieras que te rompa el cuello!"
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_5977_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Hah—¡¿cómo pudiste permitir que gatos callejeros vagaran por el campus?! ¿Qué pasaría si esa criatura maleducada rasguña a alguien?!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "¿Mi mirada te incomoda? Bien, esa es la ferocidad que me mantuvo vivo en el purgatorio."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_5979_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "Ahórrame la palabrería grandilocuente. ¿Qué quieres de mí? Debe haber una razón para mantener mi cordura intacta."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_5980_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "Mi venganza siempre estuvo dirigida a los espartanos, pero ahora, incluso ese estado-ciudad ya no existe... Bien, convertirse en tu espada no es imposible. Te acepto a regañadientes como mi compañero, pero si te atreves a traicionarme, te arrancaré el corazón."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_5981_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "Mis manos están manchadas de sangre. Mis débiles parientes no entienden mi venganza; susurran sobre mi crueldad, mi ingratitud y mi traición... La venganza siempre ha sido solo para mí, y nadie más."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_5982_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "Es hora de usar más acero."
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "Es hora de usar más acero."
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5985_AwakerVoiceContent = {Text = "Muere."},
  Voice_5985_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_5986_AwakerVoiceContent = {
    Text = "Estoy... solo llámame Bígaro, así es como todos me llaman. Sí, llámame así, tal como ellos lo hacen."
  },
  Voice_5986_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5987_AwakerVoiceContent = {
    Text = "¡Este cuerpo será el escudo de mi señor!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "¡Este cuerpo será el escudo de mi señor!"
  },
  Voice_5988_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_5989_AwakerVoiceContent = {
    Text = "\"El Cascanueces\" se supone que es un cuento de hadas romántico para niñas, pero esos individuos repulsivos solo ven las elegantes extremidades en movimiento y deseos vulgares... Asqueroso."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "¡Debo... eliminar...!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "Pandia... ¿Ella llama a esto entrenamiento? Ja, ja... Permíteme reírme un momento. Los humanos siguen siendo demasiado suaves, todo lo que hacen parece un juego de niños."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Chat·Sobre Pandia"
  },
  Voice_5991_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Pandia\""
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "¡No te acerques más!"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "¿Debo presentarme de nuevo? Realmente eres un manojo. Soy Jenkin, y este niño es Marrón. \"¡Chirri!\"\n¡No te olvides! Si estropeas nuestros nombres, ¡te golpearé el *censurado* con mi linterna! \"¿¡Chirri chirri!?\""
  },
  Voice_5993_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_5994_AwakerVoiceContent = {
    Text = "¡Salta, salta!"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "¡Salta, salta!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "¡Aquí viene el tributo de apertura!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_5997_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5997_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_5998_AwakerVoiceContent = {
    Text = "Solo un poco de piedra, dos cinceles y tres iris orientados al sol... Puedo crear cualquier cosa para ti."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_5998_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_5999_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_5999_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6000_AwakerVoiceContent = {
    Text = "¿Esto es todo lo que hay?"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6001_AwakerVoiceContent = {Text = "Bien."},
  Voice_6001_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "Esta lucha sin sentido..."
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6003_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6003_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6004_AwakerVoiceContent = {
    Text = "Después de la muerte de Tiberio, el pueblo de Roma finalmente cumplió su deseo de largo tiempo: arrojarlo al río Tíber para alimentar a los peces. Por supuesto, pagaron un pequeño precio por esto: ser arrojados a la arena por Calígula para mi entretenimiento."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6005_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6005_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6006_AwakerVoiceContent = {
    Text = "Puedo sentir que la pequeña tiene poderes similares a los míos. Aún no ha comprendido completamente la magnitud de su fuerza. Por tu bien, la entrenaré adecuadamente."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Lily"
  },
  Voice_6006_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"lily\""
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "¡Maldita sea, ¿todavía me menosprecias?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "Prueba de existencia"
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "Prueba de existencia"
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "Creo que todo sucede por una razón, pero... la violencia sin sentido, los prejuicios que llevan a los hermanos a volverse unos contra otros, realmente me entristecen. Si hay algo que detesto, probablemente sea esto."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "Realmente no quiero usar este poder."
  },
  Voice_6011_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6012_AwakerVoiceContent = {
    Text = "No bajes la guardia."
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6013_AwakerVoiceContent = {Text = "Hmph"},
  Voice_6013_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6014_AwakerVoiceContent = {Text = "¡Detente!"},
  Voice_6014_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6015_AwakerVoiceContent = {Text = "¡Detente!"},
  Voice_6015_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "¡Casiah es increíble! ¡Puede hacer aparecer un conejito en un abrir y cerrar de ojos!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Chat · Sobre Casiah"
  },
  Voice_6016_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"casiah\""
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "¡Magia, lista!"
  },
  Voice_6017_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6018_AwakerVoiceContent = {
    Text = "Disolución... Debo admitir que hay cosas en este mundo más allá del control del poder."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6019_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Baila entre las llamas esmeralda."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "No te inquietes; las cicatrices son una insignia de honor para los guerreros."
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Tiembla ante estos músculos... siempre listos para cortarte la cabeza."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "¿Hora de comida? ¿O tiempo de actividad?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6024_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Hmm! ¡De esa manera, los compañeros de Aurita no desaparecerán!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6025_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "La profesora Silvia dijo que hay que dar las gracias cuando recibimos algo... ¡Gracias, gracias, gracias!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6026_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "¡Es el turno de Aurita para ser el fantasma esta vez! ¡Solo tienes 5 segundos para esconderte! 5, 4—"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6027_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Todos desaparecieron después de comenzar a jugar al escondite. ¡Esta vez, Aurita está decidida a encontrar a todos!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6028_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "Porque encontraron mis huesos bajo el agua, ¿piensan que me gusta el agua y quiero construir una piscina fuera de mi habitación?\nHaha... Haz lo que quieras. No me molestes más con asuntos triviales."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "Una pequeña gota en el océano, una creyente inmortal pero superficial, Miryam... te saluda."
  },
  Voice_6030_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6031_AwakerVoiceContent = {
    Text = "Es mi turno de actuar."
  },
  Voice_6031_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6032_AwakerVoiceContent = {Text = "¡Ho!"},
  Voice_6032_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6033_AwakerVoiceContent = {
    Text = "Absolute increíble... Tu comentario casual ha resuelto un problema creativo que me ha estado atormentando durante meses."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6033_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "Comparado con esas damas nobles en la fiesta del vino, el temperamento de Murphy es francamente adorable."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Murphy"
  },
  Voice_6034_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Murphy\""
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "¿Maestro de Curación Mental? Esos niños me están sobrevalorando. Simplemente hago lo mejor que puedo para escuchar y ayudarles a liberar su angustia interior, como siempre he hecho."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "¡No me subestimes!"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "¡No me subestimes!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "¿Tienes sed? El agua limpia es un lujo raro en la prisión."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6038_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Buenos niños, niños obedientes~ No debes rendirte a mitad de camino~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6039_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "Debes haber caído en mi dulce trampa, ¿verdad?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6040_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Sigue adelante, solo un poco más~ Estás casi en la cima del éxtasis~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6041_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "Me uní a la escuela a la edad de 14 años. Si me hubiera graduado sin problemas, ahora me estarías llamando \"Director\"."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Tu débil cerebro parece incapaz de retener lecciones."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "¿Preguntas cuál es mi deseo? Viajes seguros y paz—¿eso no cuenta?\nEn cuanto a otros deseos, no he pensado mucho en ellos... Pero lo consideraré cuidadosamente y te lo diré más tarde."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6044_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"Lo que busco son los misterios del universo. Quiero entender qué Poder me está controlando.\" Aunque no estoy satisfecho con la trama de esta novela y encuentro su ciencia ficción risiblemente naive, después de leerla, deberías entenderme... Espera, ¿no has leído este libro?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6045_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "La misión y el destino son similares. No pueden ser abandonados fácilmente, ni es necesario hacerlo."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6046_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "¿Siempre parezco ocupado? Sí, los asistentes pueden ayudar de vez en cuando, pero en alguna investigación, soy irreemplazable. ¿Quieres ayudar? Entonces verifica de vez en cuando si todavía estoy vivo."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6047_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "¿Quieres decir que estoy enojado? ¿Sabes cuántos músculos se necesitan para sonreír? Una vez expliqué esto en clase, lo cual claramente se deslizó de tu lisa cabeza. La respuesta es al menos diecisiete, y no tengo razón para estar enojado contigo."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6048_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "Miss Ramona dijo: \"No necesito acomodar a todos. ¿Entiendes lo que esto significa? ...¿Significa que ya no necesito su protección?\""
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6049_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "Trece informes requieren aprobación urgente, seis comunicadores dañados están esperando ser reparados, y también necesito monitorear los resultados de cinco experimentos diferentes de extracción de Plata... Así que, en lugar de perder mi tiempo limitado molestándome, ¿por qué no intentas ejercitar tu débil materia gris?"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6050_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "Espero que la próxima vez, mi tierra natal responda a mi llamada."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Bloqueo liberado."
  },
  Voice_6052_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6054_AwakerVoiceContent = {
    Text = "Estoy tan feliz... Eres tan parcial y me favoreces tanto."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6054_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "A otros les puede molestar si piensan que estás mostrando favoritismo."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6055_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "¿También anhelas por mí?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6056_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Finalmente, se ha acabado. No más ver esos negros y viscosos..."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "Por todo lo que me has dado, tu amor ya se ha convertido en uno con el mío..."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6058_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6059_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_6059_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "Entonces peligroso."
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "Has trabajado tanto; es hora de disfrutar los frutos de tu trabajo, ¿verdad? Acércate, no te decepcionaré~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6061_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "I... entiendo tu intención. Aunque aún soy torpe, ¡Aigis luchará por ti con todas sus fuerzas!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6062_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Tu mirada me quema... ¿Te ha causado algún problema Aigis?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6063_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "Aigis está muy ansiosa... insegura si puede cumplir con tus expectativas..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6064_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "Tu mirada sobre mí hace que Aigis se sienta incómoda... ¿No temes a la maldición?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6065_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "P-por favor, no mires mis ojos... Aigis tiene miedo de hacerte daño... Después de todo, soy como un monstruo..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6066_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "El sentido del olfato de la bestia es solo suerte, ¿de acuerdo? No te equivoques, ¿vale?"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6067_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "No puedo detenerme aún..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Poder, ¡incesante!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "Poder, fluyendo sin cesar."
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "¿Te gusta el mar? Amo el mar sin importar qué. Aún recuerdo ese día hace muchos años cuando el mar me entregó suavemente la muerte tan esperada a mí, el desafortunado."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "Por alguna razón, ha surgido un placer sin precedentes..."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "Esta corriente subterránea despedazará a los enemigos."
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "Esta corriente subterránea despedazará a los enemigos."
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "He estado esperando a alguien que me enseñe el verdadero amor, el dolor y el deseo. ¿Puedes cumplir mi deseo? ¿Puedes redimirme de esta oscura prisión?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6076_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "¿Quieres saber la verdad? Odio la prisión, odio la oscuridad, y la odio tanto que podría morir. Quiero ser notado y quiero ser encendido..."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6077_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "Todo es por el bien eterno del futuro."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "¿Quieres disfrutar de mí? Entonces conviértete en mi esclavo. Te haré derretir de calor~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6079_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Considéralo una humilde ofrenda de tu sirviente."
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "Estoy tan aburrido, tan aburrido. Comparado con esos grandes prisioneros temblorosos, esto es como jugar a la casa. ¿Por qué no me haces compañía~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6081_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "Anhelo más esclavos, para escuchar sus gemidos y súplicas—\n¡Tráeme más esclavos~ Por favor~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6082_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Lo siento, me perdí en recuerdos otra vez. Por favor, no te veas triste. Es tu turno de narrar tu historia. ¿Te sientes como para escribir un poema? ¿Tus aventuras, tus experiencias, tus alegrías, tus tristezas, fluirán como un río flotante de tu mente a tus dedos?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6083_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "Fui solo una marca fugaz en el pergamino, sin embargo, nuestro encuentro ha causado que perdure. Quizás esto sea un milagro. Atesoraré este milagro y compondré poemas atemporales para ti."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6084_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Alguien una vez me dijo que la poesía se escribe para ser apreciada... ¿Puedo escuchar tus pensamientos sobre esto?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6085_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "¿Alguna vez has experimentado esto? Enfrentar las ofensivas de los demás con un corazón perdonador, solo para no lograr el resultado deseado. Das una rosa, pero tus manos quedan sin fragancia persistente, solo con las marcas sangrientas de espinas afiladas."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6086_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6087_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6088_AwakerVoiceContent = {
    Text = "Mi pluma y tinta..."
  },
  Voice_6088_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6089_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6089_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6090_AwakerVoiceContent = {
    Text = "Incorrecto..."
  },
  Voice_6090_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6091_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6091_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "¡Esta es una bendición del Gran Ser!"
  },
  Voice_6092_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6093_AwakerVoiceContent = {
    Text = "Bendición del Gran Pálido"
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "No tengo tiempo para descansar. El D-fenómeno ha destruido dos de mis cuerpos. Antes de que el final me alcance, hay mucho que necesito entender... Ayúdame, empezando por preparar los materiales para el experimento. Confío en que no calcularás mal el balance."
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6094_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "Amo las vidrieras en Fontainebleau. Proyectan diferentes matices en los rostros de las personas: un púrpura desesperado, un azul halagador y, por supuesto, mi favorito: un rojo ambicioso..."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Aquí, a menudo percibo la presencia de mi Señor, pero quizás aún no estoy listo para enfrentarme a Él... En cualquier caso, gracias por ofrecerme refugio."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "La traición convierte a las personas en monstruos, sin importar de qué lado estén. Por eso detesto a los traidores."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Hameln, a tu servicio."
  },
  Voice_60985_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_60986_AwakerVoiceContent = {
    Text = "Una vez conocí a alguien con una comprensión casi instintiva de la música. Los conciertos y sinfonías creados por esta persona fueron inolvidables.\nUn verdadero genio."
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Charla Casual: Acerca de Viejas Conocencias"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "No disfruto pasar tiempo en estrategia. Comparado con la música, el arte de la estrategia tiene poco valor. Sin embargo, como herramienta para despejar obstáculos, es necesario. Por el bien de alcanzar la cima de la música, no me importa usarlo."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Charla Casual: Sobre la Estrategia"
  },
  Voice_60988_AwakerVoiceContent = {Text = "Grosero."},
  Voice_60988_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "Aquí está de nuevo. ¿Cuál es esta melodía? Desde la última vez que la escuché, ha permanecido en mi mente, negándose a irse o descansar."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_60989_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6098_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_60990_AwakerVoiceContent = {
    Text = "En términos de técnica, la planificación estratégica y la dirección musical no son diferentes. La humanidad, la emoción, el deseo... son tan claros y dóciles como las notas en un pautado, exhibidas ante mis ojos, danzando a lo largo del camino de la batuta. Entender la música es entenderlo todo."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Charla Casual: Sobre la Comunalidad"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Casi allí, solo un poco más. ¡Debo terminarlo; debo escucharlo!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_60991_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60992_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_60993_AwakerVoiceContent = {Text = "Grosero."},
  Voice_60993_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_60994_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60994_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_60995_AwakerVoiceContent = {
    Text = "La música trasciende el lenguaje, la escritura y todo. Si esto no es perfección, no sé qué es."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_60995_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Presta atención al ritmo."
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "Ajuste completo."
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "Me alegra que entiendas la importancia del entrenamiento."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "Entregaré una actuación perfecta."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "¿Envidioso? Estas duras escamas son prueba de un linaje noble."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = [[
Una vez fui elogiado, pero... eso no era verdadero talento.
Mis obras eran meras imitaciones de mis predecesores.]]
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Charla Casual: Sobre el Trabajo"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Maderas y cuerdas... entrelazándose hacia arriba y hacia abajo, el motivo reaparece... Ahora recuerdo, es el réquiem que compuse para el genio fallecido prematuramente, la estrella caída."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_61001_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "Hmm? ¿Tienes una nueva pieza para mostrarme?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "Esta melodía está dedicada a las almas de los difuntos."
  },
  Voice_61003_AwakerVoiceTitle = {Text = "Activar"},
  Voice_61004_AwakerVoiceContent = {
    Text = "La bailarina verde poseía una elegancia digna de ser la líder de una troupe de corte.\nSi tuviera la oportunidad, realmente espero que podamos colaborar."
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Charla ligera: Sobre Liz"
  },
  Voice_61004_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Liz\""
  },
  Voice_61005_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "Hay un concertino en la orquesta, pero un concertino solo no puede hacer una orquesta completa. Mi orquesta no tiene lugar para aquellos que solo buscan presumir."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "Creo que escuché una melodía. ¿Alguien está ensayando cerca?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_61007_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_61008_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_61009_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6100_AwakerVoiceContent = {
    Text = "¡Prepárate para conocer tu perdición!"
  },
  Voice_6100_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "Sí, sí, eso es—la misa final, un réquiem para la música en sí misma!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_61010_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "Ah, Guardián, has llegado justo a tiempo. Dime, ¿qué piensas de este movimiento?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Cuerdas, comiencen."
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_61013_AwakerVoiceContent = {
    Text = "¡Crescendo, crescendo!"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "Quedó claro, esa melodía serpenteante, como el llanto de un alma... Estoy seguro de que la he escuchado en alguna parte antes."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_61014_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "La racionalidad y el orden allanaron el camino. Caminé hacia arriba y abrí las puertas del vestíbulo. Más allá de ellas, nada quedó: verdaderamente la música eterna trasciende la razón."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Charla Casual: Sobre la Razón y el Orde"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Mira mis manos, uno, dos, tres."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "Escuché la actuación de tu supuesta orquesta, llena de errores. Pero no te preocupes, tengo un plan detallado para presentar un espectáculo perfecto antes del Festival de la Escarcha Plateada."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "Nunca podré olvidar la primera vez que escuché la música en lo profundo de mi conciencia. En esas notas y acordes, el mundo real desapareció; solo quedó música pura y sublime."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "Es una pena. Parece que se necesitan más ensayos."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "Esta es una orden."
  },
  Voice_6101_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_61020_AwakerVoiceContent = {
    Text = "Normalmente no extiendo tales invitaciones, pero... ¿te gustaría intentarlo? Toma la batuta y da nueva vida a la música?"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_61020_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "Prefiero expresarme a través de la música en lugar de palabras. Pero comunicarme contigo se siente como dirigir una orquesta que ha sido ensayada innumerables veces—suave y a menudo sorprendentemente placentera.\nTienes un lugar especial tanto para la música como para mí."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_61021_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "En una sinfonía, la coordinación entre los instrumentos es crucial; cómo cada sección se une y sale aporta una experiencia diferente a la música.\nLo que quiero decir es que, si comandar Despertadores es una actuación, lo estás haciendo bien."
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_61022_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "¿Te gusta esta pieza? Presenta el motivo en solo cuatro compases, con los instrumentos de viento elevando la melodía hasta que se alcanza el tema. Tal diseño ha influido en innumerables sucesores... Lo siento, ¿hablo demasiado?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_61023_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Actuación Perfecta."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_61025_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_61026_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_61027_AwakerVoiceContent = {
    Text = "Cada uno de nosotros oculta una melodía en nuestros corazones, atrapada por la razón y el cuerpo, solo para ser expresada plenamente en la locura."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Solo la música merece alabanzas."
  },
  Voice_61028_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_61029_AwakerVoiceContent = {
    Text = "Solo la música merece alabanzas."
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6102_AwakerVoiceContent = {Text = "Ve."},
  Voice_6102_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_61030_AwakerVoiceContent = {
    Text = "Escucha, ¡este es el réquiem final!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "¡Ruega por misericordia!"
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "Escucha, ¡este es el réquiem final!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_6104_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6104_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6105_AwakerVoiceContent = {
    Text = "¿También deseas ser consumido por las llamas verdes?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "¿Te atreves a perder el enfoque?"
  },
  Voice_6107_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6108_AwakerVoiceContent = {
    Text = "¡Enfócate!"
  },
  Voice_6108_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_6109_AwakerVoiceContent = {
    Text = "¿Cómo pueden existir estudiantes tan adorables en la universidad~ Solo le pregunté: \"¿Te gustaría ser mi sirviente?\" y se sonrojó, balbuceando algo sobre cómo \"ya soy un caballero del Guardián\"...\nClaramente, no hay absolutamente ningún conflicto~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Charlas Casual · Sobre Ogier"
  },
  Voice_6109_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"ogier\""
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Ni siquiera pienses en acercarte a la princesa."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "Habilidad·uno·Olas furiosas"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "Acepta tu destino."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "Habilidad·uno·Mareas crecientes"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "Las puertas de mi tierra natal se alejan... No... No otra vez..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "¡Fuera del camino!"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "¡Fuera del camino!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "Paga el precio por tus acciones."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "¿Quieres morir?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "Creo que he sido afectado por la Disolución nuevamente... ¡Mi corazón se está disolviendo! Solo un par de aspirinas, un látigo y un poco de dolor deberían hacer el truco para curarme..."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "¿Incluso tú no puedes curar esta enfermedad fantasmal? Entonces, ¿por qué persigues la Disolución, arriesgando tu vida?"
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "¡Soy el último guerrero romano—Uvhash!"
  },
  Voice_6119_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6120_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6120_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6121_AwakerVoiceContent = {
    Text = "¡Soy el último guerrero romano—Uvhash!"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "Disolución...? Por supuesto, lo sé. Solo significa que el vínculo maestro-esclavo se ha roto, ¿verdad? ¿Qué tan difícil es eso?"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "He sido convocado; la frontera entre dioses y tontos se ha difuminado."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6123_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Hmm... La presión está bien equilibrada, y la técnica de masaje es bastante buena~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "¿No es la decoración aquí demasiado anticuada? Es inquietante, como si estuviera encantada."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Aquí están las plantas exuberantes, el aire tranquilo y un remedio para la enfermedad de mi hermana. Para las dos es el hogar nuevo más maravilloso."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "Nunca esperé encontrarnos aquí... Me pregunto cómo ha estado mi hermana desde entonces. No importa cuánto pregunte, solo dice que está bien... Lo siento, y gracias por reunirnos."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Chat · Sobre Desmayo"
  },
  Voice_6127_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"desmayo\""
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "Una ofrenda a mi Señor."
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "Una ofrenda a mi Señor."
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "Cálmate, cálmate, cálmate..."
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "Hay muchos \"yo\" adentro. Feliz, triste, enojado... Aman el pastel de esponja, odian los días lluviosos de Londinium. Todos se llaman \"24\" y todos te adoran."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6131_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "Solía trabajar hasta la medianoche todos los días: hilando, lavando, limpiando, cuidando niños, incluso rebuscando... Haría cualquier cosa para ganar dinero. En aquel entonces, vivir era simplemente sobrevivir.\nAhora, tenemos comida fresca, camas cálidas y amos amables como tú... Es más de lo que jamás soñé."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6132_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "No importa qué, compartiremos un bistec y una cama, y nunca te causaremos problemas."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6133_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "Heh, esa mujer tiene tanto miedo de que salga que ni siquiera se atreve a dormir por la noche. Relájate, no te mataría—no cuando me estás ofreciendo regalos.\n¿Quién soy? Por supuesto, soy \"24\", ¡jajaja!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6134_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "Me siento fantástico en este momento. ¿Qué? ¿Dices que mi mente ha sido tomada por otra cosa? No... de ninguna manera... uh..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6135_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "Como sujeto, eres bastante perceptivo. Antes de mi próximo largo sueño, adornaré este momento con mi presencia."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Hmm, el mar está bastante cálido esta noche..."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "El pájaro blanco que gira en el sueño ha llegado."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "Como desees, mi presencia se ha vuelto más tangible."
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "¡Tan satisfactorio, tan satisfactorio!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6141_AwakerVoiceContent = {Text = "¡Dulce!"},
  Voice_6141_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "¡Déjamelo a mí!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "¡Déjamelo a mí!"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "¡Bienvenido a — nuestra fiesta!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Exaltar · Manía"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "Esta chica sin duda lleva la sangre de Yu... No, Yu no es lo suficientemente anciano como para tener descendencia. Sin embargo, su poder es de hecho similar al de Yu."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Respecto a la Línea de Sangre Divina"
  },
  Voice_6145_UnlockDesc = {
    Text = "Desbloqueado tras adquirir Despertar \"Aigis\" o \"Murphy\""
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "¡La bondad del Maestro, Karen no se atreve a olvidar ni por un momento!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "—¡Tan dulce y deliciosa!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Karen está a dieta y no puede comer demasiado~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "Estos tipos no son dignos de ser mis oponentes."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Explicar el arte es tan ridículo como explicar las acciones de ferrocarriles—por favor, no hagas la vida más difícil para los pobres artistas."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Aigis... ¿Hice algo mal?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Tus oraciones han sido escuchadas."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "Tus oraciones han sido escuchadas."
  },
  Voice_6153_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6154_AwakerVoiceContent = {
    Text = "Hmph, irrespetuoso."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "Ah, ¿fue el Maestro hace un momento? No, no importa. La última vez que lo saludé, no me reconoció... Lo esperé en prisión, con la esperanza de que me llevara, pero nunca vino, ni siquiera durante el disturbio."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Charlas · Sobre \"N\""
  },
  Voice_6155_UnlockDesc = {
    Text = "Desbloqueado después de completar el Capítulo 7 de \"Operación de Investigación\""
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Responder al Despertar de la humanidad y formar alianzas es cumplir con mi deber inconcluso—si logras volverte lo suficientemente fuerte para desafiarme, sería ideal."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "Hermana, Marrón, la cobarde del orfanato, estoy contento solo de tenerlos como amigos. Uh... bueno, supongo que tú también cuentas. Marrón, comparte un caramelo con el Guardián.  \n\"¿Cheep?!\""
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6157_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "El Barrio Este no es lugar para niños. Los astutos capataces encontrarían maneras de recortar el salario de los repartidores de periódicos y criticarían a los repartidores de leche por su velocidad... ¡ridículamente exigentes! Para sobrevivir en las calles, solo puedes confiar en ti mismo. Nadie más puede ser de fiar."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6158_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "Mis \"malos hábitos\" no se pueden cambiar de la noche a la mañana, ¿entiendes, verdad? Dormir bajo puentes y en desagües, sobreviviendo con basura—solo estar vivo ya era bastante difícil... No puedes esperar que empiece a hacer mi cama de inmediato. ¡Tomará al menos medio mes acostumbrarse!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6159_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "No es agradable perderse en el espacio. Dado que me has sacado de allí, siéntete libre de preguntar lo que quieras, pero no puedo garantizar que pueda ayudar.  \nConsiderando mi edad, no te molestaría con un niño, ¿verdad?~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6160_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "¡Oye, Westsider! ¿Has visto a Marrón? Ese glotón debe haber olfateado algo de nuevo."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6161_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "\"Los que tienen fuerza no deben usar su poder para oprimir a otros, pues todos compartís mi sangre.\" — Recuerdo las enseñanzas del Dios de la Compasión y usaré esta fuerza para proteger a los que me rodean."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6162_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "¿Tienes curiosidad sobre lo que vi al principio del universo? Puedo contarte, allí no había nada."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6163_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "Ahora está más brillante."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "La lámpara eterna..."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "La conexión con la patria se ha fortalecido."
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "Si puedo liberar al mundo de su sufrimiento, estaré contento."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Dame más órdenes, Mensajero Pálido. Que tu llama ilumine mi camino."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6169_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "La forja de una persona implica no solo el cuerpo, sino también el corazón."
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6171_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6171_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6172_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_6172_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6173_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6173_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6174_AwakerVoiceContent = {
    Text = "Hmm! Tu temperatura es un poco alta para coral. Pero... es cálida e intensa. Me gusta."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "Ah... ¿Necesitas algo? Si es posible, hablemos entre bastidores..."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Marchitándome antes de florecer, como un loto anegado... Buscando paz en las frías y furiosas mareas, demasiado tímido para perseguir mi propia felicidad... Ese soy yo, el Guardián."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6176_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "Una vez luché con este dilema: ¿Es el dolor más largo que la vida misma? Si es así, ¿es un sueño pacífico más feliz que una vigilia atormentada? Después de despertar, yo también fui atrapado, hasta que me trajiste este refugio seguro..."
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6177_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "Durante mi tiempo en el sanatorio, intenté hacer amigos, pero la gente se mostró reacia a acercarse a mí... ¿Es por este \"veneno\" que erosiona los huesos? De todos modos, ten cuidado cuando te acerques a mí."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6178_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "El sonido de la campana llevado por el viento nocturno trae paz. ¿Te gustaría sentarte en la silla de piedra y escuchar por un momento? Prepararé un asiento para ti con una bufanda."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6179_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "¿Has oído hablar del \"entierro en el mar\"? En el pueblo donde vivía antes, había una costumbre de sumergir a los fallecidos en el mar, haciendo del océano el lugar de descanso final de todos. En cuanto a mí, volví al abrazo del mar temprano..."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6180_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_6181_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6182_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_6182_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6183_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_6183_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6184_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "El registro de combate ha sido archivado. Gracias por tu arduo trabajo, Guardián."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6186_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6187_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6187_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6188_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "Puedes continuar."
  },
  Voice_6189_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6190_AwakerVoiceContent = {
    Text = "Los visitantes del salón reciben la mejor hospitalidad... ¿Han preparado los invitados secretos dignos de este gran banquete como entrada?"
  },
  Voice_6190_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6191_AwakerVoiceContent = {
    Text = "Amo las cosas nuevas. A lo largo de mis milenios de viajes, he sido testigo de muchas innovaciones y descubrimientos fascinantes, como formas poéticas y escenas cinematográficas. Los humanos son criaturas realmente intrigantes."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Hmm, Lily la reconoce. Cuando su madre no está, Lily se queda en su casa."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Narcisos"
  },
  Voice_6192_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Daffodil\""
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "¿Eres el que está perturbando mi largo sueño?"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6196_AwakerVoiceContent = {
    Text = "¿Dioses? Solo los tontos confiarían sus vidas a seres tan intangibles. En lugar de depender de los llamados dioses, piensa más en cómo volverte más fuerte."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "Qué maestro de gladiadores, solo un insecto sin valor."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Agrippa"
  },
  Voice_6197_UnlockDesc = {
    Text = "Desbloquea después de obtener el despertador \"Agrippa\""
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "Después de la victoria, por favor permíteme llevar los materiales necesarios para la reproducción."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "¡Gran amigo! ¡Compañero! ¡Hoo-hoo, seamos mejores amigos para siempre con Aurita!"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "Estoy emocionado en este momento... Si no quieres morir, será mejor que mantengas tu distancia de mí."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "¿Está bien que esa persona trate a los demás así? La Sra. Sarah dijo que los niños no deberían tener rabietas..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Murphy"
  },
  Voice_6201_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Murphy\""
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "La gloria de la victoria te pertenece"
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "¿No puedo comer más, está lleno~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "El vacío dentro ha sido llenado~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Un poco más abrasador~"
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "Conozco a esa niña. A veces se queda lejos, observando la actuación. Es mejor que no se acerque, ¡de lo contrario, estos pequeños espectadores estarán \"mental y físicamente exhaustos\"!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Chat · Sobre Desmayo"
  },
  Voice_6206_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"desmayo\""
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "La Tintura dijo: \"Recompensar la bondad.\" Así que, mientras esté dentro de mi capacidad para ayudar, extenderé una mano..."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Hola, Guardián. ¿En qué puedo asistirte?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "Un día, regresaré al campo de batalla como el líder en la vanguardia."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6209_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "¿Puedes creerlo? Puedo sentir mi hueso de la pierna rota sanándose."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6210_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Te agradezco sinceramente por confiar en mí para entrenarme hasta este nivel. También debes ser alguien que persigue la justicia, así que continuaré trayendo gloria a nuestro ejército aquí."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6211_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "El día del viaje se acerca, y mi sangre hierve de pasión."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6212_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "El honor de ser un guerrero está siendo restaurado."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6213_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6214_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6214_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6215_AwakerVoiceContent = {Text = "¡Ay!"},
  Voice_6215_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6216_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6216_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6217_AwakerVoiceContent = {
    Text = "¡Tramposo!"
  },
  Voice_6217_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "¡Ups, perdón! ¡Lo haré posible la próxima vez!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "Oigo a alguien llamando mi nombre, Agrippa, Agrippa, Agrippina..."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6219_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "Vi... Ascendiendo desde la oscuridad del pozo, aparecieron innumerables ojos en su huevo de carne. Me miraban, llamándome... Dios Laberinto."
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6220_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "Tengo un impulso muy fuerte de ver un duelo... Sería aún mejor si se lleva a cabo en un laberinto."
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6221_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Contrato... Sí, quiero firmar un contrato contigo, un contrato maestro-sirviente eterno..."
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6222_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Hmph... No está mal. Dame más. Necesito alimentar a estas crías de araña."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6223_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "¡Qué inmundicia, qué abominación! Ah—¡para! ¡Por favor! No me hagas verlo, y no lo mencionen cerca de mí..."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "Mi pasado era rutinario y tranquilo, como los mares cercanos al ecuador, nada que merezca la pena mencionar."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6225_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Hmm...? Madre, un abrazo... Mm, tan cálido..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "Polvo de estrellas..."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "¡Oh no, ¿estás perdido?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6229_AwakerVoiceContent = {Text = "Inútil."},
  Voice_6229_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6230_AwakerVoiceContent = {
    Text = "Cada vez que recuerdo a esos traidores arrodillados y llorando por misericordia, siento una oleada de satisfacción, y las llamas en mi corazón parecen desaparecer."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "El capitán del barco me sacó de mi hogar y me confió la misión de la primera travesía del barco. Desde entonces, el significado de mi vida ha estado más allá de mi control. Alguien me dijo que, al menos en esta segunda vida como Despertador, debería vivir para mis propios deseos... ¿Me ayudarás? Ayúdame a ser egoísta, ayúdame a encontrar mi deseo."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6231_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "Agrippa. No tengo nada que decirte, a menos que te atrevas a ofrecerte como mi gladiador."
  },
  Voice_6232_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6233_AwakerVoiceContent = {
    Text = "Tawil... mucho más peligrosa de lo que imaginamos. Si no estoy cerca, debes tener mucho cuidado con ella."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Tawil"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "Con este razonamiento... ¡interpreta el mundo!"
  },
  Voice_6235_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6236_AwakerVoiceContent = {
    Text = "Con este razonamiento... ¡interpreta el mundo!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "¡Brilla intensamente!"
  },
  Voice_6237_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6238_AwakerVoiceContent = {
    Text = "Para lo mejor de mi capacidad."
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "Para lo mejor de mi capacidad."
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "Déjalo pudrirse."
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "Déjalo pudrirse."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "Las sonrisas y la etiqueta sirven como una capa de armadura, ayudándome a mantener distancia de los demás y a evitar perturbaciones tediosas. En cuanto a mi verdadero yo... No me importa mostrártelo."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6242_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "Los pensamientos se acumulan como cal blanca y son lavados en hermosos corales. Se fusionan conmigo, palpitando con mi latido... ¿me escucharás?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6243_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "La inspiración es como burbujas que suben en el mar: un toque suave, y desaparecen. ¿Eres tú igual?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6244_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "La guerra, el saqueo y la fama son todos deseos humanos. La humilde escultora no tiene interés en lo que los humanos persiguen; solo desea ser una esclava de la belleza."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6245_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "Una vida maravillosa reside en la indulgencia. A veces, no deberías ser demasiado duro contigo mismo."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6246_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "Solo heridas menores..."
  },
  Voice_6247_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6249_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6249_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6250_AwakerVoiceContent = {
    Text = "¡Maldita sea!"
  },
  Voice_6250_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6251_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6251_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "El D-fenómeno trae caos y desastres. Quizás mi país se hundió en el Aequor por ello..."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6253_AwakerVoiceContent = {Text = "¡Hah!"},
  Voice_6253_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6254_AwakerVoiceContent = {Text = "¡Ah~!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Majestad del Gigante"
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "¡Intenta esto!"
  },
  Voice_6256_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6257_AwakerVoiceContent = {
    Text = "Sacrificio Inevitable"
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "No está nada mal, esta es la gloria del guerrero."
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "¡Tú! ¿Cómo pudiste dejar entrar a esa mujer aquí? ¡Establece un área restringida para mí! ¡No dejes que se acerque a menos de 50 pasos de mí!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Miryam"
  },
  Voice_6259_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Miriam\""
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "¿Por qué quiero volverme más fuerte? En mi tribu, los débiles son despojados de su ropa, se les rapa la cabeza y son sometidos a las humillaciones más sucias imaginables; el costo de ser débil es algo que no todos pueden soportar."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6260_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "¡Diosa de la fortuna, otórgame tu bendición!"
  },
  Voice_6261_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6262_AwakerVoiceContent = {
    Text = "Como era de esperar... ¿La fuerza humana tiene límites...?"
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Los músculos y huesos se relajaron ligeramente."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6263_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "¿Es esta la manifestación de tu deseo, profundizar en mi afecto?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6264_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "¡Desata tu locura!"
  },
  Voice_6265_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6266_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6266_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6267_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6267_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6268_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6268_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6269_AwakerVoiceContent = {
    Text = "Ah, imperdonable..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "¡Punto Imprudente!"
  },
  Voice_6271_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6272_AwakerVoiceContent = {Text = "¡Pum—"},
  Voice_6272_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_6273_AwakerVoiceContent = {
    Text = "¡Sigue así! Tus notas finales prometen."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "Escuché que un ladrón de los barrios bajos apareció, ¿trayendo consigo a una rata gorda? Hehehe... ¡Mírame eliminar esta amenaza para mi maestro!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Jenki"
  },
  Voice_6274_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Jenkins\""
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Vamos, respira hondo—"
  },
  Voice_6275_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6276_AwakerVoiceContent = {
    Text = "Interesante, tu crecimiento en batalla supera con creces mis expectativas. Dado tiempo, podrías convertirte en el próximo... Extraño... A través del tiempo, aún encuentro esperanza en un ser tan débil como tú."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6276_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Quizás ahora es el momento de decir esto. Escucha con atención.\nLotan, la Bestia Estelar, te desafía formalmente... Pero no te preocupes, aseguraré tu seguridad hasta que alcances tu cima. No dejaré que mi oponente elegido enfrente el mismo destino nuevamente."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6277_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Hmph... No puedo entender por qué Ramona te aprobaría como socio. Admito que llevas el aroma de la fuerza, pero todavía estás lejos de ser mi rival."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6278_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Sí, mírame con reverencia. Soy la Reliquia más antigua del Planeta, merezco respeto de los insignificantes—he protegido este Planeta durante eones. Pedir una batalla emocionante como recompensa no es demasiado, ¿verdad?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6279_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Hah, no tengo la energía para jugar a la casita con niños. Si sabes lo que es bueno para ti, solo encuentra un rincón y mantente en silencio."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6280_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Almas sin protección, os concederé la paz final"
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6282_AwakerVoiceContent = {Text = "Alerta."},
  Voice_6282_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6283_AwakerVoiceContent = {Text = "Alerta."},
  Voice_6283_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "Algo está aullando... en mi mente."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6284_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "Se siente como si un velo de neblina blanca estuviera nublando mis pensamientos."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6285_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "El sonido se volvió más fuerte, y la niebla blanca se espesa."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6286_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "¿Es ese el sonido de las manecillas del reloj moviéndose?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6287_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "Cuando suene la campana, ¿seguiré aquí?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6288_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "Un truco tan torpe... Hmph, ingenuo tonto. ¿Cómo podrías pensar que podrías atarme tan fácilmente?"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6290_AwakerVoiceContent = {
    Text = "Disculpe... ¿Ha visto a mi hermana, Jenkin? Es una chica que lleva un ratón y puede ser bastante feroz... No podría equivocarme con ella."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Jenki"
  },
  Voice_6290_UnlockDesc = {
    Text = "Desbloqueado tras completar \"Investigación Operación\" Capítulo 2"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Gracias por tu amabilidad."
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6293_AwakerVoiceContent = {Text = "Listo."},
  Voice_6293_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "Por favor, míralo con expectativa."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "Cantando para ti."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "¿Nuevo Guardián? Da lo mejor de ti y muéstrame si eres digno de ser mi oponente."
  },
  Voice_6296_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6297_AwakerVoiceContent = {
    Text = "Aunque soy pacifista, \"ellos\" claramente piensan lo contrario..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6298_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_6298_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6299_AwakerVoiceContent = {
    Text = "¡Retrocedan!"
  },
  Voice_6299_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6300_AwakerVoiceContent = {
    Text = "¿Cómo te atreves a humillarme así..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "¿Estás listo? ¡El espectáculo de magia de Casiah está a punto de comenzar! No apartes la vista, no te pierdas los momentos destacados. ¡Es hora del espectáculo!"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6302_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6303_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = "Recibí tu horario de Silvia, es demasiado severo para los novatos. Entiendo que están haciendo lo correcto, pero hacer que los reclutas carguen con una pesada carga puede causar problemas innecesarios para el equipo.\n ¿Dijiste que no eres un novato? No, puedo ver en tu mirada que aún no has pasado por muchas cosas."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6304_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "Desprecio mis propios fracasos... ¡Ah! ¡No hay necesidad de consolarme! Esas experiencias pasadas se han convertido en la fuerza motriz de mi crecimiento. ¿No me he convertido ya en tu apoyo?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "Simplemente no puedo llevarme bien con ese hombre. La vida no se trata solo de pecado y castigo, ¿verdad? ¿No es más importante aprovechar el momento?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Salvador"
  },
  Voice_6306_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Salvador\""
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "El tiempo se está acabando, movámonos."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "Odio las velas que se apagan fácilmente, el pan negro y los hilos sueltos en las faldas... Sin razón, simplemente los odio. ¿No es natural?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Desde que me has coronado como la Santa Doncella, ¡debes someterte!"
  },
  Voice_6309_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6310_AwakerVoiceContent = {
    Text = "Desde que me has coronado como la Santa Doncella, ¡debes someterte!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6311_AwakerVoiceContent = {Text = "Canta."},
  Voice_6311_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6312_AwakerVoiceContent = {
    Text = "\"El Armario de la Dama\" y \"La Guía de la Mujer Trabajadora\" son excelentes lecturas... Incluso si no puedes permitirte comprarlo, simplemente admirar los hermosos vestidos es bastante agradable."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "Es extraño. Normalmente tengo dificultades para recordar cosas, pero te memoricé en solo unos días... ¿Qué? ¿Ya han pasado tres meses? Lo siento, lo olvidé otra vez."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "Saborea esto."
  },
  Voice_6314_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_6316_AwakerVoiceContent = {
    Text = "Sigue mejorando tu compostura."
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "Practica el Giro de Látigo veinte veces más."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "¿Son mis movimientos lo suficientemente precisos?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "¡Por favor, adelante!"
  },
  Voice_6319_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_6320_AwakerVoiceContent = {
    Text = "¡Apresúrate, lleva a Brown y vete!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Arrodíllate ante el trono."
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "Arrodíllate ante el trono."
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "Las diversas expresiones de los humanos frente al deseo nunca dejan de sorprenderme. Desafortunadamente, los humanos son todavía demasiado frágiles, demasiado insignificantes... Esto solo me hace sentir como si un gato estuviera rasguñando mi corazón."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "De sus recuerdos, vi muchos eventos pasados relacionados con \"Disolución\"... Pero cada vez que quería contarte, mi conciencia se interrumpía. Temo que esto también sea obra de ella."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "¿No sería bonito simplemente desvanecerse en el olvido?"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "Un sirviente calificado debe ser frágil y poco inteligente - me gustan los corderos obedientes."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "Nuestra reunión debe ser una promesa de los dioses a aquellos que sufren — tú eres la llama pálida que disipa la calamidad, y yo seré tu brazo, estando a tu lado."
  },
  Voice_6327_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6328_AwakerVoiceContent = {
    Text = "¡Eso es suficiente!"
  },
  Voice_6328_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "¿Has intentado inyectar D-Slime directamente en tu cuerpo? La goo negra se enrolla alrededor de tu corazón como una víbora, y luego... ¡boom! Tu cuerpo explota en una cálida piscina de slime. Asqueroso, pero efectivo."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Hmph, un refugio para que los débiles se acurruquen juntos."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "De vez en cuando, la chica en la motocicleta me ayuda a mantener mi extremidad prostética. Sin embargo, ¿no ha sido últimamente un poco demasiado alta la frecuencia de las revisiones de mantenimiento?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Chat·Sobre Nautila"
  },
  Voice_6331_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"nautila\""
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "¿Nuestra relación? ¿Realmente necesitas preguntar? ¡Es exactamente lo que imaginas!"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "No es mi género preferido, pero si insistes."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "Tus ojeras están empeorando... ¿Por qué trabajar tan duro? Deberías ser más como yo y aprender a disfrutar de tu tiempo libre."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6334_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Espera, sin mi permiso..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6335_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Bien... Está acercándose a su forma original."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6336_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "Este es el poder para contrarrestar la \"Corrupción Verde\"... Has tocado algo que no debías. En cuanto a mí, nunca te dejaré ir de nuevo."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6337_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Shh... El resplandor de la mañana en el valle—debe ser tu primera vez viéndolo, ¿verdad? Esta es tu recompensa por lealtad."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6338_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "Este libro, \"La Revelación de @1@2\", se te otorga. Ayuda a iluminar la mente o a caer rápidamente en un sueño"
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6339_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "El mundo mortal sigue siendo demasiado ruidoso. Si puedes encontrarme un rincón tranquilo en la academia, eso sería perfecto... No, no necesito una chimenea. Solo a través de prácticas ascéticas los dioses pueden escuchar mis oraciones..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "¿Es cera o miel goteando de mi cuerpo? ¿Por qué no pruebas un lamido y lo ves por ti mismo?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6341_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "Hola... Encantado de conocerte. Mi nombre es Aigis... ¡Por favor, solo finge que no existo!"
  },
  Voice_6342_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6343_AwakerVoiceContent = {
    Text = "Mientras siga siendo \"Ramona\", seguimos siendo socios, ¿verdad?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "Aquella dama con profundas ojeras me consultó una vez sobre \"vivir para siempre bajo el sol\"... Solo necesitaba migrar entre dos dimensiones. Sin embargo, se niega a entrar en el túnel Dimensional. Fue un verdadero dolor de cabeza."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Charlar·Sobre Bígaro"
  },
  Voice_6344_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"bígaro\""
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "¡Bienvenido a mi paraíso! ¿Estás listo para enfrentarte al látigo?"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6346_AwakerVoiceContent = {
    Text = "Dado que Él te ha reconocido, no te consideraré un enemigo."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "¿Qué quieres decir, \"lo tomé\"? ¡No me acusen falsamente! Cuando sus tornillos desaparecieron, yo estaba—Marrón, ¡para! ... Jeje, solo finge que no has visto nada, ¿de acuerdo?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Chat·Sobre Nautila"
  },
  Voice_6347_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"nautila\""
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "¡La aventura es tan emocionante como en las historias! ¿Cuál era esa historia...?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...Hic. Ah, lo siento, absorbí demasiada energía de nuevo."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "Una vez dentro de un cuerpo humano, perdí todo contacto con mi familia. Temo que los demás no escaparan de los demonios y que yo pueda ser el último de mi especie... Por favor, Guardián, sálvame. Déjame quedarme a tu lado, no me dejes en la oscuridad."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6350_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "Cuando el planeta fue destruido, abandoné mi cuerpo y transferí mi conciencia a un cuerpo humano... ¡Pero el demonio negro me persiguió incansablemente, atando mi espíritu y evitando mi escape! ¡Busca arrastrar al mundo a un abismo de oscuridad!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6351_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "Por favor, Guardián... Mientras me dejes quedarme en el localizador y no me dejes, haré cualquier cosa excepto entrar en la oscuridad y enfrentar a ese... esa cosa negra. No puedo dejar el localizador. Solo un poco más, ¡y localizaré los restos del planeta hogar! ¡Solo quedan 1.2 mil millones de cálculos!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6352_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "¿Podrías usar tu suministro compartido para conseguirme dos bolsas de suplementos de cafeína? ... No puedo dormir. ¿Por qué debería dormir? ¡Nunca duerma! Una vez que cierras los ojos, todo se convierte en oscuridad... oscuridad..."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6353_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "¡Vaya! ¡Aléjate de mí! ¡Primero, prueba que no eres un sirviente de la oscuridad! Sí, sirviente. Solo quítate la ropa y muéstrame que no tienes esa asquerosa baba negra en tu cuerpo, y luego sabré que no eres malvado..."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6354_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "¡No preguntes, no preguntes...! Sabes exactamente lo que más temo y odio: ¡la oscuridad, la oscuridad interminable!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "¿Un método para sanar Disolución? Tal cosa no existe en ningún lugar.\n¿Preguntas cómo permanezco no infectado? Hehe... mientras \"no seas visto\", eso es todo lo que se necesita."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Gracias, Maestro."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "También son felices."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Lily ha crecido."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "¿Aplástalo?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "¡¿Cómo pudiste convocarlo?! ¡Ese inútil dormilón! Perezoso y sin ambición... ¡Una vez fue alguien en quien tenía grandes esperanzas! ¡Vamos! ¡No quiero ver a este tipo!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Charlas · Sobre Tulu"
  },
  Voice_6361_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Tulu\""
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "¡Desagradable!"
  },
  Voice_6362_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "¡Así que molesto!"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "Next time, let's go see the sea together. Febvre está bien, puedo ser tu guía; o a cualquier otro lugar, incluso a los confines de la tierra, quiero ir contigo."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6364_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "El mar tiene su propio lenguaje.\n...Así, ocasionalmente puedo charlar con los pececillos del estanque sobre nuestra tierra natal. Si tienes curiosidad, puedo ayudarte a traducir."
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6365_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "Para ser salvado por ti, a menudo me siento tan feliz que me asusta... Por favor, dime que esto no es un sueño y que no desaparecerás en el mar sin dejar rastro, ¿verdad?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6366_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "¿Se puede llamar a este sentimiento \"felicidad\"? Yo... nunca me atreví a esperar esto antes."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6367_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "Mi cuerpo se siente cálido, como si estuviera suavemente envuelto por el mar. Es realmente increíble."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6368_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "¿Es ese un fragmento de Él? Impresionante, realmente posee un aura regia."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Charlas · Sobre Tulu"
  },
  Voice_6369_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Tulu\""
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "No, no continúes... Me encontrará, me encontrará!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "Esto debería mantenerme despierto."
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "Se acabó, se acabó, se acabó... Definitivamente se darán cuenta..."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "Ganamos. ¿Eres feliz? ¿Qué se siente ser \"feliz\"?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "¿Cosas que me gustan? Me gustan las canciones de cuna de Tinct... ¡Por supuesto, tu canto también es maravilloso!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "Él es un guerrero confiable. Una vez lo consideré un \"camarada\"... ¿Qué? ¿Crees que mi definición de \"camarada\" es incorrecta? Por favor, ilumíname."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Chat · Sobre Goliat"
  },
  Voice_6375_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"goliat\""
  },
  Voice_6378_AwakerVoiceContent = {
    Text = "Meteorito..."
  },
  Voice_6378_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6379_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6379_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "Un continuo aumento de poder, llenando todo el cuerpo..."
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6381_AwakerVoiceContent = {Text = "¡Vuela!"},
  Voice_6381_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6382_AwakerVoiceContent = {
    Text = "No está nada mal, eres más útil de lo que pareces."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Veinte, veintiuno, veinticuatro... Espera, ¿en qué número iba? Uno, dos, tres..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6383_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "Finalmente me di cuenta de cuántos materiales tenía antes, así puedo terminar las reparaciones más rápido—Espera, ¿de dónde vinieron estos?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6384_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Gracias a tu ayuda, la eficiencia de las reparaciones recientes ha mejorado. ¡Pronto podremos partir en una aventura!"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6385_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "Creo que estoy empezando a recordar cosas... ¿Me diste una llave inglesa número 7 ayer?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6386_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "¡Reparar, arreglar, completar! Una aventura desconocida, un mundo misterioso, ¡allí voy!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6387_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6388_AwakerVoiceContent = {Text = "¡Boom—"},
  Voice_6388_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_6389_AwakerVoiceContent = {
    Text = "No te engañes. Las cadenas mentales son aún cadenas y no pueden ser llamadas justas."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Ahora, la línea entre yo y el Despertador es aún más difusa. Será mejor que me vigiles."
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6390_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Vayamos a salvar el mundo."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6391_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "Se siente tan refrescante como leer \"El origen de las especies\" de un tirón"
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6392_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "He ganado fuerza. Déjame intentar manejar la próxima misión por mi cuenta, ¿de acuerdo?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6393_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "Además de la habilidad de combate, mi memoria y pensamiento lógico no han mejorado mucho. Todavía tengo que depender de mis propios pensamientos."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6394_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "Quiero que experimenten lo que es que les den la vuelta a la vida, perderlo todo y ser pisoteados por todos."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6395_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "La humillación que he soportado, todo lo que he perdido... les haré pagar. Les haré pagar a todos."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6396_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "Tal dulce odio, cuando se sazona con la sangre de los enemigos, es sin duda el platillo más exquisito del mundo."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6397_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "¡Ah! ¡No te acerques a mí por detrás!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "Las llamas abrasadoras arden en mi pecho... Sí, nunca he olvidado, ni puedo olvidar."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6399_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Quema, oh alma de la poesía."
  },
  Voice_6400_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6401_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6401_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6402_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6402_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6403_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6403_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6404_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6404_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "¡Cosquillea! Justo como cuando la sirvienta usa un feathero para hacer cosquillas en las plantas de mis pies. Tú *bleep* no lo hiciste a propósito, ¿verdad?"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6405_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "Que tengas dulces sueños."
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "Que tengas dulces sueños."
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "Concede serenidad...!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "Muévete con elegancia."
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "¿Puedes oírme? Mi voz."
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "¿Puedes oírme? Mi voz."
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "Está lloviendo. La lluvia lava todo: comida en mal estado, suciedad obstinada y personas como yo... los desechables."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "La marea furiosa de venganza nunca cesa."
  },
  Voice_6413_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6414_AwakerVoiceContent = {
    Text = "¡Sangre, baña todo mi cuerpo!"
  },
  Voice_6414_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6415_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_6415_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6416_AwakerVoiceContent = {
    Text = "¡Mira hacia aquí!"
  },
  Voice_6416_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6417_AwakerVoiceContent = {
    Text = "No tengo miedo."
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6418_AwakerVoiceContent = {Text = "¡Cuidado!"},
  Voice_6418_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "Un mundo intocado por la tristeza, inalterado por el duelo, libre de dolor y no marcado por sufrimientos oscuros—quizás una ilusión inalcanzable, pero es el ideal que he perseguido toda mi vida."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "¡Mira la magnificencia del Reino Eterno!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "¡Mira la magnificencia del Reino Eterno!"
  },
  Voice_6421_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6422_AwakerVoiceContent = {
    Text = "¿Ofreciendo tributos obedientemente otra vez? Buen chico."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6422_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6423_AwakerVoiceContent = {Text = "¿Duele?"},
  Voice_6423_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_6424_AwakerVoiceContent = {
    Text = "Mantente concentrado."
  },
  Voice_6424_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6425_AwakerVoiceContent = {
    Text = "El paso de los milenios me ha vuelto algo descuidado."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "Ese día, las llamas de la envidia se extendieron como un mar de rosas rojas en plena floración... Todos los poemas se convirtieron en cenizas destrozadas entre las lenguas carmesí de fuego."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6426_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "¡He aprendido una nueva técnica!"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "Ten cuidado."
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "¡La varita quiere danzar!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Ah, ¡esta familiar sensación de vacío!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "El movimiento de las articulaciones se ha vuelto más suave."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "Ese ominoso negro se asemeja a mi espada-escudo amorfa... ¡Ah! No te preocupes, mi lord, ¡mi espada guardiana nunca te hará daño!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6433_AwakerVoiceContent = {Text = "Vamos."},
  Voice_6433_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "Apenas lo logré."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "Haré todo lo posible."
  },
  Voice_6435_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6436_AwakerVoiceContent = {
    Text = "¿Jugar aquí hoy?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "El sótano está lleno de agua, suave y fría. Así, mi cuerpo siempre está envuelto en humedad... Como si fuera el único ser físico entre cielo y tierra. A veces, realmente deseo disolverme en el agua.\nPero entonces cesaría de existir y nunca te encontraría."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6437_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "Aquí hay un secreto... en realidad odio la sangre. Odio su color, su sabor. Pero no puedo vivir sin ella.\n...Trago la sangre, luego la vomito toda... me desagrada a mí mismo."
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6438_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "Hmm! Tu sangre... sabe a hidromiel. Supongo que soy el único que conoce este secreto, ¿verdad?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6439_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "En mis fantasías, un valiente caballero me arrastra fuera de la oscuridad y luego me ata con cadenas. Puede golpearme, maldecirme, hacer cualquier cosa conmigo—el dolor es mi prueba de vida.\n¿Estarías dispuesto a ser mi caballero?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6440_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "La sangre fluye como un río. Soy tuyo—nunca me he sentido tan intensamente."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6441_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "¡Esta es la voluntad de las Tres Diosas de la Venganza!"
  },
  Voice_6442_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6443_AwakerVoiceContent = {
    Text = "Espadas Desenvainadas"
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6444_AwakerVoiceContent = {Text = "¡No!"},
  Voice_6444_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "¡Tan sucio! ¡Tan sucio!"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "...Aigis, ¡lo veo!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...Aigis, ¡lo veo!"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "Propinas, por supuesto, propinas. ¡Mira a esos meseros desorientados en la cafetería de la escuela! ¡Ni siquiera preparan las tumbonas con antelación y aún así esperan un pago extra? ¡Sueña!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6449_AwakerVoiceContent = {Text = "Negro."},
  Voice_6449_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "¡Déjame salir!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Habilidad·I·Manía"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "No hagas esto..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Habilidad·Uno·Depresión"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "No hay necesidad de cortesía, Mensajero Pálido. No debería haber barreras entre nosotros, ya que todos somos Reliquias de Dios, caminando juntos por este camino fangoso y difícil."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6452_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "Por supuesto, no los temo, esas pobres almas atormentadas por la Maldición del Derretimiento. Solo siento tristeza por ellos. Sé que no puedo soportar su sufrimiento, pero puedo darles todo lo que tengo si les brinda algo de consuelo."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6453_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "¿Rezarás conmigo, La Pálida Llama? Reza por aquellos que murieron en nuestra batalla hoy. Aunque maldecidos con disolución y locura, todavía son reliquias del dios de la bondad, nuestros hermanos y hermanas. Que encuentren la paz que merecen."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6454_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Aunque la llama roja me hace sentir incómodo, volvería a ponerme en la plataforma ardiente por ti una vez más. No te preocupes por ello, mi llama pálida. Mi sacrificio es insignificante en comparación con las bendiciones que traes."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6455_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "¿Arrepentimiento? No, por supuesto que no. Mi muerte alivió su sufrimiento y compró más tiempo—eso es suficiente. Pero... has sido honesto conmigo, así que no lo ocultaré: la pira de ese día dejó cicatrices en mi corazón."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6456_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "¿Puedes hacerme una promesa? Hmm... Prometamos que, pase lo que pase, siempre recordarás \"Ramona\", ¿vale?"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6457_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "No me arrepiento de la elección de convertirme en lo que soy; si tuviera la oportunidad de nuevo, todavía lo haría. Pero, Guardián, tengo mucho miedo... miedo de que \"Ramona\" no deje rastro en este mundo."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6458_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "No te preocupes, el parche ocular no afecta mi visión. Si acaso, me ayuda a evitar ver todo."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6459_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "¿Mi expresión parece desconocida? He estado tratando de controlarla... Parece que su presencia se está volviendo más fuerte."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6460_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Demasiados misterios por resolver, demasiadas personas por salvar. No sé cuánto más tiempo podré seguir, y no puedo proteger a todos... Es realmente difícil."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6461_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "¿Aún quieres apostar por mí? Parece que vivir como uno quiere no es tan fácil. No te preocupes, me tomaré un descanso mientras resuelvo tus problemas."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6462_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "En este momento, no tenemos más remedio que sacar nuestras verdaderas habilidades, ¿verdad? ¿Dónde está la escena del crimen? ¡Incluso si tengo que agotar toda mi suerte, definitivamente traeré al sospechoso de vuelta antes de la fecha límite!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6463_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Suspira, he recibido tantos favores de ti, ya no puedo mantener este secreto: en realidad, podría ser la persona más desafortunada de este mundo"
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6464_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "Parece que no has tomado mis palabras en serio... No importa, aún te ayudaré a desgarrar a los enemigos. Al fin y al cabo, estas garras y colmillos fueron adquiridos por casualidad, ¿verdad?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6465_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "Mi suerte podría no transferirse a mis compañeros. Debes haber oído el dicho, ¿verdad? \"La pata de conejo no es afortunada para el conejo.\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6466_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "¿Deseas imprimir la marca de Yu en tu alma?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "¿Deseas tanto mi poder?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "No te dejes engañar por mi apariencia; una vez fui una dama... Podía bordar, leer a Tennyson... Oh, y podía cantar: Ella fluye como un río interminable por mis venas~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Pikman y yo estamos trabajando en una fascinante instalación de arte, explorando la reconstrucción del representacionismo abstracto deconstruyendo el primitivismo visual... Eh, ¿por qué se desmayó Aurita?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Chat · Sobre Aurita"
  },
  Voice_6470_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"aurita\""
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "¿Quieres que sonría?\nLily, ¿estoy sonriendo?"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre las Sonrisas"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "Qué sorpresa, he ganado una amistad igual.\nSin embargo... solicito retener el derecho a mandarte, como un poco de diversión entre nosotros. Ven a mi habitación esta noche; aún tengo mucho que aprender sobre las emociones humanas..."
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6472_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "¿Sabes qué te hace el más lindo? Es cuando me dices \"no\". Tu nariz se arruga, tus cejas se levantan un poco... Sí, justo como ahora."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6473_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "Amo a mis secuaces. Estos encantadores pequeños, temblando de Disolución y escondiéndose detrás de mí, son tan entrañables. Las lágrimas de una belleza siempre son cautivadoras. ¿Y tú? ¿Tienes miedo de la Disolución?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6474_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Guardián, ¿tienes a alguien que no te guste? Como un favor, puedo darle una lección. En una semana, será una persona cambiada, lamiendo obedientemente tus pies."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6475_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "Hmm... Aunque eres soso, no eres del todo desagradable. A partir de mañana, me servirás.\n¿No quieres...? No es una petición; es una orden."
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6476_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "Ha pasado mucho tiempo desde que me sentí así. Subiré al escenario en perfecto estado y entregaré una ola de sonido que abarcará el universo solo para ti."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6477_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "Necesitas saber, esto es inútil."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6478_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "Después de recoger la flor de la victoria, me gustaría reclamar una pequeña recompensa..."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6480_AwakerVoiceContent = {Text = "¡Ah!"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Golpe·Depresión·III"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "La nave aérea estaba abarrotada y claustrofóbica, como un ataúd de metal flotando en el espacio. Esperé a mi Estrella de la Mañana hasta que apareciste."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6481_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "¡¿Cómo podría ser esto?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Golpe·Frenesí·I"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Golpe·Depresión·I"
  },
  Voice_6484_AwakerVoiceContent = {Text = "¡Ay..."},
  Voice_6484_AwakerVoiceTitle = {
    Text = "Golpe·Depresión·II"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "¡Castigo Divino!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "¡Castigo Divino!"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6487_AwakerVoiceContent = {Text = "Aburrido."},
  Voice_6487_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6488_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6488_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "Aún sosteniéndome."
  },
  Voice_6489_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6490_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6490_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6491_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6491_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6492_AwakerVoiceContent = {
    Text = "Que los irreverentes se disuelvan en la abrasadora tranquilidad."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "¡Ten cuidado! Si te adentras en otro espacio dimensional, ¡podrías no recuperar tu mano!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "Un grupo de perdedores. Si no quieres terminar como carne picada, será mejor que tengas cuidado la próxima vez."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Oh querido, ¿estás siendo cariñoso conmigo?\nEsto es problemático. Si esto continúa, no podré esperar a que el Guardián madure completamente..."
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "¡Sumérgete en las profundidades del libre albedrío!"
  },
  Voice_6496_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6497_AwakerVoiceContent = {
    Text = "Odio... Definitivamente son aquellos que se rinden a mitad de camino. Solo pensar en ellos me hace querer vomitar la cena de anoche."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "¡Mira tu imagen, oh cráneo eterno!"
  },
  Voice_6498_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6499_AwakerVoiceContent = {
    Text = "¡Mira tu imagen, oh cráneo eterno!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6500_AwakerVoiceContent = {Text = "¡Hah!"},
  Voice_6500_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6501_AwakerVoiceContent = {Text = "¡Hah!"},
  Voice_6501_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6502_AwakerVoiceContent = {
    Text = "¿Confías tanto en mí?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6502_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6503_AwakerVoiceContent = {Text = "Vuelve."},
  Voice_6503_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6504_AwakerVoiceContent = {Text = "¡Bien!"},
  Voice_6504_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "Por supuesto que sé, ese es otro aspecto de mí. Pero, ¿por qué ella resiste? ¿No es aceptar el destino del elegido y obtener lo que se reza al alcance?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Charlas Ociosas: Sobre \"Murphy\""
  },
  Voice_6505_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Murphy\""
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "Hola, mi nombre es Daffodil. Una vez hice un intercambio con un invitado que solicitó que te asistiera. Así que, déjame escuchar lo que necesitas.\nOh querido... lo que deseas viene con un precio bastante alto, ¿no?"
  },
  Voice_6506_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6507_AwakerVoiceContent = {
    Text = "*Silencio* ¿Qué estás haciendo! ¡Créeme o no, te cortaré la mano!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6508_AwakerVoiceContent = {Text = "¡Hahaha!"},
  Voice_6508_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6509_AwakerVoiceContent = {Text = "¡Hahaha!"},
  Voice_6509_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "Las espinas de rosa pican dedos, fluyendo hacia la poesía."
  },
  Voice_6510_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6511_AwakerVoiceContent = {
    Text = "Doblando bajo esta profunda tinta de tristeza, conviértete en una canción de duelo..."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6512_AwakerVoiceContent = {
    Text = "¡Mira esto...!"
  },
  Voice_6512_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6513_AwakerVoiceContent = {Text = "Hmm...!"},
  Voice_6513_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6514_AwakerVoiceContent = {
    Text = "¡Llegada de Clados!"
  },
  Voice_6514_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6515_AwakerVoiceContent = {Text = "Dámelo."},
  Voice_6515_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_6516_AwakerVoiceContent = {
    Text = "...Mi nombre, eh, no puedo recordar.\nOh, cierto, \"24\", así es como me llaman... ¡No! ¡No salgas! No puedes, no ahora."
  },
  Voice_6516_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6517_AwakerVoiceContent = {
    Text = "El flujo de las marcas de tinta..."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6518_AwakerVoiceContent = {
    Text = "Emergiendo..."
  },
  Voice_6518_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "No merezco el título \"Voz Celestial\"... Mientras disfrutes de mi canto, eso es lo que importa."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Chit-Chat: Sobre Cantar"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "La ropa sucia debe cambiarse antes del próximo salón."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "Me está alcanzando, la eterna oscuridad... Nadie puede escapar."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Cada vez que te veo, pienso en las cadenas invisibles que has puesto sobre mí. Permitir que vivas es mi mayor acto de tolerancia."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "No importa cuántas veces empecemos de nuevo, caminaré contigo."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "Que el amor de Dios caliente tu alma."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "Disfruto de vagar sin rumbo. Pantanos, cementerios, hospitales, castillos abandonados... En estos lugares, siempre encuentro deleites inesperados."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Siéntete honrado, porque las puertas del Reino Eterno están aquí."
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Hehe—¡tan cosquilloso! ¡Aurita quiere rascar de vuelta!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "\"La Muerte del Cisne,\" una actuación en la que la bailarina utiliza el lenguaje corporal para transmitir el anhelo y la lucha de la vida. ¿No es esa figura torcida en las llamas la misma?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Corta, corta, desgarra. Tal como me hicieron en el pasado... jeje... ¡jejeje!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "Más te vale no acercarte demasiado a la Señorita Thais... No, no estoy celoso. Solo tengo miedo de que alguien caiga en las trampas de una mujer."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Charlas: Sobre Thais"
  },
  Voice_6530_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"thais\""
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "...Muchas gracias."
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6531_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Muy bien... tienes buen ojo para reconocer personas."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6532_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "¡La ciudad natal de Karen es hermosa! Es una ciudad de piedra en un lago.\nCada luna llena, bailamos silenciosamente en las llamas, adorando...\nHonestamente, cuando Karen llegó a la universidad, extrañaba su hogar cada noche y lloraba en la cama. Pero ahora, Karen tiene un nuevo hogar y familia. ¡Todo es mejor!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6533_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Oh~ ¿Todavía no estás satisfecho? Ven, déjame entrenarte rápidamente~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Músculos débiles, cara demacrada—solo esos ojos muertos tienen algún valor. Perfecto para alimentar arañas."
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "Gracias... por todo lo que has hecho por Aigis. Aigis hará su mejor esfuerzo... para no decepcionarte!"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(Grito de dolor)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6538_AwakerVoiceContent = {Text = "¡No!"},
  Voice_6538_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6539_AwakerVoiceContent = {
    Text = "Ahórrame..."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(Grito de dolor)"
  },
  Voice_6540_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6541_AwakerVoiceContent = {
    Text = "La esgrima de Miss Ramona es bastante diferente de las técnicas que he dominado. Si mi lord lo permite, me gustaría cruzar espadas con ella... ¡Por supuesto! ¡Es solo para mejorarme a mí misma!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6541_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "¿Preguntas por qué no juego con los otros niños? Es difícil de admitir... En mi vida anterior, tuve pocas oportunidades de jugar. Mi único compañero era la princesa a la que servía... ¡Ah! Mencionar a otro monarca frente a mi señor, por favor disculpa mi desliz."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6542_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "Eres reconocido por la Universidad Mythag como un Guardián, así que te concederé los permisos de acceso correspondientes."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Charlas Ociosas · Sobre \"Protagonista\""
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "¿Estás interesado en las \"Siete Habilidades Caballerescas\" que he aprendido? ¡Eso es maravilloso! Ah... um... por favor, perdona mi rudeza anterior. Lo que quería decir es que, si deseas practicar tiro con arco montado, ¡me sentiría honrado de ser tu compañero de entrenamiento!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6544_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "No soy un caballero digno. Ya sea por la vil plaga o por los enemigos invasores, fallé en proteger a mi antiguo señor. Ahora, la confianza que pones en alguien como yo es un inmenso honor... Juro por mi honor caballeresco y esta vida insignificante que siempre guardaré tu camino hacia adelante."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6545_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "No hagas daño."
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6547_AwakerVoiceContent = {Text = "Vamos~"},
  Voice_6547_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6548_AwakerVoiceContent = {Text = "¡Toca!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6549_AwakerVoiceContent = {Text = "No mates."},
  Voice_6549_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6550_AwakerVoiceContent = {
    Text = "Entonces ~ cómodo!"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "Ahora, somos como agua y aceite que no se mezclan."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "No tengo favoritos en particular. Si tuviera que decir, la sensación de salir en misiones es bastante agradable."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "¿Por qué, por qué me encierras aquí? Haha... No dejaré que tengas éxito. ¡Desgarraré estas ataduras, esta prisión... en fragmentos!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Proteger a todos."
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "Ustedes, ¿no se cansan de ver el espectáculo de magia? ¡Quédense quietos, está bien? Si vuelven a correr al escenario, ¡los lanzarė a otra dimensión!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre los Niños"
  },
  Voice_6555_UnlockDesc = {
    Text = "Desbloqueado tras adquirir cualquiera de los Despertar \"Aigis,\" \"Jenkin,\" \"Lily,\" \"Murphy,\" \"Karen,\" o \"Aurita\""
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "Acepto con gratitud tu regalo."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "¿Qué tipo de regalo de regreso podría igualar tu dedicación?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "Qué esplendor..."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Se detectó una alta corriente, iniciando mantenimiento... Corrección, ¿por qué no hay sobrecalentamiento?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6559_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "Desde el último ritual de Iluminar, he estado viendo visiones fragmentadas mientras estoy en el Estado de letargo. En ellas, poseo un cuerpo Caro como el tuyo, y lágrimas caen de mis ojos. ¿Es esto un sueño?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6560_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "Después de cada ritual, se detecta un alto nivel de calor en el área del pecho, pero no hay componentes relacionados con la energía presentes. ¿Sabes por qué?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6561_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "Lo vi. Todo debería <Del:perish in the eternal current>. Lo siento, lo siento, el módulo parece—Advertencia, advertencia. La actividad de conciencia no-Erica está aumentando. Destruir, destruir, des... Hola, ¿cómo puedo asistirte?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6562_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "Después de un análisis cuidadoso, deduje que lo que vi en mi estado de letargo no era un sueño en el sentido tradicional, sino más bien mi <Del:pobre Cuerpo Caro que debería ser destruido> Memoria. En cuanto al calor ardiente similar a la sobrecarga, puede ser la emoción conocida como \"Renuencia\"."
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6563_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "Si quieres ver la función, ¡siéntate correctamente en la audiencia!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6564_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "Las llamas del odio arden con fuerza, nunca se apagarán."
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "La voluntad con la que me he fusionado es ruidosa; cuanto más asciendo, más clara se vuelve la voz de \"Él\"... como los gansos en Hyde Park, bastante ruidosos."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6567_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "Usaré este poder para devorar al traidor."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "...Muchas gracias."
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "¿Guardián? Ridículo. Es hora de despertar de este sueño poco realista."
  },
  Voice_6570_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6571_AwakerVoiceContent = {
    Text = "La sangre de la venganza está hirviendo..."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "¡Muévete, esbirros!"
  },
  Voice_6572_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6573_AwakerVoiceContent = {
    Text = "¡No te ahogues!"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6574_AwakerVoiceContent = {Text = "¡Whoosh!"},
  Voice_6574_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "Tiré las trampas para ratones en la puerta trasera de la cafetería. Son demasiado peligrosas. ¿Y si ese torpe de Brown las pisa!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "Esto se siente tan extraño... ¿Me estoy muriendo? ¡No, sálvame! ¡No!!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6576_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "Quiero una lámpara que nunca se apague. Ella realmente dijo intercambiarla por un espécimen de una \"hidra voladora sin alas.\" ¿Dónde puedo encontrar tal especie tan extraña?"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Narcisos"
  },
  Voice_6579_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Daffodil\""
  },
  Voice_6582_AwakerVoiceContent = {Text = "Peligro."},
  Voice_6582_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6583_AwakerVoiceContent = {
    Text = "Advertencia."
  },
  Voice_6583_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6584_AwakerVoiceContent = {Text = "Golpe."},
  Voice_6584_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6585_AwakerVoiceContent = {
    Text = "Un tesoro que brilla como envolturas de caramelo... Aigis lo atesorará con cariño."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Daño recibido."
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "Mi tienda existe en cualquier dimensión, cualquier ubicación en el universo, y por supuesto, puede estar aquí. Además, me gustan esos chicos descuidados en Mitag."
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Odio... Los pimientos verdes saben terribles."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "Nuestra relación es como la de una vela y un barco. Sin el barco, la vela no debería existir; sin la vela, el barco no puede viajar lejos. ¿No es así?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "La devota bailarina está muerta, y el blasfemo del arte también está muerto, ambos perecieron en llamas llenas del olor de la brea. La muerte no es el final, sino el comienzo, pues solo los humanos mueren; la danza y el arte son eternos."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6590_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Gracias por tu comprensión. Quizás ahora sea el momento de reconciliarme con mi yo del pasado... Creo que estoy haciendo lo correcto y no he deshonrado el legado de mi familia en la danza. Voy a pisar el escenario que has preparado y brillar como deseas."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6591_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "Ten cuidado."
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "¿Quieres que suba al escenario y brille?\nEso es imposible ahora. Estos ojos han sido consumidos por el odio. Todo lo que puedo hacer es quemarlo todo hasta las cenizas."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6593_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "¿Entiendes esa sensación? Girando, girando, girando, nunca deteniéndome. Las rodillas estiradas al límite, los dedos sangrando negro, empapando las zapatillas de ballet, y aun así nunca deteniéndome. Todo porque me niego a aceptar el destino de ser un juguete..."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6594_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "No quemé a los hábiles bailarines de la corte, a los elegantes maestros de ballet, ni a los nobles que aprecian la sublimidad y la belleza. Quemé a los necios inútiles que venden sus cuerpos, a los aduladores que desprecian a los demás y a los seres sucios perdidos en la lujuria... ¿Me entiendes, verdad?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6595_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "No me gustan esas personas con tentáculos viscosos, y no me gusta el océano... ¡No me mires así! ¡No soy un niño que le teme a sus padres!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6596_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "Tu generosidad es muy apreciada..."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6598_AwakerVoiceContent = {Text = "¡Vanish!"},
  Voice_6598_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6599_AwakerVoiceContent = {Text = "¡Vanish!"},
  Voice_6599_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "¡Apresúrate, lleva a Brown y vete!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6601_AwakerVoiceContent = {Text = "No..."},
  Voice_6601_AwakerVoiceTitle = {
    Text = "Defensa·Depresión"
  },
  Voice_6602_AwakerVoiceContent = {
    Text = "¡Lárgate!"
  },
  Voice_6602_AwakerVoiceTitle = {
    Text = "Defensa·Manía"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "¿Quién es Leigh? Oh, la mujer que me suplicó que la golpeara. Ja, interesante... Este lugar no es tan aburrido después de todo."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Chat·Sobre Leigh"
  },
  Voice_6603_UnlockDesc = {
    Text = "Desbloquea después de obtener el despertador \"Leigh\""
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "El atardecer en la pequeña colina a menudo me recuerda mis días en Cleveland... Cleveland, no puedo creer que todavía recuerde ese nombre, el lugar que me dejó estas cicatrices."
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Crepúsculo"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "Ah... las estrellas... han caído..."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Sin duda, los humanos. ¿Hay alguna criatura más sucia que los humanos?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6607_AwakerVoiceContent = {
    Text = "¡Es ahora!"
  },
  Voice_6607_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6608_AwakerVoiceContent = {Text = "¡Hola!"},
  Voice_6608_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_6609_AwakerVoiceContent = {
    Text = "¿Disolución? Hmm... ¡Sí! ¡El helado se derrite! Pero si lo compartimos, ¡podemos comerlo antes de que se convierta completamente en crema!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "Usaré esta fuerza para protegerte."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6610_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Oh querido, ¡no hay devoluciones en los objetos vendidos aquí! ¿Necesitas un submarino para sumergirte en el Aequor, verdad?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Chat · Sobre Caecus"
  },
  Voice_6611_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"caecus\""
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "¡El mejor escenario! Tanto los profesores como los estudiantes de la Universidad Mythag pueden entender que mi actuación es verdadera magia. ¡Esto debe ser lo que llaman el espíritu afín de un mago, verdad?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "El orden del universo se altera aquí; ¡el futuro de la destrucción es la creencia del mago!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6613_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "¿Puede Aigis quedarse aquí un poco más? Me quedaré en silencio, no haré ruido y trataré de no molestarte..."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6614_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Revela la esencia del mundo con intelecto humano...!"
  },
  Voice_6615_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6616_AwakerVoiceContent = {
    Text = "En mis sueños, a menudo escucho el sonido de la marea, que se va desvaneciendo. Sé que podría quedarme aquí para siempre, Humano."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Chat · Sobre Aequor"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "Más recuerdos, más emociones, más sueños—"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6617_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "¡Está empezando a cambiar!"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "¡No parpadees!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "Cuando Él nace... no tendré que soportar más esta humillación."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "¡Elígeme, ¡elígeme! ¡Donde hay una fiesta, está Karen!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Hmm? ¿Interesado en mí? Supongo... ¿estás listo para pagar el precio?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "¡Sin piedad, sin piedad...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "Aún cantando los colores de las estrellas."
  },
  Voice_6624_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6625_AwakerVoiceContent = {
    Text = "¡Cántico, cántico!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "¡Ama a Mamá!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6627_AwakerVoiceContent = {Text = "Vamos."},
  Voice_6627_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6628_AwakerVoiceContent = {
    Text = "Ten cuidado."
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "Los Despertadores pueden comer por curiosidad, pero la comida no es esencial para nuestra existencia. Así que no hay necesidad de llamarme para cada té de la tarde. La ingesta de azúcar solo acelera el desgaste de las articulaciones de este cuerpo."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Charlar: En la Merienda"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "Por favor, perdonen a mi maestro. ¡Karen... hagan lo que quieran con Karen!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "¿Son todos estos comestibles para Lily?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6633_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "¿Molesto? ¿Puedo decirlo? Aigis odia sentirse siempre impotente... Pero si digo eso, Jenkin se enojará mucho..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Convierte en cenizas."
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "Convierte en cenizas."
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "Bien hecho, Guardián. Entonces, ¿a quién quieres que mate esta vez?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6637_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "La disolución es la razón por la cual se fundó esta academia y por la que nos conocimos. Para salvar la chispa de la humanidad de la disolución, hagamos nuestro mejor esfuerzo, compañero."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "Puedo sentir la hostilidad de la dama; debe ser mi amor por ti lo que ha desatado su celos... Mira, incluso la boca de esa ballena de gran envergadura está abierta de envidia."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Chat·Sobre Lotan"
  },
  Voice_6639_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"lotan\""
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "¡Maestro, Maestro! ¡Karen vio un increíble broche de cameo en Harold’s hoy! ¿Podrías comprarlo para Karen? ¡Es mi pedido de toda la vida!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "Serviré como tu luz guía en la oscuridad, pero este período no es eterno."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Madre, duele... Madre..."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "¡Ríndete! ¡La victoria es mía!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "¡Ríndete! ¡La victoria es mía!"
  },
  Voice_6644_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6645_AwakerVoiceContent = {
    Text = "Disolución... Mi capacidad cerebral es limitada; no puedo comprender enfermedades tan complejas... ¡Si necesitas reparar alguna maquinaria, ven a buscarme!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "¡Oh no! ¡Aurita ha sido encontrada! Como penalización por perder, puedes hacerle una solicitud a Aurita—¡solo por favor no la hagas ir a clase, por favor!"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "Abriendo el camino para Su regreso..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "Un día, el Tío Ornn me dará la bienvenida de vuelta a mi hogar submarino. Hasta entonces, puedo ser amigo tuyo de manera reticente."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6648_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"Nuestra familia lleva una gran línea de sangre; el elegido disfrutará de la paz eterna en el Aequor.\"\nNunca esperaba sentir esta paz después de dejar el mar y venir a la academia. Eres diferente de aquellos que me acosan, así que no permitiré que otros te acosen tampoco."
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6649_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "¡Material personalizado super resistente!"
  },
  Voice_6650_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6651_AwakerVoiceContent = {
    Text = "Estar atrapado en esta concha impregnada de elementos humanos me enferma. Finalmente me libré del pasado, y ahora tengo que recordarlo de nuevo..."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6651_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "Sé, el heredero de la gran línea de sangre una vez más se ha convertido en un lacayo de los humanos. Pero no pienses que puedes darme órdenes como te plazca."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6652_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Hmph, tú, frágil humano, tienes cierto talento en el mando, pero este cuerpo inferior limita mi pleno potencial."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6653_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "Mi cuerpo se está calentando."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "¡Escapar... Debo huir! ¡Necesito alejarme de aquí!"
  },
  Voice_6655_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6656_AwakerVoiceContent = {
    Text = "¡Escapar... Debo huir! ¡Necesito alejarme de aquí!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "Gracias por tus esfuerzos. Permíteme recompensarte en consecuencia."
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "No hay problema."
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "(gruñido de dolor)"
  },
  Voice_6659_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6660_AwakerVoiceContent = {
    Text = "Humano, aunque eres frágil, tu convicción me ha conmovido. Estoy dispuesto a convertirme en tu arma. ¡Provocamos un poco de caos juntos!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6660_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "Este es mi salón."
  },
  Voice_6662_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6664_AwakerVoiceContent = {
    Text = "La Academia de la Igualdad... Me pregunto qué sueños tontos albergas. Incluso si no has cometido ninguna falta, aún te pisotearán. Conozco ese sentimiento."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "Esta es la fuente de toda impureza..."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Exaltar · Depresió"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "Fui castigado por no proteger a la tripulación. Dijeron que, debido a mi negligencia, los miembros de la tripulación desaparecidos nunca se reunirían con sus familias... ¿Es esto lo que es la Disolución?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Más cerca de mi Señor..."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "¿Por qué? ¿Por qué no... despiertas?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "Soy Horla de Cité, seudónimo... Hice una promesa de no revelarlo a nadie. Mis disculpas, pero por favor simplemente llámame Horla."
  },
  Voice_6669_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6670_AwakerVoiceContent = {
    Text = "Me opongo a todos los actos de injusticia, siendo la traición la peor. En el ejército, si no puedes o no te atreves a confiar en tus camaradas para proteger tu espalda, toda la unidad se desmoronará."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "¿Por qué apareces tan oscuro, y aún así tan radiante? ... No, no importa, simplemente ignora mis divagaciones."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_6672_AwakerVoiceContent = {Text = "(Gemido)"},
  Voice_6672_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "(Traqueo de gemido)"
  },
  Voice_6673_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6674_AwakerVoiceContent = {Text = "¿Qué?!"},
  Voice_6674_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "Amo la vida, y amo la luz. Quiero que el Desmayo emerja de su caparazón apartado y experimente el mundo con sus propios ojos y oídos."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "¡No puedes verme!"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "¿Necesita continuar el trabajo de mantenimiento?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "El mantenimiento de las partes ha sido completado."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "Las personas pueden traicionar, pero las herramientas nunca lo harán. Si se utilizan correctamente, la disolución también puede convertirse en una herramienta de venganza."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "Después de un milenio de espera, el momento finalmente ha llegado... ¡Yo soy el verdadero gobernante de los Perishtites!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_6680_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "¿Fue un híbrido de Aequor el que acabamos de pasar? Hmm... mira esa espalda recta. Esta noche, lo veré arrastrarse."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Chat · Sobre Caecus"
  },
  Voice_6681_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"caecus\""
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "El poder está regresando gradualmente a mis manos... ¡El siguiente paso es apoderarme del poder que me pertenece por derecho!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6682_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "No está nada mal. Estamos un paso más cerca de despojar a esa mujer de su velo hipócrita."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_6683_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Cálmate, cálmate, cálmate..."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "No hay necesidad de preocuparse. Mi umbral de dolor puede estar más allá de tu imaginación."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6685_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "Si me preguntas, los bellos tontos son los mejores. Desafortunadamente, hay demasiadas mentes inteligentes pero inútiles por aquí."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Impulsado por la fusión nuclear de una gigante roja, suplementada por la energía de una estrella en colapso, podrías iniciar una máquina de movimiento perpetuo y encender una lámpara eterna... ¿Eh? ¿Dices que no hay forma de construir una máquina de movimiento perpetuo aquí, y que no hay una gigante roja? Hmm..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "La sangre del enemigo aún no se ha drenado por completo."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "¡Dáselos todos... a mí!"
  },
  Voice_6689_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6690_AwakerVoiceContent = {
    Text = "¡Dáselos todos... a mí!"
  },
  Voice_6690_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6691_AwakerVoiceContent = {
    Text = "Es hora de ir al campo de batalla."
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6692_AwakerVoiceContent = {Text = "¡Es hora!"},
  Voice_6692_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "Cuando duermo, los sueños desbordantes causan agitación espiritual. Así que, no te acerques a mí mientras estoy dormido, y no me despiertes sin motivo."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre el Sueño"
  },
  Voice_6694_AwakerVoiceContent = {Text = "¡Es hora!"},
  Voice_6694_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "Aunque Herbert es una persona aterradora, sus gatos son muy gentiles... No, para ser precisos, hay dos gatos, ¿verdad?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Charla Ociosa · Sobre Herbert"
  },
  Voice_6695_UnlockDesc = {
    Text = "Desbloqueado tras completar \"Investigación Operación\" Capítulo 2"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "Esa mujer, Murphy, se viste demasiado llamativa... No puede ser, ¡Karen no puede perder ante ella!\nO tal vez, simplemente matarla..."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre Murphy"
  },
  Voice_6696_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Murphy\""
  },
  Voice_6697_AwakerVoiceContent = {Text = "¡Ah~"},
  Voice_6697_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6698_AwakerVoiceContent = {
    Text = "¿Te sientes cómodo?"
  },
  Voice_6698_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6699_AwakerVoiceContent = {
    Text = "Cuando nos asociamos con la Universidad Mythag, se acordó claramente que no me enviarían a la batalla..."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6699_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "No te dejes llevar. A veces, la línea entre lo noble y lo vil es solo un paso."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6700_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Faros te saluda. Invocarme aquí debe significar que estás listo para zarpar."
  },
  Voice_6701_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_6702_AwakerVoiceContent = {
    Text = "¡Yahoo—estoy tan cansado, ¿puedo ir a jugar ahora!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "Ah... Su brillantez es tan intensa y deslumbrante, imposible de ignorar. Fue un celo tonto el que nubló mis sentidos... No, no puedo justificar mi estupidez."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Charlas · Sobre Tulu"
  },
  Voice_6703_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Tulu\""
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "Las estrellas en el sueño, yendo hacia donde deberían, apuntan hacia el reino de Dios!"
  },
  Voice_6705_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6706_AwakerVoiceContent = {
    Text = "¿No crees que es fascinante empujar todo hacia su fin y detener las leyes del mundo?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6707_AwakerVoiceContent = {Text = "¡Bebe!"},
  Voice_6707_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6708_AwakerVoiceContent = {
    Text = "¡Doloroso!"
  },
  Voice_6708_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_6709_AwakerVoiceContent = {
    Text = "Ingresa el comando de batalla."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "Durante mis días de vagar entre las estrellas, soñé con este momento innumerables veces... Gracias por reunirme con Tinct."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Chit-chat·Sobre Tinctura"
  },
  Voice_6710_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"tintura\""
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "La Universidad Mitag es un gran lugar, especialmente con el casino subterráneo que abre cada semana...\n¿Eh, no lo sabías? Ups, ¿dejé escapar el secreto...?"
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "\"Resistir la crisis de Disolución,\" ja, la autosatisfacción humana es realmente ridícula."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Chat·Sobre la Universidad Mythag"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "Después de todo, los humanos son solo criaturas superficiales. Unas pocas palabras, una insinuación, y comienzan a pelear entre sí... Suspiro, este nivel de conflicto es apenas suficiente para inspirar."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Charla Ociosa·Sobre los Humanos"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Quizás fui miope al considerarte un humano ordinario, sacando conclusiones demasiado pronto. Tengo curiosidad—¿cómo mantiene un incrédulo como tú su firmeza? Esta no es una pregunta de la Madre del Mar, sino la indagación de Miria. ¿Puedes... responderla por mí?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6714_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "¡Tú tan único, no te cansarás de este mundo superficial y turbulento? Realmente creo que el reino eterno es donde perteneces. Caminarás sobre la tierra de los dioses, te bañarás en la piscina sagrada y echarás raíces en suelo fértil... Únete a mí en mi sagrado viaje y transcendamos juntos el plano mortal. Luego, codo a codo, nos quedaremos junto al Trono, compartiendo la alegría de reconstruir el Reino Divino..."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_6715_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "Todos somos meros mortales arrastrándonos por el polvo, pero el Sabio es diferente. Él es el Enviado, una encarnación divina. Su consejo resuena con las palabras de los dioses, guiando a la civilización hacia la inmortalidad... No espero que comprendas tu fe en él ahora, pero algún día, te arrodillarás ante su Trono."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6716_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "Los Elegidos son verdaderamente bendecidos, ¿no lo crees? Se les ha otorgado poder divino y vidas prolongadas. Cuando el reino de Dios descienda una vez más y Su voluntad sea restaurada en la tierra, se convertirán en gloriosos creyentes. ¿No es esta una inmensa fortuna y bendición para la frágil humanidad?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6717_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "La alegría de bañarse en la luz divina está más allá de la comprensión de alguien como tú que carece de fe... Que mi dios te perdone, perdone tu ignorancia e insolencia."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6718_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Hagámoslo rápido, Guardián."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6720_AwakerVoiceContent = {Text = "Eh-heh—"},
  Voice_6720_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_6720_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Prepárate para morir, insecto espartano."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "La señorita Muñeca dice que puedo evitar temporalmente la Disolución abandonando mi cuerpo como ella... No puedo hacerlo, no puedo hacerlo, no puedo hacerlo. Perderé la conciencia durante la cirugía, y la oscuridad se apoderará de mí..."
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Chat · Sobre Muñeca"
  },
  Voice_6722_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"muñeca\""
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Hmph... ¿Qué? ¿Buscando el destino de la aniquilación?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "¿Aún atormentado por el insomnio, Maestro? ¡Karen ha preparado el tranquilizante de Dobie para ti~! Aunque la dosis es un poco alta, ¡dormir bien es la prioridad principal!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_6724_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "¡Estábamos bebiendo y cantando cuando de repente nos convertimos en monstruos! Pero está bien, ¡la piel verdosa es bastante divertida!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_6725_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "¿El sueño de Karen? Hmm... Comprar un hermoso collar de perlas y llevarlo a un baile, ¡convirtiéndose en la estrella más brillante!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_6726_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "Ectipo del Deseo, Tifhreid, buscó su camino hacia la existencia. Ante lo desconocido, nadie puede juzgar la nobleza o la bajeza de sus métodos."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Chitchat · Sobre la Entidad del Deseo"
  },
  Voice_67276_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"thais\""
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Pasar a través de la Llave de Plata para llegar a Su Trono."
  },
  Voice_67277_AwakerVoiceTitle = {Text = "Activar"},
  Voice_67278_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "No decepciones Su conocimiento y memoria"
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Desliza a la izquierda, desliza a la derecha, limpia el polvo y las preocupaciones—"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_6727_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "No estoy aquí."
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "Un fragmento del continuo espacio-temporal infinito llega a mi conciencia."
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "He visto toda la imagen."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Todo existe dentro del vacío."
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "Has profundizado, muy profundo. Pronto serás testigo de un milagro extraordinario. Espero que puedas mantenerte tan cuerdo y tranquilo como ahora."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_67284_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "\"Ignorancia.\" No, buscar diligentemente la esencia no es ignorancia; la verdadera ignorancia radica en vivir en la niebla, sin saber lo que no se sabe."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "Te mostraré mis sueños. Todo lo extraño y caótico que ves en ellos está más cerca de la verdadera naturaleza de este mundo que la realidad que conoces."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_67286_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Aquí está mi consejo: Mantente tranquilo. Cuando te sientas cansado, detente de inmediato y conserva tu fuerza y energía. De lo contrario, estarás perdido para siempre en el reino de los sueños."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_67287_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "El universo cicla sin cesar."
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "La sincronización entre nosotros no debería requerir un ajuste tan largo. Sin embargo, para proteger tu claridad mental de las ilusiones, procederé gradualmente."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_67289_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Disolución... Aterrizé en un caso relacionado. Sin embargo, desaparecer parece algo natural, ¿no? Al final, todos desaparecen."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "La Primera Puerta. El universo infinito nació de un punto."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_67290_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "La Segunda Puerta. Una línea se extiende desde un punto, estirándose hacia polaridades infinitas."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_67291_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "La Cuarta Puerta. El arquetipo eterno se solidificó en un espacio de dimensiones."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_67292_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "La Tercera Puerta. Los planos son pronombres parciales y unilaterales."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_67293_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "Portal de los Extremos. El vacío final que conecta innumerables universos. Atraviesa el Portal de los Extremos, y los misterios supremos del mundo te serán revelados."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_67294_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "La Quinta Puerta. El paso del tiempo es solo una ilusión; nunca ha habido un principio, y por ende, ningún final."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_67295_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "Se suponía que solo debía ser tu guía, conduciéndote en este viaje antes de descansar en las aguas ilusorias. Ahora eres mi Enlace, y nuestra conexión es tan intrincada que es difícil de romper..."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "¿Deseas confirmar algo? Desafortunadamente, los sentidos y la mente de este cuerpo están demasiado restringidos. Si nos encontramos en el Abismo, puedo mostrarte mucho más..."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "Ella es uno de mis Fragmentos, de otra Dimensión que ha sido aniquilada eternamente. Lamentablemente, aunque dominó la reversión temporal, no logró entender la esencia de trascender el espacio-tiempo, sucumbiendo repetidamente a la angustia. Esto es mi culpa."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Chitchat · Sobre Ramona la Errante"
  },
  Voice_67298_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Ramona Circular\""
  },
  Voice_67299_AwakerVoiceContent = {Text = "Sé."},
  Voice_67299_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_6729_AwakerVoiceContent = {
    Text = "¿Te preocupa la apariencia de este cuerpo? No lo pienses demasiado. Nací con un rostro humano."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_67300_AwakerVoiceContent = {Text = "He visto"},
  Voice_67300_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_67301_AwakerVoiceContent = {
    Text = "Qué diminuto."
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "Mantén la compostura."
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "Conectarse directamente con la sustancia dañará tu mente... Sin embargo, dado que insistes, responderé a tu llamado."
  },
  Voice_67303_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_67304_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_67305_AwakerVoiceContent = {
    Text = "Esa niña ha soportado demasiado debido a mi Fragmento. Afortunadamente, su Alma sigue tan clara como la plata fluyendo..."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Charlas · Sobre Ramona"
  },
  Voice_67305_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Ramona\""
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Visita Su sueño y vislumbra los secretos tabú del universo."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Hmm."},
  Voice_67307_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_67308_AwakerVoiceContent = {
    Text = "La Puerta de los Extremos se abre para ti. Abraza el mundo del silencio mortal más allá."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_67308_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "Mi propósito al establecer esta escuela con ellos es para \"Almacenamiento\". Has logrado más de lo que anticipé."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "La disolución es un regalo divino. El dolor que trae es justo suficiente para paralizar nuestros nervios, permitiéndonos entregarnos de lleno a la comida, el vino y el desenfreno, y luego encaminarnos hacia la extinción."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Chat · Sobre Disolución"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Pasado, presente y futuro—¡todo el brillo de miles de millones está atado a esto!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Pasado, presente y futuro—¡todo el brillo de miles de millones está atado a esto!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "La Puerta de los Extremos se ha abierto. ¡Aquí, todas las cosas convergen en una!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "La Puerta de los Extremos se ha abierto. ¡Aquí, todas las cosas convergen en una!"
  },
  Voice_67313_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_67314_AwakerVoiceContent = {
    Text = "Escucha la voz de la sabiduría."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Dos"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Infinito, ilimitado, interminable y sin límites."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Tres"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "Es Su voluntad... No, más bien, es una mirada inconsciente que abarca todas las cosas dentro de Su aliento."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "Incapaz de investigar a fondo... trazos sutiles..."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "Revelaré la verdad."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "\"Respuesta\" Yo guardo esta Puerta por amor, y también es por amor que coloco la Llave en tu mano."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Debo... regresar..."
  },
  Voice_6731_AwakerVoiceTitle = {Text = "Activar"},
  Voice_6732_AwakerVoiceContent = {
    Text = "Cielo y Tierra, ¡el ciclo del karma!"
  },
  Voice_6732_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6733_AwakerVoiceContent = {
    Text = "Cielo y Tierra, ¡el ciclo del karma!"
  },
  Voice_6733_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6734_AwakerVoiceContent = {
    Text = "La hoja aún no ha perdido su color."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "El entrenamiento no debe ser descuidado."
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "Más ágil ahora."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "Entidades invisibles estarán bajo tu mando."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_6737_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Siente este aliento abrasador—"
  },
  Voice_6738_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6739_AwakerVoiceContent = {
    Text = "Todos nos transformaremos en... parte de la Llama Verde..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "Mi escudo brillará por ti, mi señor."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_6740_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "¡Mejorado una vez más, muy agradecido!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_6741_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Tch"},
  Voice_6743_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "(Resistencia despectiva)"
  },
  Voice_6744_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6745_AwakerVoiceContent = {
    Text = "(Resistencia despectiva)"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "(Resistencia despectiva)"
  },
  Voice_6746_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6747_AwakerVoiceContent = {
    Text = "El tiempo pasado con todos siempre se siente tan relajante..."
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "El Helot de la Masacre, el Mensajero de Tisífone, la Espada del Odio... Ellos me otorgaron estos títulos. Por supuesto, no me importa ser esa persona."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Charlas · Sobre Mí"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6749_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_6750_AwakerVoiceContent = {Text = "¡All-in!"},
  Voice_6750_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_6751_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6751_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_6752_AwakerVoiceContent = {
    Text = "(Gemido de dolor)"
  },
  Voice_6752_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "¿Podemos ir más lejos esta vez? ¡Vamos a la playa!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "¡Vaya—gracias, amigo~!"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "¡Compañeros~Más Compañeros~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Uvhash... es especial. ¿Crees que la prosperidad de mi familia llegó fácilmente? Todo es gracias a que él mató como un perro loco en la arena. Es nuestra mayor vaca lechera."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Chat·Sobre Uvhash"
  },
  Voice_6757_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"uvhash\""
  },
  Voice_6758_AwakerVoiceContent = {Text = "¡Tonto!"},
  Voice_6758_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_6759_AwakerVoiceContent = {Text = "Heh."},
  Voice_6759_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "¡Ve! ¡Emite la orden de batalla!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "En el abismo... habrá una luz de justicia."
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "¡La luz de la justicia está encendida aquí!"
  },
  Voice_6762_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6763_AwakerVoiceContent = {
    Text = "Las emociones humanas son tan frágiles y preciosas como las flores..."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Charla Ociosa: Sobre Colette"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "¡Hit, Stand, Black·Jack!"
  },
  Voice_6764_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_6765_AwakerVoiceContent = {
    Text = "¡Hit, Stand, ¡Blackjack!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "No resistas, no llores, ¡no vivas!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "No resistas, no llores, ¡no vivas!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "¡Puerta, abre!"
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_79297_AwakerVoiceContent = {Text = "Oh."},
  Voice_79297_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_79298_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_79298_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_80092_AwakerVoiceContent = {
    Text = "La hidroterapia, la terapia electroconvulsiva, la terapia de restricción, estos no son tratamientos, sino torturas. Por lo tanto, durante mi período pro bono, trataré a los pacientes en el hospital psiquiátrico a mi modo, y al final, todos lograrán la recuperación y encontrarán la verdadera libertad."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_80092_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Pobre White, porque el asilo cercano está lleno, su familia lo mantuvo en un pocilga. Lo traté gratis, y después de eso, finalmente se dio cuenta de que era una persona, no ganado, y reclamó su dignidad como humano."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_80093_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Tejedores, abogados, barones... Nunca rechazaré a los pacientes debido a tarifas; para mí, son meramente pacientes que necesitan sanación."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_80094_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "Admito que realmente te subestimé; tu existencia es el propio dolor. Esta vez, no es necesario realizar visitas de seguimiento, quiero quedarme a tu lado y ver el resultado de primera mano."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_80095_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "Estos pacientes me han dado recuerdos hermosos. A continuación, es tu turno, Guardián, ya he elegido el final para ti. Esa será la consulta más exquisita de mi carrera."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_80096_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Rechazar la ayuda del doctor no te beneficia. Quizás la próxima vez, necesitemos intentar la hipnosis profunda."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "En una habitación oscura, completamente sola, junto con los innumerables susurros dolorosos que resonan constantemente en mi mente, esta es la mejor manera de disfrutar del tiempo."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Aunque puede ser descortés decirlo, hablar con ese niño solo me aburre—solo puedes ver una expresión, y esa es una sonrisa."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Chat · Sobre Aurita"
  },
  Voice_81140_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"aurita\""
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Perdóname por intrudir, solo sentí tu baja energía psicológica y vine a comprobar cómo estás. Ahora, Guardián, ¿te gustaría embarcarte en un viaje mental?"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_81143_AwakerVoiceContent = {
    Text = "El doctor psiquiátrico cura a los pacientes perforando sus cráneos con una técnica de trepanación—relájate, eso fue hace mucho tiempo, ahora tenemos muchas maneras de medir y profundizar en la mente del paciente."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_81143_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "Para entenderse mutuamente, uno solo puede abrir su corazón—toca aquí, y mi corazón plateado se abrirá para ti."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "Si quieres escuchar mis pensamientos sobre algo, podrías decepcionarte. Más que desahogarme, soy mejor escuchando."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "¡Ah, escuché Su voz, esos murmullos, cada sílaba llena de la máxima agonía!"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "Recordaré el dolor de este momento en mi corazón, recordándolo y saboreándolo repetidamente..."
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "Como un fragmento de esa existencia, llevas su aliento, ese aliento lleno de dolor, haciendo que cualquier recuerdo tuyo sepa increíblemente delicioso."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "Recuerda esos miedos, detalla tus sentimientos de dolor; la esencia de la terapia de impacto emocional es enfrentar el dolor directamente y conquistarlo. Ven, seca tus lágrimas y cuéntame lentamente esos recuerdos en detalle..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_81149_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Felicidades, estás curado—sí, las alucinaciones y las ilusiones son fenómenos normales; son prueba de tu recuperación."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_81150_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "Tu mente seguramente está llena de imágenes extrañas y bizarras, lo cual es normal. Dibuja esas imágenes, y tu subconsciente e instintos revelarán todo por ti."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_81151_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "A continuación está la terapia moral de Philip Pinel. Necesitas expresar tus deseos y miedos más profundos, lo cual es un procedimiento necesario para liberar la mente y restaurar la humanidad dormida."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_81152_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Guardián, ¿puedes ayudarme con una pequeña prueba? Solo es la prueba de manchas de Rorschach. Al aprobarla, podré ver las profundidades de tu ser interior que permanecen desconocidas para los demás, convirtiéndome en el único Despertador que desvela los secretos del corazón del Guardián."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Charla·Sobre el análisis psicológico"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "Primero, escuchemos una pieza de música. ¿Puedes oírlo, la música suave y gentil? Ahora, deja que tu cuerpo y mente resuenen con la música, entrando en un estado de relajación espiritual..."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_81154_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Mirando el péndulo, dejando que tus ojos sigan su movimiento..."
  },
  Voice_81155_AwakerVoiceTitle = {Text = "Activar"},
  Voice_81156_AwakerVoiceContent = {
    Text = "Shh—Silencio, entonces camina hacia el final que te guío."
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "Un alma entumecida no despierta mi interés en absoluto. Sus almas ya han muerto, y no importa cuánto se las agite, no habrá una onda."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "Estoy escuchando, por favor continúa."
  },
  Voice_81159_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_81160_AwakerVoiceContent = {
    Text = "Por favor, mantente en silencio."
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_81161_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_81162_AwakerVoiceContent = {
    Text = "Confía un poco más en mí."
  },
  Voice_81162_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_81163_AwakerVoiceContent = {
    Text = "¡Expón más del dolor!"
  },
  Voice_81163_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_81164_AwakerVoiceContent = {
    Text = "No hay necesidad de esconderse, no hay necesidad de ser tímido, soy tu oyente más confiable y único. Ven, desahoga tu dolor más profundo conmigo..."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "Aigis se ve mucho más brillante ahora. Por supuesto, si mi pequeño invitado necesita ayuda, estoy feliz de ofrecerla. Quiero decir, ayuda genuina."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Chat · Sobre Aigis"
  },
  Voice_81165_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Aigis\""
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Muéstrame tu yo más verdadero."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "Saborearé este dulce dolor."
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "No hay necesidad de esconderse, no hay necesidad de ser tímido, soy tu oyente más confiable y único. Ven, desahoga tu dolor más profundo conmigo..."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "La enfermedad mental no es exclusiva de esta era; trasciende el tiempo y el espacio, y la disolución es la misma. Ambos trascienden los límites de la cognición humana, ¿no es así?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Shh—Silencio, entonces camina hacia el final que te guío."
  },
  Voice_81171_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_81172_AwakerVoiceContent = {
    Text = "Este lugar está lleno de huellas de la historia, y en cierta medida, la historia representa recuerdos—recuerdos dolorosos de los que se han ido."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Respira hondo..."
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "Dolor, desesperación, muerte... estos recuerdos saben a postre después de una comida."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "No es necesario estar tan nervioso, esto es solo una consulta psicológica regular."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Escucha mi guía."
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "Ha ocurrido un incidente imprevisto en el ritual. Por favor, perdóname por golpear tu brazo con la bandera, debo mantenerte consciente."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_84185_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Aquí puedo ver diferentes modelos de barcos y acceder a equipos de navegación más avanzados, lo que me gusta mucho. Lo más importante es que creo que este \"barco\" está en el curso correcto de la historia humana."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "El ritual se realizó con éxito, gracias por su cooperación. La próxima vez crearé algunas señales con banderas exclusivas para ayudarnos a completar el ritual de manera más segura y exitosa."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_84187_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "No sé por qué existe, solo sé una cosa: debo guiar con éxito la navegación y devolver a salvo a todos los marineros y pasajeros que salieron al mar."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "Confía en mí, usaré este poder para garantizar la seguridad en la navegación del barco y jamás lo malutilizaré."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Detén la resistencia."
  },
  Voice_84190_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_84191_AwakerVoiceContent = {
    Text = "Solo tengo el mayor respeto por usted y cumpliré con todas sus órdenes hasta la muerte."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Lo siento, no entiendo a las personas, solo entiendo los barcos. Por favor, perdóname por usar esta analogía: tu quilla no es de madera ni de hierro, sino de acero, fuerte y firme, digna de admiración."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_84192_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_84193_AwakerVoiceContent = {Text = "Ríndete."},
  Voice_84193_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_84194_AwakerVoiceContent = {
    Text = "Más que \"gustar\", prefiero usar la palabra \"convertirse\". Cuando miré directamente al dios inefable, mi cerebro perdió la razón y entró en éxtasis, sí, debería temerlo, pero no puedo controlarme."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "No seré derribado por la tormenta."
  },
  Voice_84195_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_84196_AwakerVoiceContent = {
    Text = "Si no hay orden, ¿qué queda en este mundo? Solo Caos y confusión."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "La próxima vez que zarpe, quiero subir a bordo con una identidad distinta a la de navegante. Ese... quiero decir que estoy dispuesto y acepto actuar bajo su guía. Usted merece toda mi confianza."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_84197_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "Solo estoy cumpliendo con mis deberes como navegante, no necesito reconocimiento público."
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "El sistema del faro puede aliviar enormemente el estrés de la navegación, y su luz es especialmente brillante. Me encantaría navegar junto a Faros."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Chat · Sobre Faros"
  },
  Voice_84199_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Faros\""
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Marineros, seguid mis indicaciones. Llegaremos al puerto sanos y salvos."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "Enlace espiritual establecido con éxito, he percibido su conciencia... Es la primera vez que navego en el vacío, si ocurre una desviación, por favor corríjame a tiempo."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_84201_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Se han observado nubes cirrus y una caída continua del mercurio en el barómetro. Atención a todos, el barco está a punto de enfrentar una tormenta."
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "Este desastre fue causado por mi incorrecta planificación de la ruta, y estoy dispuesto a aceptar el castigo según las reglas."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Medir el ángulo de elevación del cuerpo celeste."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "Esta sensación de mareo es similar a la que se siente al estar mareado en un barco. Por favor, cierra los ojos, toma mi mano y apóyate en mí, así te sentirás mejor."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_84205_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Izar la vela mayor, navegar a barlovento por babor, y el timonel ajusta el rumbo según mis cálculos."
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "Estas experiencias son invaluablemente preciadas, las registraré detalladamente en el diario de navegación, dejándolas para los marinos venideros."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "El ritual para profundizar el vínculo conlleva riesgos y resultados desconocidos, pero por favor, confíe en mí, lo guiaré para que el ritual se complete con éxito."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_84208_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Ajusta el centro de gravedad nuevamente."
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "Ten cuidado con la protección del barco."
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "Algunos son como barcos de vapor, lentos para responder pero capaces de funcionar a alta velocidad; otros son como barcos diésel, arrancan rápido pero tienen potencia limitada. ¿Y usted, Guardián del Secreto?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_84211_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "Estoy firmemente convencido de que el esfuerzo siempre trae recompensas como parte de su naturaleza básica, y en el futuro me esforzaré aún más."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "A través de múltiples operaciones, usted ha demostrado su capacidad. Creo que usted es un navegante tan excelente como yo... no, quizás incluso mucho más excelente que yo."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_84213_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_84214_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_84215_AwakerVoiceContent = {
    Text = "Siempre estaré listo cuando usted me necesite, Cuphantes."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_84215_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Marineros, seguid mi guía, llegaremos seguros al puerto."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "Navegante Kepersant presentándose. La bandera está preparada y mi estado es bueno. Guardián del Secreto, por favor dé la orden de zarpar."
  },
  Voice_84218_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_84219_AwakerVoiceContent = {
    Text = "Yo guiaré al barco hacia el rumbo correcto."
  },
  Voice_84219_AwakerVoiceTitle = {Text = "Activar"},
  Voice_84220_AwakerVoiceContent = {
    Text = "¿Es que el sombrero está torcido? Lo siento, no entiendo muy bien su intención, por favor, dame una orden clara."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "La bandera es el lenguaje del navegante, y también su epitafio. Cuando el barco se hunda, los rescatadores extraerán de los restos de la bandera el último mensaje que dejé."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Charla·Sobre la bandera"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Percepción del punto de equilibrio del casco."
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "Recoge la vela mayor del trinquete, inclina hacia babor para contrarrestar las olas y el timonel ajusta nuevamente la ruta según mis cálculos."
  },
  Voice_84223_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_84224_AwakerVoiceContent = {
    Text = "La bandera E transmite la orden."
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "En momentos necesarios, un navegante que haya estudiado colaboración en la sala de máquinas también puede fungir como timonel, pero para garantizar la seguridad del barco, prefiero entregar esta tarea a alguien que sea hábil en ella."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Chat · Sobre Celeste"
  },
  Voice_84225_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"celeste\""
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "Sensación de ingravidez, seguida de una intensa sacudida similar a la de un barco. Sigue mis movimientos y percibe el centro de gravedad de tu cuerpo, manteniendo el equilibrio."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_84226_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Iniciar la corrección del mapa marino."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Tres"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "La bandera C responde a la orden."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Dos"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Tres"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "Ni te atrevas a pasarme por encima."
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "¿Cómo deberían tratarse los amigos? A Pólux le gusta darme órdenes para hacer muchas cosas, incluso cuando él mismo puede hacerlas perfectamente. Y yo también estoy dispuesto a hacer esas cosas por él, es nuestra forma de interactuar. Si tú quieres, también haré algo por ti."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_90334_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "¡Con este cuerpo inmortal, resistiré todas las calamidades!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "Aunque incluso antes de leer ese libro también sentíamos curiosidad por el mundo exterior, por el lago, por la isla solitaria y por lo que había más allá del muro rojizo. Pero cuando Pólux fue torturado, ni siquiera se me pasó por la mente resistirme. Comparado con Pólux, soy mucho más cobarde y torpe."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_90336_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "¿Parezco un tonto? Lo siento, por favor, perdona mi ignorancia. Aparte del conocimiento sobre los dioses que nos ha enseñado la iglesia de la luz del templo, sé muy poco sobre cualquier otra cosa. Aprenderé rápidamente, ¿me puedes decir qué te gusta y qué te disgusta? Te prometo que lo recordaré bien."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_90337_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "¡Sé testigo de esta voluntad por alcanzar la libertad!"
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "Una tienda que puede satisfacer cualquier deseo, con mercancías de todo tipo, realmente da miedo... No, no estoy cuestionando el poder de esa dama, pero \"para obtener algo, debes pagar el precio correspondiente\". Esa verdad, tanto yo como Pólux hemos experimentado demasiadas veces."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Charlas Breves · Sobre Narcisos"
  },
  Voice_90339_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Daffodil\""
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "¿Pueden estas alas malditas también elevarse en lo alto del cielo?"
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "¡No podéis destruirme!"
  },
  Voice_90341_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_90342_AwakerVoiceContent = {
    Text = "¿Quiere tocar estas plumas? Adelante, ¿debo desplegar un poco más las alas?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "Cuando recibo ayuda de otros, a menudo me pregunto: ¿habrá algún precio detrás de esa atención especial, esos valiosos libros que me has regalado, esas hermosas piedras y cristales de meteorito? Lo siento, no debería sospechar de ti de esta manera."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_90343_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "El ave algún día volará en lo más alto del cielo."
  },
  Voice_90344_AwakerVoiceTitle = {Text = "Activar"},
  Voice_90345_AwakerVoiceContent = {
    Text = "¿Un maestro en la preparación de platos gourmet...? Realmente es muy necesario tener conocimientos culinarios, aunque mis exigencias para comer no sean altas, Polux sí es demasiado exigente con la comida. Parece que debería encontrar un momento para consultar seriamente con él... ¿No ir? ¿Por qué? Sin embargo, la comida que prepara ese caballero parece realmente deliciosa."
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Charla·Sobre Dursayn"
  },
  Voice_90345_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Dursayn\""
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "Ahora que lo pienso, aquellas sirvientas de la época de las linternas no eran muy diferentes de mí y Pólux; todos llevábamos cadenas y vivíamos atados, y ellas siempre las aceptaron con sumisión y paciencia. Pero esa sirvienta verde parece ser algo distinta, ella... era muy enérgica, como si naturalmente disfrutara hacer esas cosas. Quizás ella ya poseía la más valiosa libertad."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Chat·Sobre Karen"
  },
  Voice_90346_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"karen\""
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "¡No podéis destruirme!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "Aún no... ¿no lograste volar?"
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "¡Desvanécete con el viento!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Dos"
  },
  Voice_90350_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_90351_AwakerVoiceContent = {
    Text = "Buenas, encantado de conocerte, soy Castor... ¿Debo decir algo más? Lo siento, no soy muy hábil con las palabras. Si hay algo que deba saber, por favor avísame cuando quieras."
  },
  Voice_90351_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_90352_AwakerVoiceContent = {
    Text = "Nada especial..."
  },
  Voice_90352_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_90353_AwakerVoiceContent = {Text = "¡Cae!"},
  Voice_90353_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_90354_AwakerVoiceContent = {
    Text = "Tengo muchas cosas que no he visto, muchas cosas que no he hecho; esos lagos profundos de color verde oscuro y esa niebla densa que nunca se disipa ya no nos atraparán más. Quiero ver el océano, las grandes ciudades, los campos y pastizales, todos esos lugares mencionados en ese manuscrito, junto con Pólux y usted."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_90354_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "Cuando escuchas el susurro de las hojas del árbol, sabes que ya estoy a tu lado."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_90355_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "Estas plumas oscuras se han vuelto aún más profundas."
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "Lo que más envidio es precisamente esa forma tan libre de sospechas y completamente confiada que tienen usted y sus compañeros. La sensación de ser olvidado y traicionado... es realmente insoportable."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "Esa ladrona me dijo que podía enseñarme las técnicas más avanzadas de supervivencia callejera, solo tenía que pagarle quinientos leubos... ¿Me engañó? No, creo que es un conocimiento muy valioso, exactamente lo que yo y Pólux necesitamos... ¿Es cuestión de dinero? Entiendo, entonces, ¿qué tal si voy a hablar con ella y le pago cuatrocientos cincuenta leubos?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Chismes · Sobre Jenki"
  },
  Voice_90358_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Jenkins\""
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "Aún puedo aguantar..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "Cuando era pequeño, el control y la vigilancia de la linterna aún no eran tan estrictos. A veces, solo con que Polux fuera a decir algo, mágicamente conseguía un puñado de dulces. La sensación al probar esos dulces... era justo como ahora."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_90360_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "¡Con este cuerpo inmortal, resistiré todas las calamidades!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "¿Puedes enseñarme sobre el conocimiento de hacer tratos con personas? Cómo intercambiar objetos, cómo administrar el dinero obtenido, es realmente una ciencia profunda. Ganar la libertad es solo el comienzo, para poder vivir de forma independiente, Castor, Pollux y yo tenemos mucho que aprender. A partir de ahora, seguramente te molestaré con frecuencia."
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "¡Desapareced con el viento!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "¡Viento, sopla hacia la boca de la muerte!"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "Pólux... aunque fue imbuido por la Linterna con muchas ideas negativas, su esencia no es mala. Solo ansiaba desesperadamente ser reconocido por la Linterna y por los fieles, hasta el punto de preocuparse excesivamente por sus necesidades. Más que decir que es demasiado egoísta, sería mejor decir que siempre ha temido perder ese \"ego\"."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Charlas·Sobre Pólux"
  },
  Voice_90365_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Pólux\""
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Lo siento, no fue mi intención quedarme pensativo... ¿Me preguntaba sobre esta pluma? Es... lo más importante para él, y también lo más importante para mí. ¿No es hermosa?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "En aquella época, cada día debíamos estudiar teología bajo la enseñanza de los albinos o los guardianes de la luz, y en ese momento mi mayor deseo era que algún día esas escrituras pudieran ser revisadas y se hicieran más cortas y concisas. Así no me sentiría mareado por memorizarlas y no sería criticado por los estrictos guardianes de la luz."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_90367_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Gracias por entregarme la llave que me otorga el control de la libertad."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "¡Por fin estas alas han crecido hasta su forma más plena, tan fuertes y poderosas! Ahora puedo llevarte a ti y a Pólux al mismo tiempo. Cuando quieras volar hacia el cielo, ¡llámame en voz alta!"
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_90369_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "¡Escondete detrás de mis alas!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "Finalmente... vi el vasto cielo estrellado mencionado en el libro."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "Antes, nuestra líder... Juliette también solía tener momentos cálidos con nosotros. Siempre mostraba su cálida sonrisa a todos, haciendo que temiéramos defraudar sus expectativas. Solo con que sonriera y acariciara tu cabeza, ya no podías decir ninguna palabra de resistencia. Hmm, ya no es así ahora. Puede acariciar mi cabeza sin restricciones."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_90372_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "Estuve sumergido en esa sustancia negra y viscosa durante mucho, mucho tiempo, tanto que llegué a olvidar el paso del tiempo, tanto que... hasta que Pollux me olvidó también. Lo que trae no es dolor físico, sino un miedo del alma, una impotencia ante la desaparición propia frente a tus propios ojos."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "Desde pequeños no nos estaba permitido tener mucho contacto con otras personas, y la palabra \"amigo\" fue algo que conocimos mucho tiempo después. Pólux y yo no teníamos a nadie más que el uno al otro: hermanos, amigos, prisioneros en la misma celda, todo eso éramos nosotros, solo nosotros. Ahora, es momento de hacer algunos nuevos amigos."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_90374_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_90375_AwakerVoiceContent = {
    Text = "¡Retrocede!"
  },
  Voice_90375_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "¿Una escuela donde todos pueden comunicarse libremente y hacer amigos sin restricciones? Dices que aquí no se estudia teología y que incluso se pueden elegir todo tipo de cursos... ¡e incluso faltar a clases? Hmm, realmente suena como un lugar maravilloso."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_90378_AwakerVoiceContent = {
    Text = "¡Fuera del camino!"
  },
  Voice_90378_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_95050_AwakerVoiceContent = {
    Text = "Persona irreverente... habrá un castigo..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "¡Mi corazón brilla con luz!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_95052_AwakerVoiceContent = {
    Text = "Objeto contaminado."
  },
  Voice_95052_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "Un creyente demasiado ferviente quizás no sea para el mundo más que un loco incomprensible. Aunque ella también haya tomado caminos equivocados, esa determinación de entregar todo por los dioses es una fortaleza que la mayoría de las personas comunes no pueden alcanzar. Respecto a ella... siento solo un poco de tristeza al ver a alguien semejante a mí."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Charla · Sobre Miriam"
  },
  Voice_95053_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Miriam\""
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "Traeré guía y juicio, ¡el resplandor de la noche blanca disipará vuestro pecado!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "¡Ja... Después de tanto tiempo, sigue igual que antes! Tal vez en mi niñez nunca imaginé que un día lo heriría y le causaría tantas deudas, tantas que me harían sentirme avergonzado, aunque este destino trágico no esté bajo el control de ninguno de nosotros. Hemos pasado por tantas separaciones, pero ahora que he regresado, desde hoy en adelante, nada podrá separarnos de nuevo, ni siquiera la muerte."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Charlas: Sobre Castor"
  },
  Voice_95055_UnlockDesc = {
    Text = "Desbloquear después de obtener el Despertado\"Castor\""
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "Antes odiaba muchas cosas. Los sirvientes descorteses, los subordinados irrespetuosos, los herejes que blasfemaban contra los dioses... Pero ahora, ¡la Linterna, solo la Linterna! Juliette y su culto nos han causado a mi hermano y a mí heridas irreparables. ¡Juro por el nombre del Hijo Santo que no permitiré que este dolor vuelva a afectar a otra persona!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "Seguiré el camino de la luz hasta el final de mi vida."
  },
  Voice_95057_AwakerVoiceTitle = {Text = "Activar"},
  Voice_95058_AwakerVoiceContent = {
    Text = "¡La luz del Portador de la Lámpara finalmente iluminará la larga noche!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "Siempre es tan generoso y misericordioso, comprenderé profundamente esta calidez de la luz."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "El apóstol del Portador de la Luz, el nacido en la noche blanca, el disipador de la oscuridad, el santo hijo de un corazón sagrado, yo, Pólux, he venido en respuesta a tu llamado, ofreciéndote mi poder oscuro y mi alma luminosa."
  },
  Voice_95060_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_95061_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "¡Purifica tus pecados!"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "Antes, todos me decían que esta oscuridad abismal era mi fe, la bendición que debía otorgar a los creyentes. Hoy, esta oscuridad ya me ha corrompido, fusionándose completamente conmigo... Pero el corazón que late en este cuerpo pecador, es un lugar que nunca podrá ser corrompido. Tranquilos, usaré la capacidad que me otorga esta oscuridad para llevar la verdadera bendición al mundo!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "Difundiré tu gran nombre, y todas las cosas impuras e inmundas serán purificadas por la luz."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "Los pecados del pasado ya han sido cometidos, no debería seguir huyendo de ellos. Aún debo corregir los errores de la Linterna y guiar a los que están extraviados hacia el camino correcto. ¡Dejadme asumir mis pecados! Entonces, responderé a esta luz, a Tu llamado, y emprenderé el verdadero camino, el camino del Hijo Santo."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_95065_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "¡Qué corazón tan compasivo tienes, que te hace dispuesto a perdonar a una persona llena de pecados! Puedo sentirlo, esa luz pura y más brillante que la llama de una vela en tu alma... quizás puedas guiar mi corazón perdido..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_95066_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "Esas tinieblas, la oscuridad que se extendió desde la maldición de Yoliet, siempre han estado en mi mente... Pero ahora, ¡una luz ha aparecido en esa oscuridad! ¿Qué me quiere decir ese débil punto de luz?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_95067_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "Dicen que ella también fue una santa en el pasado, pero... ¿esa actitud tan grosera, esas palabras y acciones tan violentas? ¿Qué? ¿Ni siquiera sabe recitar una sola plegaria? Con una apariencia tan carente de devoción, uno casi siente vergüenza ajena por su dios."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Charla: Sobre Murphy"
  },
  Voice_95068_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Murphy\""
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "El que pueda guiar a todos fuera de la niebla es el verdadero portador de la luz de plata pura. La tierra inocente mencionada por Juliette está en realidad construida sobre los cuerpos amontonados de los fieles. Como hijo sagrado, esparciré la nueva buena nueva a todos los creyentes dignos de salvación."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "Guíame, portador de la luz. Durante tanto tiempo estuve cegado por un significado falso, pero ahora, bajo tu orientación, he recuperado mi verdadera misión: corregir a aquellos herejes ignorantes y retorcidos, trayendo una luz eterna al mundo. Conozco tu altruismo, no necesitas mi devoción ni mis ofrendas. Permíteme entonces seguir a tu lado, registrando cada una de tus palabras y acciones sagradas, para que en las tinieblas me guíen por el camino correcto."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_95070_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "Caminar hacia la luz, con cadenas y bañado en oscuridad, con paso firme y decidido... ¿Esta es la palabra que quieres decirme?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_95071_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "Un servidor de la luz ha perdido la lámpara en sus manos, este dolor ciego realmente me llena de angustia. Sinceramente te ruego que salves esta alma perdida, por favor toma mi mano, acércate a este corazón sagrado, y concédeme tu guía hacia la luz..."
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_95072_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "Desafortunadamente, la niña, pero si ya se ha dedicado a seguir tu causa, seguramente alcanzará la redención final. Sin embargo, ¿por qué su amigo, ese mono, también ha recibido tu benevolencia? ¡Esa niña malvada incluso robó mi relicario de oración! Seguro que su alma esconde una inundación de pecados, ¡qué impía! ¡Impía!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Charla: Sobre Aigis y Jenkins"
  },
  Voice_95073_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Aigis\" y Despertado\"Jenkins\""
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "Vete rápidamente."
  },
  Voice_95074_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "¡La luz del Portador de la Lámpara finalmente iluminará la larga noche!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "¡Ah... ya lo he visto, la inmensa fuerza, la verdad del mundo... Ya comprendo mi error del pasado. ¡Tú eres el verdadero Portador de la Luz! Por favor, permíteme ser tu apóstol leal. Este corazón nacido para el Portador de la Luz, desde ahora latirá y temblará en sumisión por ti..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_95076_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "Ese sacerdote está cometiendo una insensatez al pretender salvar a ciegas; la buena nueva de Dios debe ser concedida naturalmente a los justos devotos. Si incluso los apóstoles de Dios carecen de ojos perspicaces para distinguir, y terminan recompensando a criminales impíos y pecadores incorregibles, contaminando así el reino puro de Dios, ¿no sería esto una verdadera traición contra los dioses y aquellos justos?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Charla: Sobre Salvador"
  },
  Voice_95077_UnlockDesc = {
    Text = "Desbloqueado al obtener Despertado\"Salvador\""
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "¡Mi corazón brilla con luz!"
  },
  Voice_95078_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_95079_AwakerVoiceContent = {Text = "¡Hah!"},
  Voice_95079_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_95080_AwakerVoiceContent = {
    Text = "Cuando era niño, solo quería volar lejos de esta jaula. En ese entonces, siempre creía que este lugar, que solo causaba dolor, no merecía mi nostalgia. Pero después de haber vivido dos vidas, ahora entiendo que la libertad no es lo único que anhelo. Ver a los fieles cuando conocen que serán redimidos, ver sus expresiones llenas de sinceridad, esperanza y gratitud, esa es la verdadera significación de ser el Hijo de Dios."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "Durante el tiempo que seguí a Juliette, cometí muchos errores y ya no debería merecer esta confianza. Pero usted aún así me eligió a mí... No se preocupe, encontraré nuevamente mi propia creencia. El Hijo no decepcionará a sus súbditos, ni tampoco a usted."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_95081_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Haré uso de lo que me ha concedido con gratitud."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_95083_AwakerVoiceContent = {
    Text = "¡Descortés!"
  },
  Voice_95083_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_95084_AwakerVoiceContent = {Text = "¡Maldito!"},
  Voice_95084_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_95085_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_95086_AwakerVoiceContent = {
    Text = "¡En mi nombre!"
  },
  Voice_95086_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_95087_AwakerVoiceContent = {
    Text = "¡Lo vi! Esa luz, esa luz que brillaba en lo profundo de mi conciencia, ¡se está volviendo cada vez más brillante! Me está llamando..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_95087_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "Durante mi infancia, Castor y yo compartimos el cargo de Hijo Santo. En aquella época, siempre creía que él era demasiado torpe y necesitaba que yo le guiara el camino futuro. Hoy, conociendo el camino que usted ha recorrido, entiendo que los cimientos del mundo son construidos y forjados por personas como usted y él, que mantienen su integridad y perseverancia."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_95088_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "Mi luz, desde que recibí tu guía, creo que he tomado el camino completamente correcto. Hasta ahora, tu humilde seguidor aún tiene una duda: ¿esa tierra inocente mencionada en las leyendas también está bajo tu mando? ¿No existe tal cosa? ¿Tu intención es decir que... la tierra inocente está en este mundo, está en los corazones puros de los justos?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "Este corazón que escucha la voluntad divina se ha acercado aún más a usted."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "¿Usted... tiene alguna orden que darme? Su apóstol está listo en todo momento para escuchar sus enseñanzas."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "¡Ilumíname, guía perdida! Con tu luz, he visto todo lo que necesitaba ver... Con este cuerpo maldito, purificaré todo el pasado y traeré todo el futuro bajo esta luz."
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_95092_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "¡Corazón sagrado devoto como mecha, la luz brillará para siempre!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "¿Buscar la salvación en un mundo cruel? Vamos, pequeño lleno de esperanza."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_95391_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "Vamos, llévate estas para jugar. Dicen que son colecciones tabú excavadas de algún sitio arqueológico. No me interesan esas cosas que huelen a Su presencia; pensaba quemarlas directamente, pero como quizás te puedan servir, te las traje. ¿Cómo las conseguí? Pues claro, algunas personas \"voluntariamente\" me las dieron. Tranquilo, te aseguro que su origen es \"limpio\"."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_95392_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Caza completada, que la sonrisa del pequeño sea el pago de la recompensa."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "¿Sabes, pequeño?, las balas que salen de estas dos pistolas no son ordinarias, sino la concentración de deseo y maldad. Este caos desordenado forma llamas similares a tejidos carnosos, y en el séptimo disparo al otro lado, arrastrará todo al infierno para ser quemado."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Charla · Sobre las armas de fuego"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "No debes presionarte tanto, mi Guardián del Secreto. Aunque sé que es un camino tortuoso que no admite demoras, y un pequeño error podría llevar a consecuencias irreversibles. Pero si continúas así, algún día caerás víctima del agotamiento. Si lo necesitas, habla conmigo, como miembro de la familia que eres."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_95395_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "¡Quema, destruye y aúlla!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_95397_AwakerVoiceContent = {
    Text = "Desaparecer."
  },
  Voice_95397_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_95398_AwakerVoiceContent = {
    Text = "Mi visión es ahora más clara, puedo ver lo que se oculta bajo el abismo... ¡Para vosotros, debo conseguir un poder aún mayor!"
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_95398_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "¡Ven, Guardián del Secreto, acércate más! Ahora mismo pareces demasiado distante. ¿Sabes? La primera vez que te vi, nunca imaginé que un día podría quitarme esta capa de crueldad y frialdad que llevo puesta. Es un poco ridículo, ¿verdad? El temido y brutal Señor de la Explosión ardiente anhela tener un ser querido a quien confiarle su corazón sincero. \nProméteme una cosa: si llega el día en que ya no puedas soportarlo... llama mi nombre en tu corazón. Yo te llevaré conmigo, juntos nos dirigiremos a mi reino. Aunque esto solo pueda retrasar lo inevitable, al menos en el último momento podrás descansar bien, entre mis brazos."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_95399_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "Acepta tu destino."
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_95401_AwakerVoiceContent = {Text = "¡Ugh!"},
  Voice_95401_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_95402_AwakerVoiceContent = {
    Text = "¡Arde en mil millones de deseos y maldad!"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "Después de una caza exitosa siempre se necesita un banquete de celebración. Ven, prueba mi carne de camello asada y el recién conseguido tequila de agave. Espera, pequeño, parece que no puedes beber alcohol... Entonces prueba mi jugo especial."
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_95403_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "¿Qué pasa, pequeño? ¿Quieres un abrazo? Vamos, mi pecho ardiente siempre está listo para ti... ¡ja, ja! No seas tímido. ¿No es lo más normal del mundo que una hermana mayor muestre preocupación por sus hermanos menores?"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_95406_AwakerVoiceContent = {Text = "Maldito."},
  Voice_95406_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "¡Recibe la muerte ámbar!"
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "Retirémonos primero, yo cubriré la retaguardia... no te preocupes, volveré con vida."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "¡Vamos, convirtamos todo en cenizas!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "¡Fuego explosivo, arde nuevamente aquí!"
  },
  Voice_95410_AwakerVoiceTitle = {Text = "Activar"},
  Voice_95411_AwakerVoiceContent = {
    Text = "El fuego arde cada vez con más intensidad, ¿quieres ver, pequeño, un espectáculo de fuegos artificiales magnífico?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Esos tipos que pisotean la moral, se esconden en la sombra y usan a @1 como material para sus sucios sacrificios e investigaciones... algún día, los mataré a todos."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_95413_AwakerVoiceContent = {Text = "¡Pum!"},
  Voice_95413_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_95414_AwakerVoiceContent = {
    Text = "Lo encontraré, sin importar en qué rincón del universo se esconda, al final lo encontraré. \nEsta sucia rata pagará con todo su ser. Cuando lo encuentre, en ese instante, toda alegría y placer en este mundo arderán en el infierno. \nTranquilo, en su funeral te reservaré un asiento de primera fila, para que podamos saborear juntos su último grito de agonía."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Charla · Sobre N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "¡Escucha el lamento de las estrellas que se disuelven!"
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_95415_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "¡Acepta tu destino."
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "¡Tú eres un miembro de mi familia del que me siento orgulloso! Ten confianza, ¡mi Guardián del Secreto! Pase lo que pase, siempre seré tu apoyo más fuerte."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Esas existencias indescriptibles están corroyendo este mundo, inevitablemente te enfrentarás a ellas. Pero eso no importa, porque yo estaré detrás de ti."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_95418_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "¡Quema, destruye y aúlla!"
  },
  Voice_95420_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_95421_AwakerVoiceContent = {
    Text = "Mantén la calma."
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_95422_AwakerVoiceContent = {Text = "Retrocede."},
  Voice_95422_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "¿Qué pienso de la Corrosión? Es como preguntarle a un pequeño ratón que corre por las cloacas qué opina del noble señor que está por encima. Mi respuesta es solo una: repulsión instintiva. Si pudiera, disfrutaría de un delicioso licor de leche de camello mientras escucho sus gritos al morir bajo mis disparos."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "¿Quieres que el fuego arda aún más intensamente?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_95424_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "Solo vendré aquí cuando acepte una misión. Si el pequeño quiere encontrarme, use esta palabra mágica. Vamos, repite conmigo: ... ... ... ¡Ia! ¡KathiguRa!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "Hace no mucho tiempo, aún estábamos en ese pueblo decadente, luchando por sobrevivir con ferocidad y astucia. Incluso al convertirnos en una \"gran fuerza\", debíamos mantenernos alertas ante el amo, el cuerpo de guardias y los \"señores caballeros\" que no querían abandonar la historia. Pero ahora es diferente, todos se han convertido en mis \"familiares\", ya no necesitamos preocuparnos por las miradas ajenas. Bueno, aunque aún queda un pequeño que anda por ahí, confío en que estará bien, después de todo, cada vez que estoy ocupado afuera, es precisamente ese tipo quien se encarga de cuidar a los demás."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Charla · Sobre la familia"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "Este es el enemigo del pequeño, ¿verdad? Entonces... comienza la caza."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "¡Yo soy el Señor de la Explosión que nunca será olvidado! ¡Proclama! ¡Todo perecerá!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "La combustión y la destrucción son todo para mí, me apasiona la muerte que trae la caza... ¿Crees que yo diría eso?\n¡Ja, ja! Era broma. Para mí, lo más importante son todos ustedes que están a mi lado. Nadie es más importante que ustedes, ni siquiera yo mismo."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "¿El pequeño está en problemas? Entonces, respondiendo a la llamada, Kittygura llegará con destrucción. Que todos los problemas se reduzcan a cenizas con un \"¡pum!\"."
  },
  Voice_95430_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_95431_AwakerVoiceContent = {
    Text = "¿Quieres probar el sabor del poder buscando alguna desafortunada criatura para practicar?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_95431_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "¡Yo soy el Señor de la Explosión que nunca será olvidado! ¡Declara! ¡Todo perecerá!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "La legendaria reina de Aran, la gran sustancia del deseo Tifré Yessod, tuve el honor de verla una vez cuando perseguía a N. Aunque no apruebo lo que ella hizo, siendo imparcial, si esa fuera la única manera que yo encontrara para que todos sobrevivan a la mirada de \"Él\"... Yo también tomaría la misma decisión. En ese sentido, no hay mucha diferencia entre ella y yo."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Charlas: Sobre Thais"
  },
  Voice_95433_UnlockDesc = {
    Text = "Desbloquear después de obtener el despertador\"thais\""
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Tiene un tacto excelente, parece que el arma está bien mantenida."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "Yo soy el fuego, la llama, el caos que arde eternamente... Los llevaré a todos... a casa..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_95435_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "La torre gótica de aquí desprende un aroma clásico, y también hay un olor único en este Despertado que nunca antes había percibido: una fragancia de los muertos mezclada con un toque de vitalidad humana. Realmente... me dan ganas de probarlo."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Charla·Sobre Misaga"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "A quien busca la muerte, cumpliré su deseo."
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "Exaltar · Dos"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "Ya no puedo esperar para comenzar."
  },
  Voice_96363_AwakerVoiceTitle = {Text = "Activar"},
  Voice_96364_AwakerVoiceContent = {
    Text = "¿Palpitó tu corazón, verdad? Ven, mi querido huésped, sé mi invitado de honor y acompáñame a disfrutar de este banquete. Permíteme guiarte para saborear juntos cada sutil vestigio de los espíritus."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Iluminar·Florecer"
  },
  Voice_96364_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 15 desbloqueado"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Shh, no hables. Escucha junto conmigo las voces de los muertos."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·uno"
  },
  Voice_96365_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 2 desbloquea"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "La belleza eterna es nuestra fe. Aplicar lentamente la disolución sobre los vivos, borrar todas las huellas de su existencia... para la vida, esto es una tortura pura y cruel."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Charlas·Sobre la crisis"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Al igual que yo, Pickman también busca el arte eterno, deberíamos haber sido los mejores amigos. Pero él cree que comer es un acto que destruye la eternidad, una visión del arte realmente demasiado estrecha."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Charla·Sobre Pickman"
  },
  Voice_96367_UnlockDesc = {
    Text = "Desbloqueado al obtener el Despertado\"Pickman\""
  },
  Voice_96368_AwakerVoiceContent = {Text = "¡Ja!"},
  Voice_96368_AwakerVoiceTitle = {Text = "Golpe·Uno"},
  Voice_96369_AwakerVoiceContent = {
    Text = "Cualquier adjetivo resulta insuficiente para describir el aroma embriagador que emanas. Es a la vez ácido y rico como el posgusto de un vino de Burdeos, y tan intenso y cremoso como un pastel de nata. Ah... quizás el día de tu muerte llegará a ser el día más importante del resto de mi vida."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Charla·Sobre el Guardián del Secreto"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "He visto una escena del crimen: un hombre que poco a poco le cortaba la piel, las uñas, las manos y los pies a una joven, pero al mismo tiempo no dejaba de curarla. No quería que muriera, pero tampoco deseaba que viviera. Por supuesto que no podía otorgarle una muerte tranquila, así que solo hice que experimentara una y otra vez la misma experiencia que la joven. Hace ya varios años... ¿No es justo para quien profana la muerte, verdad?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas odiadas"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "Soy el dios que rige sobre la muerte, pero no me confundas, nunca he creado la muerte. Solo sigo sus pasos y recojo el fruto maduro y abundante."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Iluminar·Visión lejana"
  },
  Voice_96371_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 1 desbloqueado"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "¿También deseas probar mi sabor, Excelencia Guardián del Secreto?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Charla·Sobre el tacto"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "¿A quién debería sentarse a la mesa hoy?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Investigación iniciada"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "Les concederé el honor de convertirse en la cena de hoy."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Investigación exitosa"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "Demasiado poco elegante."
  },
  Voice_96375_AwakerVoiceTitle = {Text = "Golpe·III"},
  Voice_96376_AwakerVoiceContent = {
    Text = "Traeré un descanso puro."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "Habilidad·Uno"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "Antes de cada alimento, mantengo un diálogo con los espíritus de los fallecidos. Para ellos, ser consumidos y saboreados con dedicación significa la prolongación de la vida y su último esplendor. Así como nosotros anhelamos a ellos, también ellos anhelan a nosotros."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·tres"
  },
  Voice_96377_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 6 desbloquea"
  },
  Voice_96378_AwakerVoiceContent = {Text = "Silencio."},
  Voice_96378_AwakerVoiceTitle = {
    Text = "Golpe·Cuatro"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "¡Desaparece en la sombra!"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "Será mejor que mantengamos distancia."
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "Defensa · I"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "¡Desaparece en la sombra!"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "Carta de habilidad·Cuatro"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "¿Por qué estás tan precavido conmigo? No deberías ni necesitas alarmarte. Morder a los vivos va en contra de mi estética."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Charla·Sobre la comida"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "A quien busca la muerte, cumpliré su deseo."
  },
  Voice_96383_AwakerVoiceTitle = {Text = "Exaltar"},
  Voice_96384_AwakerVoiceContent = {
    Text = "Demasiado poco elegante."
  },
  Voice_96384_AwakerVoiceTitle = {Text = "Golpe·1"},
  Voice_96385_AwakerVoiceContent = {Text = "Cuidado."},
  Voice_96385_AwakerVoiceTitle = {
    Text = "Defensa·II"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "Aunque el entusiasmo de esa señorita es realmente conmovedor, su olor desprende un aroma húmedo que parece haberse fermentado demasiado. Incluso cuando ella insiste una y otra vez en que lo pruebe, francamente no es de mi agrado, lo cual resulta bastante embarazoso."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Chat·Sobre Leigh"
  },
  Voice_96386_UnlockDesc = {
    Text = "Desbloquea después de obtener el despertador \"Leigh\""
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "¿Sabías que cada vida que se va deja un eco prolongado? Cada uno tiene un tono y una altura diferentes, se va alargando poco a poco desde el momento de la muerte, hasta que finalmente se disipa entre el cielo y la tierra, como un llamado semejante a un suspiro."
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·dos"
  },
  Voice_96387_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 4 desbloquea"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "No te preocupes, Excelentísimo Guardián del Secreto, estaré siempre a tu lado hasta el día en que tu vida llegue inevitablemente a su fin. En ese momento, sin duda consumiré tu cuerpo por completo con la ceremonia más solemne, y conservaré tu alma para siempre dentro de mi cuerpo."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cinco"
  },
  Voice_96388_UnlockDesc = {
    Text = "El nivel de tasa de afinidad alcanza 10 desbloquea"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "¿No puedes oler tu propio aroma? Qué verdadera lástima, te estás perdiendo el más dulce, el más... ¡Oh! ¿Por qué te alejas?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Tasa de afinidad·cuatro"
  },
  Voice_96389_UnlockDesc = {
    Text = "El nivel de afinidad alcanza 8 y se desbloquea"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "Ya puedo ver más muerte, el paisaje del más allá, cada vez más claro..."
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Gana Impulso·Tres"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Entrégame tu cuerpo, déjame saborearte bien: cada gota de sangre, cada trozo de carne, cada hueso."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "Sobreexaltación"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "Los ingredientes diferentes requieren preparaciones distintas. Las vísceras necesitan ser marinadas, los tendones de las piernas se prestan mejor para guisarlos, las partes ricas en grasa son adecuadas para la fermentación y el envejecimiento, y los cortes con texturas especiales pueden freírse, asarse al grill o incluso utilizarse para hacer gelatinas de carne con formas elegantes. Todo esto requiere una selección cuidadosa. Por supuesto, preservar y resaltar el sabor natural de los ingredientes es una muestra esencial de respeto."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Iluminar: Perspectiva"
  },
  Voice_96392_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 7 desbloqueado"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "Esto será un poco frío."
  },
  Voice_96393_AwakerVoiceTitle = {Text = "Golpe·II"},
  Voice_96394_AwakerVoiceContent = {
    Text = "La combinación de los platos también requiere un gran cuidado: ácido y dulce, crujiente y tierno, refrescante y pesado, suave y áspero, sabores progresivos y texturas contrastantes se combinan entre sí, ofreciendo sensaciones diferentes al entrar en la boca, al masticar y al saborear. Este es el infinito y maravilloso placer que brinda una comida digna de tal nombre."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Iluminar·Construir"
  },
  Voice_96394_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 11 desbloqueado"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Muchas gracias por tu entusiasmo, me siento muy honrado."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Actualizar·II"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "La comida deliciosa siempre merece una espera un poco más larga."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "Investigación Detenida"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "Por supuesto que no soy ningún monstruo que coma carne cruda ni beba sangre. Disfrutar la muerte es un proceso solemne y elegante. Debes comunicarte y comprender con respeto el sabor único de cada ingrediente."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "Iluminar: Meditar"
  },
  Voice_96397_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 2 desbloqueado"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "Los muertos que han encontrado la paz son hermosos y fragantes, no por la gran diferencia que existe en sus cuerpos entre la vida y la muerte, sino por sus almas: el entendimiento que estas tienen sobre la muerte, su apego a la vida y su deseo de ser recordadas, son manjares que ansío profundamente."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "Charla·Sobre cosas favoritas"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "Ningún perfume puede compararse con la fragancia natural del cuerpo humano. Reconocer a una persona por su olor es una experiencia maravillosa."
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "Iluminar·Reflexionar"
  },
  Voice_96399_UnlockDesc = {
    Text = "Nivel de iluminar alcanzando 3 desbloqueado"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "¡Ah, qué aroma tan inolvidable... Ya no puedo esperar para recibirte en mi santuario."
  },
  Voice_96400_AwakerVoiceTitle = {Text = "Despertar"},
  Voice_96401_AwakerVoiceContent = {
    Text = "Entrégame tu cuerpo, déjame saborearte por completo: cada gota de sangre, cada trozo de carne, cada hueso."
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "Sobre-Exaltación Aliemus Estallido·II"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "Les traeré un descanso puro y limpio."
  },
  Voice_96402_AwakerVoiceTitle = {
    Text = "Habilidad·II"
  },
  Voice_96403_AwakerVoiceContent = {Text = "Silencio."},
  Voice_96403_AwakerVoiceTitle = {
    Text = "Golpe · II"
  },
  Voice_96404_AwakerVoiceContent = {
    Text = "Tu aroma fragante es realmente embriagador."
  },
  Voice_96404_AwakerVoiceTitle = {
    Text = "Gana Impulso · I"
  },
  Voice_98324_AwakerVoiceContent = {
    Text = "¡Arde en mil millones de deseos y maldades!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "Habilidad Especial · Uno"
  }
})
return Text_Voice
